-- >>>>>>>>>> supabase/migrations/v2.5_reschedule_confirmation.sql
-- ============================================================================
--  Migration v2.5 — staff-proposed reschedule needs customer confirmation
--  Run AFTER schema.sql + earlier migrations. Idempotent.
--
--  Previously, when staff rescheduled a booking, the change applied
--  immediately with no customer say in it. Now: a staff-initiated reschedule
--  only PROPOSES a new time (status='reschedule_proposed', new time held in
--  pending_date/pending_start_min/pending_end_min) — the actual date/start_min
--  /end_min stay untouched until the customer confirms, rejects (cancels), or
--  picks a different time themselves from their own dashboard.
--
--  A customer's OWN self-service reschedule is unaffected — still immediate,
--  since it's their own choice already.
-- ============================================================================

alter table public.appointments drop constraint if exists appointments_status_check;
alter table public.appointments add constraint appointments_status_check
  check (status in ('pending','confirmed','cancelled','rescheduled','completed','no_show','reschedule_proposed'));

alter table public.appointments add column if not exists pending_date date;
alter table public.appointments add column if not exists pending_start_min integer;
alter table public.appointments add column if not exists pending_end_min integer;

alter table public.appointments drop constraint if exists appointments_pending_start_min_check;
alter table public.appointments add constraint appointments_pending_start_min_check
  check (pending_start_min is null or pending_start_min between 0 and 1440);

alter table public.appointments drop constraint if exists appointments_pending_end_min_check;
alter table public.appointments add constraint appointments_pending_end_min_check
  check (pending_end_min is null or pending_end_min between 0 and 1560);

-- No RLS change needed: p_appt_update's WITH CHECK already allows an
-- anonymous (customer) caller to set status to 'cancelled' or 'rescheduled'
-- — exactly the two outcomes a confirm/reject produces — and staff already
-- have unrestricted status access via is_manager()/my_stylist_id(). The
-- guard_anonymous_appt_update trigger's blocked-fields list doesn't include
-- pending_date/pending_start_min/pending_end_min, so customers can clear
-- them when responding.


-- >>>>>>>>>> supabase/migrations/v2.6_rfm_simplify.sql
-- ============================================================================
--  Migration v2.6 — simpler, stylist-accessible customer segmentation
--  Run AFTER schema.sql + earlier migrations. Idempotent.
--
--  Two changes to get_customer_rfm_segments():
--  1. Opened to any active staff member (was manager-only) — a stylist
--     deciding who to follow up with needs this as much as the owner does.
--  2. Simplified from 6 overlapping segments down to 4 clean, actionable
--     ones. The old "نیازمند توجه" / "در خطر ریزش" split and the
--     "پتانسیل وفاداری" catch-all get merged into whichever real category
--     they're closest to — the follow-up message was the same either way.
-- ============================================================================

-- Return type differs from the earlier version (and from schema.sql on a
-- fresh install), which CREATE OR REPLACE can't change — drop first.
drop function if exists public.get_customer_rfm_segments();
create or replace function public.get_customer_rfm_segments()
returns table (
  phone text, name text, sms_opt_out boolean,
  recency_days int, frequency int, monetary bigint,
  r_score int, f_score int, m_score int,
  segment text, segment_fa text
)
language sql stable security definer set search_path = public as $fn$
  with scored as (
    select
      raw.*,
      case when raw.recency_days <= 30  then 4
           when raw.recency_days <= 60  then 3
           when raw.recency_days <= 120 then 2
           else 1 end as r_score,
      case when raw.frequency >= 8 then 4
           when raw.frequency >= 4 then 3
           when raw.frequency >= 2 then 2
           else 1 end as f_score,
      ntile(4) over (order by raw.monetary asc) as m_score
    from public.customer_rfm_raw raw
    where public.is_staff()
  )
  select
    phone, name, sms_opt_out, recency_days, frequency, monetary, r_score, f_score, m_score,
    case
      when r_score >= 3 and f_score >= 3 then 'champions'
      when r_score <= 2 and f_score >= 3 then 'at_risk'
      when r_score >= 3 and f_score < 3  then 'new'
      else 'inactive'
    end as segment,
    case
      when r_score >= 3 and f_score >= 3 then 'مشتریان وفادار'
      when r_score <= 2 and f_score >= 3 then 'در خطر ریزش'
      when r_score >= 3 and f_score < 3  then 'مشتریان جدید'
      else 'غیرفعال'
    end as segment_fa
  from scored;
$fn$;
grant execute on function public.get_customer_rfm_segments() to authenticated;


-- >>>>>>>>>> supabase/migrations/v2.9_referral_verification.sql
-- ============================================================================
--  Migration v2.9 — anti-referral-fraud (2 layers)
--  Run AFTER schema.sql + earlier migrations. Idempotent.
--
--  THE PROBLEM this closes: apply_referral() previously awarded the
--  referrer's points the instant a referral code was entered — before any
--  real appointment ever happened. Combined with the anonymous booking
--  flow, this was farmable: create a booking under a real-looking but
--  fake/burner phone number, apply a referral code, collect the points,
--  repeat. The existing "must already be a real customer" and rate-limit
--  checks raised the bar but didn't close it.
--
--  LAYER 1 — customers.name becomes immutable per phone (first non-empty
--  value wins; later bookings never overwrite it). Closes a related
--  identity-manipulation angle where a phone's on-file name could be
--  changed after the fact.
--
--  LAYER 2 — referral points move from "code entered" to "visit completed
--  AND staff verified at checkout". apply_referral() now only records the
--  referred_by relationship — no points. A new referral_verified column
--  (staff-only, defaults false) must be explicitly set true, together with
--  status='completed', before EITHER side's reward is inserted — both the
--  referrer's and the new customer's own bonus, at the same time, under the
--  same check. This is the human-in-the-loop step: front-desk staff confirm
--  the person checking out is a genuinely new customer, not a fabricated
--  one, before any points for that referral exist anywhere.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. New column
-- ----------------------------------------------------------------------------
alter table public.appointments
  add column if not exists referral_verified boolean not null default false;

-- ----------------------------------------------------------------------------
-- 2. sync_customer_from_appointment(): immutable name + gated referral award
-- ----------------------------------------------------------------------------
create or replace function public.sync_customer_from_appointment() returns trigger
language plpgsql security definer set search_path = public as $fn$
declare pts int; ref_phone text; ref_pts int;
begin
  if new.customer_phone !~ '^09[0-9]{9}$' then
    return new;
  end if;

  -- LAYER 1: name is immutable per phone once set.
  insert into public.customers (phone, name, gender, last_booking_at)
  values (new.customer_phone, new.customer_name, new.customer_gender, now())
  on conflict (phone) do update
    set name            = coalesce(nullif(public.customers.name, ''), excluded.name),
        last_booking_at = now();

  update public.campaign_targets ct
     set returned = true, returned_at = now()
   where ct.customer_phone = new.customer_phone
     and ct.returned = false
     and exists (select 1 from public.campaigns c
                  where c.id = ct.campaign_id and c.status = 'sent');

  update public.campaigns c
     set returned_count = (select count(*) from public.campaign_targets t
                            where t.campaign_id = c.id and t.returned)
   where c.status = 'sent';

  -- Visit points — unchanged from before this migration.
  if new.status = 'completed'
     and coalesce(old.status, '') <> 'completed'
     and new.points_awarded = 0 then
    select coalesce(s.loyalty_points, ls.points_per_visit) into pts
      from public.loyalty_settings ls
      left join public.services s on s.id = new.service_id
     where ls.id = 1;
    pts := coalesce(pts, 10);

    insert into public.loyalty_ledger (customer_phone, delta, reason, appointment_id)
    values (new.customer_phone, pts, 'visit', new.id);

    update public.customers
       set loyalty_points = loyalty_points + pts,
           total_visits   = total_visits + 1
     where phone = new.customer_phone;

    new.points_awarded := pts;
  end if;

  -- LAYER 2: both the referrer's AND the new customer's own referral bonus
  -- — completed + staff-verified, idempotent via a ledger existence check
  -- (guards both inserts together, since they're always written as a pair).
  if new.status = 'completed' and new.referral_verified = true then
    select referred_by into ref_phone from public.customers where phone = new.customer_phone;
    if ref_phone is not null and ref_phone <> new.customer_phone
       and not exists (select 1 from public.loyalty_ledger where reason = 'referral' and appointment_id = new.id) then
      select referral_points into ref_pts from public.loyalty_settings where id = 1;
      ref_pts := coalesce(ref_pts, 50);
      insert into public.loyalty_ledger (customer_phone, delta, reason, appointment_id) values
        (ref_phone, ref_pts, 'referral', new.id),
        (new.customer_phone, ref_pts, 'referral', new.id);
      update public.customers set loyalty_points = loyalty_points + ref_pts
       where phone in (ref_phone, new.customer_phone);
    end if;
  end if;

  return new;
end $fn$;
-- Trigger definition (BEFORE INSERT OR UPDATE) is unchanged — replacing the
-- function body is enough; no DROP/CREATE TRIGGER needed here.

-- ----------------------------------------------------------------------------
-- 3. apply_referral(): validation + relationship only, no point awarding
-- ----------------------------------------------------------------------------
create or replace function public.apply_referral(p_new_phone text, p_code text)
returns json language plpgsql security definer set search_path = public as $fn$
declare referrer record;
begin
  select * into referrer from public.customers where referral_code = upper(p_code);
  if referrer is null then return json_build_object('ok', false, 'error', 'کد معرف پیدا نشد'); end if;
  if referrer.phone = p_new_phone then return json_build_object('ok', false, 'error', 'کد معرف خودتان قابل استفاده نیست'); end if;
  if exists (select 1 from public.customers where phone = p_new_phone and referred_by is not null) then
    return json_build_object('ok', false, 'error', 'قبلاً از کد معرف استفاده کرده‌اید');
  end if;
  if not exists (select 1 from public.customers where phone = p_new_phone) then
    return json_build_object('ok', false, 'error', 'ابتدا باید یک نوبت برای این شماره ثبت شده باشد');
  end if;

  update public.customers set referred_by = referrer.phone where phone = p_new_phone;

  return json_build_object('ok', true);
end $fn$;
grant execute on function public.apply_referral(text, text) to anon, authenticated;

-- ----------------------------------------------------------------------------
-- 4. RLS: only manager/stylist can change referral_verified — anonymous
--    (customer) callers are blocked from it even on an otherwise-legal
--    cancel/reschedule update. Staff already have unrestricted field-level
--    access via p_appt_update's row-level policy, so no separate grant is
--    needed for them — only this trigger addition for the anon path.
-- ----------------------------------------------------------------------------
create or replace function public.guard_anonymous_appt_update() returns trigger
language plpgsql security definer set search_path = public as $fn$
begin
  if auth.uid() is null then
    if new.customer_phone is distinct from old.customer_phone
       or new.customer_name is distinct from old.customer_name
       or new.staff_id is distinct from old.staff_id
       or new.service_id is distinct from old.service_id
       or new.final_price is distinct from old.final_price
       or new.original_price is distinct from old.original_price
       or new.discount_type is distinct from old.discount_type
       or new.discount_value is distinct from old.discount_value
       or new.referral_verified is distinct from old.referral_verified then
      raise exception 'این تغییر برای مشتری مجاز نیست — فقط لغو یا جابه‌جایی زمان مجاز است';
    end if;
    insert into public.audit_log (event, actor, detail) values (
      'appointment_self_update', null,
      jsonb_build_object('appointment_id', new.id, 'from_status', old.status, 'to_status', new.status)
    );
  end if;
  return new;
end;
$fn$;
-- Trigger definition (BEFORE UPDATE) is unchanged — replacing the function
-- body is enough; no DROP/CREATE TRIGGER needed here.


-- >>>>>>>>>> supabase/migrations/v2.10_segment_settings.sql
-- ============================================================================
--  Migration v2.10 — configurable customer segmentation (manager-only)
--  Run AFTER schema.sql + earlier migrations. Idempotent.
--
--  Replaces the fixed R/F-score grid in get_customer_rfm_segments() with a
--  single, manager-configurable singleton (mirroring the existing
--  loyalty_settings id=1 pattern exactly) and direct threshold comparisons.
--  Recency and frequency are now computed strictly from `completed`
--  appointments (previously recency came from customers.last_booking_at,
--  which could reflect a booking that was later cancelled or no-showed).
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. customer_segment_settings — singleton, same shape as loyalty_settings
-- ----------------------------------------------------------------------------
create table if not exists public.customer_segment_settings (
  id                   int primary key default 1 check (id = 1),
  loyal_recency_days   int not null default 60  check (loyal_recency_days between 1 and 365),
  loyal_min_visits     int not null default 4   check (loyal_min_visits between 1 and 100),
  inactive_after_days  int not null default 120 check (inactive_after_days > loyal_recency_days),
  updated_at           timestamptz not null default now(),
  updated_by           uuid references auth.users(id)
);
insert into public.customer_segment_settings (id) values (1) on conflict (id) do nothing;

alter table public.customer_segment_settings enable row level security;

drop policy if exists p_segment_settings_read on public.customer_segment_settings;
create policy p_segment_settings_read on public.customer_segment_settings
  for select using (public.is_staff() or public.is_manager());

drop policy if exists p_segment_settings_write on public.customer_segment_settings;
create policy p_segment_settings_write on public.customer_segment_settings
  for update using (public.is_manager()) with check (public.is_manager());

grant select, update on public.customer_segment_settings to authenticated;

-- ----------------------------------------------------------------------------
-- 2. customer_rfm_raw — recency/frequency now computed strictly from
--    completed appointments (was: customers.last_booking_at / total_visits,
--    which could include bookings that never actually happened).
-- ----------------------------------------------------------------------------
create or replace view public.customer_rfm_raw as
select
  c.phone,
  c.name,
  c.sms_opt_out,
  coalesce(extract(day from (now() - max(a.date)))::int, 9999) as recency_days,
  count(a.id) as frequency,
  coalesce(sum(a.final_price), 0) as monetary
from public.customers c
left join public.appointments a
  on a.customer_phone = c.phone and a.status = 'completed'
group by c.phone, c.name, c.sms_opt_out;

-- ----------------------------------------------------------------------------
-- 3. get_customer_rfm_segments() — direct threshold classification, reading
--    live from customer_segment_settings. Return signature drops the old
--    r_score/f_score/m_score columns (meaningless under direct thresholds;
--    nothing in the frontend reads them) — DROP is required first since
--    CREATE OR REPLACE cannot change a function's return columns.
-- ----------------------------------------------------------------------------
drop function if exists public.get_customer_rfm_segments();

create or replace function public.get_customer_rfm_segments()
returns table (
  phone text, name text, sms_opt_out boolean,
  recency_days int, frequency int, monetary bigint,
  segment text, segment_fa text
)
language sql stable security definer set search_path = public as $fn$
  with settings as (
    select * from public.customer_segment_settings where id = 1
  )
  select
    raw.phone, raw.name, raw.sms_opt_out, raw.recency_days, raw.frequency, raw.monetary,
    case
      when raw.recency_days <= s.loyal_recency_days and raw.frequency >= s.loyal_min_visits then 'champions'
      when raw.recency_days >  s.loyal_recency_days and raw.frequency >= s.loyal_min_visits then 'at_risk'
      when raw.recency_days <= s.loyal_recency_days and raw.frequency <  s.loyal_min_visits then 'new'
      else 'inactive'
    end as segment,
    case
      when raw.recency_days <= s.loyal_recency_days and raw.frequency >= s.loyal_min_visits then 'مشتریان وفادار'
      when raw.recency_days >  s.loyal_recency_days and raw.frequency >= s.loyal_min_visits then 'در خطر ریزش'
      when raw.recency_days <= s.loyal_recency_days and raw.frequency <  s.loyal_min_visits then 'مشتریان جدید'
      else 'غیرفعال'
    end as segment_fa
  from public.customer_rfm_raw raw, settings s
  where public.is_staff();
$fn$;
grant execute on function public.get_customer_rfm_segments() to authenticated;

-- ----------------------------------------------------------------------------
-- 4. preview_customer_segment_distribution() — same classification logic
--    against HYPOTHETICAL thresholds passed as parameters, so a manager can
--    see the effect of a change before saving it. Reads live customer data
--    but never writes anything.
-- ----------------------------------------------------------------------------
create or replace function public.preview_customer_segment_distribution(
  p_recency int, p_visits int, p_inactive int
)
returns table (segment text, segment_fa text, customer_count bigint, pct numeric)
language sql stable security definer set search_path = public as $fn$
  -- p_inactive is accepted for parameter symmetry with the 3-field settings
  -- form (and to leave room for a future "hibernating beyond N days" split),
  -- but the current 4-way classification below is fully determined by the
  -- recency/visits crossover alone, matching get_customer_rfm_segments()
  -- exactly — it isn't referenced further in this query.
  with classified as (
    select
      case
        when raw.recency_days <= p_recency and raw.frequency >= p_visits then 'champions'
        when raw.recency_days >  p_recency and raw.frequency >= p_visits then 'at_risk'
        when raw.recency_days <= p_recency and raw.frequency <  p_visits then 'new'
        else 'inactive'
      end as segment
    from public.customer_rfm_raw raw
    where public.is_manager()
  ),
  totals as (select count(*) as n from classified),
  counted as (
    select segment, count(*) as customer_count
    from classified
    group by segment
  )
  select
    seg.key as segment,
    case seg.key
      when 'champions' then 'مشتریان وفادار'
      when 'at_risk'   then 'در خطر ریزش'
      when 'new'       then 'مشتریان جدید'
      else                  'غیرفعال'
    end as segment_fa,
    coalesce(counted.customer_count, 0) as customer_count,
    case when (select n from totals) = 0 then 0
         else round(coalesce(counted.customer_count, 0)::numeric / (select n from totals) * 100, 1)
    end as pct
  from (values ('champions'), ('at_risk'), ('new'), ('inactive')) as seg(key)
  left join counted on counted.segment = seg.key;
$fn$;
grant execute on function public.preview_customer_segment_distribution(int, int, int) to authenticated;


-- >>>>>>>>>> supabase/migrations/v2.11_advanced_segmentation.sql
-- ============================================================================
--  Migration v2.11 — advanced segmentation: personalized churn, VIP tiering,
--  category-level matrix
--  Run AFTER schema.sql + earlier migrations (through v2.10). Idempotent.
--
--  Three additions, all read-only analytics — no existing table's data is
--  modified, and no existing RPC's CALLERS need to change:
--
--  1. Personalized churn: get_customer_rfm_segments() now classifies
--     recency against a PER-CUSTOMER threshold (their own average gap
--     between completed visits × 1.5, floored at the salon-wide
--     loyal_recency_days setting) instead of one flat number for everyone.
--     A customer who naturally returns every ~90 days shouldn't be flagged
--     "at risk" at day 61 just because the salon default is 60.
--
--  2. VIP tiering: within the "champions" segment, customers whose total
--     completed spend is at or above the 80th percentile (among customers
--     with at least one completed visit) get is_vip = true.
--
--  3. Category matrix: a new function, get_customer_category_matrix(),
--     giving a per-customer × per-service-category view of how recently
--     they were last seen for THAT category specifically (a customer who
--     is a hair-color regular but hasn't had a facial in 8 months looks
--     very different line by line vs. as one blended average).
--
--  Backward compatibility: get_customer_rfm_segments()'s existing columns
--  (phone, name, sms_opt_out, recency_days, frequency, monetary, segment,
--  segment_fa) are unchanged in name, type, and meaning — segment still
--  returns exactly the same 4 values as before ('champions','at_risk',
--  'new','inactive'). Three columns are ADDED (avg_gap_days, personal_
--  recency_limit, is_vip); any existing caller that reads the old columns
--  by name keeps working untouched. DROP is required before CREATE OR
--  REPLACE here because Postgres cannot alter a function's return-table
--  shape in place (adding columns hits the same 42P16 "invalid table
--  definition" error as removing them would) — every aggregate below is
--  explicitly cast to the exact declared output type for the same reason
--  (count()/sum() default to bigint, avg()/percentile_cont() default to
--  numeric or double precision — left uncast, small differences between
--  what the query produces and what the RETURNS TABLE clause declares are
--  exactly what trips 42P16).
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. get_customer_rfm_segments() — personalized recency + VIP tiering
-- ----------------------------------------------------------------------------
drop function if exists public.get_customer_rfm_segments();

create or replace function public.get_customer_rfm_segments()
returns table (
  phone text, name text, sms_opt_out boolean,
  recency_days int, frequency int, monetary bigint,
  segment text, segment_fa text,
  avg_gap_days numeric, personal_recency_limit int, is_vip boolean
)
language sql stable security definer set search_path = public as $fn$
  with settings as (
    select * from public.customer_segment_settings where id = 1
  ),
  -- Gap between each customer's own consecutive completed visits (in days).
  -- date - date in Postgres yields a plain integer day count directly, no
  -- interval arithmetic/extraction needed.
  gaps as (
    select
      customer_phone,
      (date - lag(date) over (partition by customer_phone order by date))::int as gap_days
    from public.appointments
    where status = 'completed'
  ),
  avg_gaps as (
    select customer_phone, avg(gap_days)::numeric as avg_gap_days
    from gaps
    where gap_days is not null and gap_days > 0
    group by customer_phone
  ),
  -- 80th percentile of total completed spend, among customers who have at
  -- least one completed visit (frequency = 0 customers would just drag an
  -- all-customer percentile down toward zero without meaning anything).
  monetary_p80 as (
    select percentile_cont(0.80) within group (order by monetary)::bigint as p80
    from public.customer_rfm_raw
    where frequency > 0
  ),
  scored as (
    select
      raw.*,
      ag.avg_gap_days,
      case
        when coalesce(ag.avg_gap_days, 0) > 0
          then greatest(s.loyal_recency_days, round(ag.avg_gap_days * 1.5)::int)
        else s.loyal_recency_days
      end as personal_recency_limit,
      s.loyal_min_visits,
      mp.p80
    from public.customer_rfm_raw raw
    left join avg_gaps ag on ag.customer_phone = raw.phone
    cross join settings s
    cross join monetary_p80 mp
    where public.is_staff()
  )
  select
    phone, name, sms_opt_out, recency_days, frequency, monetary,
    case
      when recency_days <= personal_recency_limit and frequency >= loyal_min_visits then 'champions'
      when recency_days >  personal_recency_limit and frequency >= loyal_min_visits then 'at_risk'
      when recency_days <= personal_recency_limit and frequency <  loyal_min_visits then 'new'
      else 'inactive'
    end as segment,
    case
      when recency_days <= personal_recency_limit and frequency >= loyal_min_visits then 'مشتریان وفادار'
      when recency_days >  personal_recency_limit and frequency >= loyal_min_visits then 'در خطر ریزش'
      when recency_days <= personal_recency_limit and frequency <  loyal_min_visits then 'مشتریان جدید'
      else 'غیرفعال'
    end as segment_fa,
    avg_gap_days,
    personal_recency_limit,
    -- VIP only means anything within "champions" — being a big spender who
    -- hasn't been back in a year doesn't make someone a VIP champion, it
    -- makes them a high-value at_risk/inactive customer instead.
    (recency_days <= personal_recency_limit
       and frequency >= loyal_min_visits
       and monetary >= coalesce(p80, monetary + 1)) as is_vip
  from scored;
$fn$;
grant execute on function public.get_customer_rfm_segments() to authenticated;

-- ----------------------------------------------------------------------------
-- 2. get_customer_category_matrix() — per-customer × per-service-category
--    recency, so "hair regular who's overdue for skincare" is visible at a
--    glance instead of buried inside one blended recency number.
-- ----------------------------------------------------------------------------
create or replace function public.get_customer_category_matrix()
returns table (
  phone text, name text, category text, category_fa text,
  visit_count int, last_visit_days int, line_status text, line_status_fa text
)
language sql stable security definer set search_path = public as $fn$
  with cat_stats as (
    select
      a.customer_phone as phone,
      c.name,
      s.category,
      count(a.id)::int as visit_count,
      extract(day from (now() - max(a.date)))::int as last_visit_days
    from public.appointments a
    join public.services s on s.id = a.service_id
    join public.customers c on c.phone = a.customer_phone
    where a.status = 'completed'
    group by a.customer_phone, c.name, s.category
  )
  select
    phone, name, category,
    case category
      when 'hair'             then 'مو'
      when 'beard'             then 'ریش'
      when 'color'             then 'رنگ'
      when 'makeup'            then 'میکاپ'
      when 'nails'             then 'ناخن'
      when 'skin'              then 'پوست'
      when 'permanent_makeup'  then 'خدمات دائم'
      else category
    end as category_fa,
    visit_count, last_visit_days,
    case
      when last_visit_days <= 45 then 'active'
      when last_visit_days <= 90 then 'at_risk'
      else 'dormant'
    end as line_status,
    case
      when last_visit_days <= 45 then 'فعال در این خط خدمت'
      when last_visit_days <= 90 then 'در خطر ریزش در این خط خدمت'
      else 'غیرفعال در این خط خدمت'
    end as line_status_fa
  from cat_stats
  where public.is_staff()
  order by phone, category;
$fn$;
grant execute on function public.get_customer_category_matrix() to authenticated;


-- >>>>>>>>>> supabase/migrations/v2.13_campaign_tracking.sql
-- ============================================================================
--  Migration v2.13 — campaign conversion tracking & ROI analytics
--  Run AFTER schema.sql + earlier migrations (through v2.12). Idempotent.
--  Purely additive: two new tables, one new nullable column on an existing
--  table, one new isolated trigger, one new RPC. Nothing existing is
--  altered in behavior — sync_customer_from_appointment() (the existing
--  booking trigger) is untouched.
--
--  ATTRIBUTION MODEL: time-based (not link-based). The system has no link
--  shortener today — SMS bodies are plain template text, no URLs are
--  generated or tracked — so building one would mean a whole new redirect
--  service, well past "additive." Time-based attribution needs nothing new
--  at the infrastructure level: a booking counts as a conversion of a
--  campaign if that phone number was sent a campaign SMS within the
--  preceding 7 days. This is the standard fallback attribution model used
--  when link tracking isn't available, and it's what actually answers "did
--  this campaign make our phone ring" for a salon.
--
--  WHY A SEPARATE TRIGGER, NOT AN EXTENSION OF THE EXISTING ONE: the
--  existing sync_customer_from_appointment() already does a lot (customer
--  upsert, campaign_targets.returned flag, loyalty points, referral
--  rewards). Bolting conversion-attribution logic onto it would make an
--  already-dense BEFORE trigger denser and riskier to touch. A separate,
--  minimal AFTER INSERT trigger keeps this feature's logic fully isolated
--  — it reads sms_messages and writes campaign_conversions only, and a bug
--  in it cannot affect booking creation itself (AFTER triggers run once the
--  row is already committed to the table).
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. campaign_logs — one row per bulk send (smart-campaign or manual-
--    composer), independent of whether it went through the older
--    campaigns/campaign_targets pair (which tracks per-recipient outcomes
--    for a named campaign) — this tracks per-TEMPLATE performance across
--    every kind of send, which the older tables don't do.
-- ----------------------------------------------------------------------------
create table if not exists public.campaign_logs (
  id               text primary key default 'cl-' || substr(md5(gen_random_uuid()::text), 1, 12),
  -- Not FK-constrained: a real sms_templates.id when a manual-composer
  -- template was used, OR a synthetic key (e.g. "champions", "at_risk")
  -- for a one-click RFM smart campaign, which has no row in sms_templates.
  -- template_label is a human-readable snapshot so a title is always
  -- available for display regardless of which case this is.
  template_id      text,
  template_label   text not null default '',
  segment          text, -- RFM segment targeted, if this was a segment-based send; null for a manual/free audience
  sent_at          timestamptz not null default now(),
  total_sent       integer not null default 0,
  successful_count integer not null default 0,
  created_by       uuid references auth.users(id),
  created_at       timestamptz not null default now()
);
create index if not exists campaign_logs_template_idx on public.campaign_logs (template_id);
create index if not exists campaign_logs_sent_at_idx on public.campaign_logs (sent_at);

alter table public.campaign_logs enable row level security;
drop policy if exists p_campaign_logs_read on public.campaign_logs;
create policy p_campaign_logs_read on public.campaign_logs for select using (public.is_staff());
drop policy if exists p_campaign_logs_write on public.campaign_logs;
create policy p_campaign_logs_write on public.campaign_logs for insert with check (public.is_staff());
-- No update/delete policy — logs are append-only by design.
grant select, insert on public.campaign_logs to authenticated;

-- ----------------------------------------------------------------------------
-- 2. sms_messages gets one new nullable column, linking a send back to the
--    campaign_log it belongs to (null for confirmations/reminders/etc,
--    which aren't campaigns). This is what the attribution trigger below
--    looks up by phone number.
-- ----------------------------------------------------------------------------
alter table public.sms_messages
  add column if not exists campaign_log_id text references public.campaign_logs(id) on delete set null;

create index if not exists sms_messages_campaign_log_idx on public.sms_messages (campaign_log_id);
-- Partial index scoped to only campaign sends — this is exactly the lookup
-- the attribution trigger does on every new booking, so it needs to stay
-- fast as sms_messages grows into the tens of thousands of confirmation/
-- reminder rows that have nothing to do with campaigns.
create index if not exists sms_messages_conversion_lookup_idx
  on public.sms_messages (to_phone, sent_at desc) where campaign_log_id is not null;

-- ----------------------------------------------------------------------------
-- 3. campaign_conversions — one row per booking attributed to a campaign
--    send, written automatically by the trigger below. unique(appointment_id)
--    is the idempotency guard: a given appointment can be attributed at
--    most once, ever, no matter how many times this trigger logic runs.
-- ----------------------------------------------------------------------------
create table if not exists public.campaign_conversions (
  id               text primary key default 'cc-' || substr(md5(gen_random_uuid()::text), 1, 12),
  campaign_log_id  text not null references public.campaign_logs(id) on delete cascade,
  customer_phone   text not null,
  appointment_id   text not null references public.appointments(id) on delete cascade,
  sms_message_id   text references public.sms_messages(id) on delete set null,
  converted_at     timestamptz not null default now(),
  days_to_convert  integer not null default 0,
  unique (appointment_id)
);
create index if not exists campaign_conversions_log_idx on public.campaign_conversions (campaign_log_id);
create index if not exists campaign_conversions_phone_idx on public.campaign_conversions (customer_phone);

alter table public.campaign_conversions enable row level security;
drop policy if exists p_campaign_conversions_read on public.campaign_conversions;
create policy p_campaign_conversions_read on public.campaign_conversions for select using (public.is_staff());
-- No client insert policy: rows are written exclusively by the security-
-- definer trigger function below, which runs with elevated privilege and
-- isn't subject to this table's RLS for its own writes.
grant select on public.campaign_conversions to authenticated;

-- ----------------------------------------------------------------------------
-- 4. Attribution trigger — the ONE new trigger this migration adds to the
--    booking path. Fires AFTER INSERT (the row is already committed, so
--    nothing here can block or slow down booking creation itself), does
--    one indexed lookup, and writes at most one row.
-- ----------------------------------------------------------------------------
create or replace function public.track_campaign_conversion() returns trigger
language plpgsql security definer set search_path = public as $fn$
declare matched_sms record;
begin
  if new.customer_phone !~ '^09[0-9]{9}$' then
    return new;
  end if;

  -- Most recent campaign SMS sent to this phone in the last 7 days, if any.
  select sm.id as sms_id, sm.campaign_log_id, sm.sent_at
    into matched_sms
    from public.sms_messages sm
   where sm.to_phone = new.customer_phone
     and sm.campaign_log_id is not null
     and sm.status in ('sent', 'delivered')
     and sm.sent_at >= now() - interval '7 days'
   order by sm.sent_at desc
   limit 1;

  if matched_sms.campaign_log_id is not null then
    insert into public.campaign_conversions
      (campaign_log_id, customer_phone, appointment_id, sms_message_id, converted_at, days_to_convert)
    values (
      matched_sms.campaign_log_id, new.customer_phone, new.id, matched_sms.sms_id, now(),
      greatest(0, extract(day from (now() - matched_sms.sent_at))::int)
    )
    on conflict (appointment_id) do nothing;
  end if;

  return new;
end $fn$;

drop trigger if exists appointments_track_conversion on public.appointments;
create trigger appointments_track_conversion after insert on public.appointments
  for each row execute function public.track_campaign_conversion();

-- ----------------------------------------------------------------------------
-- 5. get_campaign_performance() — per-template conversion rate and
--    attributed revenue. Revenue is joined live from appointments.final_price
--    at query time (not snapshotted at conversion time), so a later price
--    change or completion always reflects accurately — "دقت محاسبات" over
--    a cached number that can go stale.
--
--    Performance: every join below is on an indexed key (campaign_log_id,
--    appointment_id is the appointments primary key) and the whole result
--    is a small, GROUP BY-aggregated set — one row per template, not one
--    row per message or per conversion — so this stays fast as send volume
--    grows into the thousands without needing to change shape.
-- ----------------------------------------------------------------------------
create or replace function public.get_campaign_performance(p_template_id text default null)
returns table (
  template_id text, template_label text, segment text,
  total_sent bigint, successful_count bigint,
  total_conversions bigint, conversion_rate numeric,
  attributed_revenue bigint
)
language sql stable security definer set search_path = public as $fn$
  select
    cl.template_id,
    max(cl.template_label) as template_label,
    max(cl.segment) as segment,
    sum(cl.total_sent)::bigint as total_sent,
    sum(cl.successful_count)::bigint as successful_count,
    count(distinct cc.id)::bigint as total_conversions,
    case when sum(cl.successful_count) = 0 then 0::numeric
         else round(count(distinct cc.id)::numeric / sum(cl.successful_count) * 100, 1)
    end as conversion_rate,
    coalesce(sum(a.final_price) filter (where a.status = 'completed'), 0)::bigint as attributed_revenue
  from public.campaign_logs cl
  left join public.campaign_conversions cc on cc.campaign_log_id = cl.id
  left join public.appointments a on a.id = cc.appointment_id
  where public.is_staff()
    and (p_template_id is null or cl.template_id = p_template_id)
  group by cl.template_id
  order by conversion_rate desc;
$fn$;
grant execute on function public.get_campaign_performance(text) to authenticated;


-- >>>>>>>>>> supabase/migrations/v2.14_feedback_loop.sql
-- Migration v2.14 — customer feedback loop. Idempotent.

create table if not exists public.feedbacks (
  id         text primary key default 'fb-' || substr(md5(gen_random_uuid()::text), 1, 12),
  booking_id text not null unique references public.appointments(id) on delete cascade,
  rating     int not null check (rating between 1 and 5),
  tags       text[] not null default '{}',
  comment    text not null default '',
  created_at timestamptz not null default now()
);
create index if not exists feedbacks_created_at_idx on public.feedbacks (created_at);

alter table public.feedbacks enable row level security;

-- Public insert, no login: booking_id (appointments.id, already an opaque
-- per-booking string) is the bearer token — same trust model as the
-- tracking-code lookup used elsewhere in this app. Restricted to bookings
-- that are actually completed, so a random/guessed id or an unfinished
-- booking can't be used to submit feedback. unique(booking_id) blocks a
-- second submission for the same booking.
drop policy if exists p_feedback_insert on public.feedbacks;
create policy p_feedback_insert on public.feedbacks
  for insert
  with check (
    exists (select 1 from public.appointments a where a.id = booking_id and a.status = 'completed')
  );

drop policy if exists p_feedback_read on public.feedbacks;
create policy p_feedback_read on public.feedbacks
  for select using (public.is_staff());

grant select, insert on public.feedbacks to anon, authenticated;


-- >>>>>>>>>> supabase/migrations/v2.15_stylist_access_fix.sql
-- Migration v2.15 — fix stylist unauthorized-access issues. Idempotent, no
-- data changes. Root causes found: (1) several policies used is_staff()
-- (any active user) where role-specific scoping was needed; (2) two
-- policies checked my_role()='stylist' without is_staff() (active check),
-- so a deactivated stylist account could still act; (3) a stylist's own-
-- booking UPDATE had no field-level limit — could reassign staff_id,
-- change customer_phone/name, price, discounts.

-- 1) appointments SELECT: stylist scoped to own staff_id (was: any signed-
--    in user via is_staff() through no dedicated policy — actually was
--    `using (true)`, open to everyone; anonymous access left as-is here,
--    since replacing it changes the public booking flow's data access
--    pattern, out of scope for this stylist-focused fix — flagged in
--    the summary for a follow-up).
drop policy if exists p_appt_select on public.appointments;
create policy p_appt_select on public.appointments for select using (
  public.is_manager()
  or (public.is_staff() and public.my_role() = 'stylist' and staff_id = public.my_stylist_id())
  or auth.uid() is null
);

-- 2) appointments UPDATE: add the missing active-account check to the
--    stylist branch (was my_role()='stylist' alone — a deactivated
--    stylist's still-valid session could act).
drop policy if exists p_appt_update on public.appointments;
create policy p_appt_update on public.appointments for update using (
  public.is_manager()
  or (public.is_staff() and public.my_role() = 'stylist' and staff_id = public.my_stylist_id())
  or auth.uid() is null
) with check (
  public.is_manager()
  or (public.is_staff() and public.my_role() = 'stylist' and staff_id = public.my_stylist_id())
  or (auth.uid() is null and status in ('cancelled', 'rescheduled'))
);

-- 3) Field-level lock for a stylist's own-booking updates (mirrors the
--    existing anonymous-customer lock in the same trigger): a stylist may
--    change status/pending_*/referral_verified on their own bookings, but
--    not reassign staff_id (record ownership), edit customer identity, or
--    change price/discount.
create or replace function public.guard_anonymous_appt_update() returns trigger
language plpgsql security definer set search_path = public as $fn$
begin
  if auth.uid() is null then
    if new.customer_phone is distinct from old.customer_phone
       or new.customer_name is distinct from old.customer_name
       or new.staff_id is distinct from old.staff_id
       or new.service_id is distinct from old.service_id
       or new.final_price is distinct from old.final_price
       or new.original_price is distinct from old.original_price
       or new.discount_type is distinct from old.discount_type
       or new.discount_value is distinct from old.discount_value
       or new.referral_verified is distinct from old.referral_verified then
      raise exception 'این تغییر برای مشتری مجاز نیست — فقط لغو یا جابه‌جایی زمان مجاز است';
    end if;
    insert into public.audit_log (event, actor, detail) values (
      'appointment_self_update', null,
      jsonb_build_object('appointment_id', new.id, 'from_status', old.status, 'to_status', new.status)
    );
  elsif public.my_role() = 'stylist' and not public.is_manager() then
    if new.customer_phone is distinct from old.customer_phone
       or new.customer_name is distinct from old.customer_name
       or new.staff_id is distinct from old.staff_id
       or new.service_id is distinct from old.service_id
       or new.final_price is distinct from old.final_price
       or new.original_price is distinct from old.original_price
       or new.discount_type is distinct from old.discount_type
       or new.discount_value is distinct from old.discount_value then
      raise exception 'این تغییر خارج از اختیار آرایشگر است';
    end if;
  end if;
  return new;
end;
$fn$;
-- Trigger definition unchanged — replacing the function body is enough.

-- 4) working_hours / time_offs: add the missing active-account check.
drop policy if exists p_sched_write on public.working_hours;
create policy p_sched_write on public.working_hours for all
  using (public.is_manager() or (public.is_staff() and public.my_role() = 'stylist' and staff_id = public.my_stylist_id()))
  with check (public.is_manager() or (public.is_staff() and public.my_role() = 'stylist' and staff_id = public.my_stylist_id()));

drop policy if exists p_sched_write on public.time_offs;
create policy p_sched_write on public.time_offs for all
  using (public.is_manager() or (public.is_staff() and public.my_role() = 'stylist' and staff_id = public.my_stylist_id()))
  with check (public.is_manager() or (public.is_staff() and public.my_role() = 'stylist' and staff_id = public.my_stylist_id()));

-- 5) approved_dates: which days the WHOLE SALON is open for booking is a
--    manager decision, not a per-stylist one — was is_staff() (any active
--    signed-in user, stylist included).
drop policy if exists p_sched_write on public.approved_dates;
create policy p_sched_write on public.approved_dates for all
  using (public.is_manager()) with check (public.is_manager());

-- 6) Back-office tables: was a blanket is_staff() read for every signed-in
--    user. expenses/campaigns/campaign_targets/sms_messages/sms_templates/
--    loyalty_ledger have no legitimate per-stylist scope — accounting,
--    campaigns, SMS log/templates, and the full loyalty ledger are
--    manager-only now.
do $$
declare t text;
begin
  foreach t in array array['expenses','campaigns','campaign_targets','sms_messages','sms_templates','loyalty_ledger'] loop
    execute format('drop policy if exists p_staff_read on public.%I', t);
    execute format('create policy p_staff_read on public.%I for select using (public.is_manager())', t);
  end loop;
end $$;

-- 7) customers: "essential customer info of that same booking" means a
--    stylist may look up a customer they've actually had an appointment
--    with — not the whole customer bank. (Most of the app reads customer
--    name/phone straight off the appointments row, which is already
--    correctly scoped by fix #1 above; this covers the few call sites,
--    like referral-verification at checkout, that query customers
--    directly.)
drop policy if exists p_staff_read on public.customers;
create policy p_staff_read on public.customers for select using (
  public.is_manager()
  or (
    public.is_staff() and public.my_role() = 'stylist'
    and exists (
      select 1 from public.appointments a
      where a.customer_phone = customers.phone and a.staff_id = public.my_stylist_id()
    )
  )
);

-- 8) campaign_logs / campaign_conversions: campaign analytics — manager-only.
drop policy if exists p_campaign_logs_read on public.campaign_logs;
create policy p_campaign_logs_read on public.campaign_logs for select using (public.is_manager());
drop policy if exists p_campaign_logs_write on public.campaign_logs;
create policy p_campaign_logs_write on public.campaign_logs for insert with check (public.is_manager());

drop policy if exists p_campaign_conversions_read on public.campaign_conversions;
create policy p_campaign_conversions_read on public.campaign_conversions for select using (public.is_manager());

-- 9) get_campaign_performance(): tighten from is_staff() to is_manager()
--    (campaigns are manager-only per #8; a stylist could otherwise still
--    read this RPC even without campaign_logs table access, since it's
--    security definer).
create or replace function public.get_campaign_performance(p_template_id text default null)
returns table (
  template_id text, template_label text, segment text,
  total_sent bigint, successful_count bigint,
  total_conversions bigint, conversion_rate numeric,
  attributed_revenue bigint
)
language sql stable security definer set search_path = public as $fn$
  select
    cl.template_id,
    max(cl.template_label) as template_label,
    max(cl.segment) as segment,
    sum(cl.total_sent)::bigint as total_sent,
    sum(cl.successful_count)::bigint as successful_count,
    count(distinct cc.id)::bigint as total_conversions,
    case when sum(cl.successful_count) = 0 then 0::numeric
         else round(count(distinct cc.id)::numeric / sum(cl.successful_count) * 100, 1)
    end as conversion_rate,
    coalesce(sum(a.final_price) filter (where a.status = 'completed'), 0)::bigint as attributed_revenue
  from public.campaign_logs cl
  left join public.campaign_conversions cc on cc.campaign_log_id = cl.id
  left join public.appointments a on a.id = cc.appointment_id
  where public.is_manager()
    and (p_template_id is null or cl.template_id = p_template_id)
  group by cl.template_id
  order by conversion_rate desc;
$fn$;

-- 10) Customer segmentation RPCs: reverts an earlier "open to all staff"
--     change (v2.6) — segment views expose the full customer base's
--     names/phones/spend, which is exactly the "customer bank" this
--     migration restricts. Manager-only now; the appointments-level fix
--     in #1 already gives a stylist their own customers' essential info.
create or replace function public.get_customer_rfm_segments()
returns table (
  phone text, name text, sms_opt_out boolean,
  recency_days int, frequency int, monetary bigint,
  segment text, segment_fa text,
  avg_gap_days numeric, personal_recency_limit int, is_vip boolean
)
language sql stable security definer set search_path = public as $fn$
  with settings as (
    select * from public.customer_segment_settings where id = 1
  ),
  gaps as (
    select
      customer_phone,
      (date - lag(date) over (partition by customer_phone order by date))::int as gap_days
    from public.appointments
    where status = 'completed'
  ),
  avg_gaps as (
    select customer_phone, avg(gap_days)::numeric as avg_gap_days
    from gaps
    where gap_days is not null and gap_days > 0
    group by customer_phone
  ),
  monetary_p80 as (
    select percentile_cont(0.80) within group (order by monetary)::bigint as p80
    from public.customer_rfm_raw
    where frequency > 0
  ),
  scored as (
    select
      raw.*,
      ag.avg_gap_days,
      case
        when coalesce(ag.avg_gap_days, 0) > 0
          then greatest(s.loyal_recency_days, round(ag.avg_gap_days * 1.5)::int)
        else s.loyal_recency_days
      end as personal_recency_limit,
      s.loyal_min_visits,
      mp.p80
    from public.customer_rfm_raw raw
    left join avg_gaps ag on ag.customer_phone = raw.phone
    cross join settings s
    cross join monetary_p80 mp
    where public.is_manager()
  )
  select
    phone, name, sms_opt_out, recency_days, frequency, monetary,
    case
      when recency_days <= personal_recency_limit and frequency >= loyal_min_visits then 'champions'
      when recency_days >  personal_recency_limit and frequency >= loyal_min_visits then 'at_risk'
      when recency_days <= personal_recency_limit and frequency <  loyal_min_visits then 'new'
      else 'inactive'
    end as segment,
    case
      when recency_days <= personal_recency_limit and frequency >= loyal_min_visits then 'مشتریان وفادار'
      when recency_days >  personal_recency_limit and frequency >= loyal_min_visits then 'در خطر ریزش'
      when recency_days <= personal_recency_limit and frequency <  loyal_min_visits then 'مشتریان جدید'
      else 'غیرفعال'
    end as segment_fa,
    avg_gap_days, personal_recency_limit,
    (recency_days <= personal_recency_limit
       and frequency >= loyal_min_visits
       and monetary >= coalesce(p80, monetary + 1)) as is_vip
  from scored;
$fn$;

create or replace function public.get_customer_category_matrix()
returns table (
  phone text, name text, category text, category_fa text,
  visit_count int, last_visit_days int, line_status text, line_status_fa text
)
language sql stable security definer set search_path = public as $fn$
  with cat_stats as (
    select
      a.customer_phone as phone, c.name, s.category,
      count(a.id)::int as visit_count,
      extract(day from (now() - max(a.date)))::int as last_visit_days
    from public.appointments a
    join public.services s on s.id = a.service_id
    join public.customers c on c.phone = a.customer_phone
    where a.status = 'completed'
    group by a.customer_phone, c.name, s.category
  )
  select
    phone, name, category,
    case category
      when 'hair' then 'مو' when 'beard' then 'ریش' when 'color' then 'رنگ'
      when 'makeup' then 'میکاپ' when 'nails' then 'ناخن' when 'skin' then 'پوست'
      when 'permanent_makeup' then 'خدمات دائم' else category
    end as category_fa,
    visit_count, last_visit_days,
    case when last_visit_days <= 45 then 'active' when last_visit_days <= 90 then 'at_risk' else 'dormant' end as line_status,
    case when last_visit_days <= 45 then 'فعال در این خط خدمت'
         when last_visit_days <= 90 then 'در خطر ریزش در این خط خدمت'
         else 'غیرفعال در این خط خدمت' end as line_status_fa
  from cat_stats
  where public.is_manager()
  order by phone, category;
$fn$;

create or replace function public.preview_customer_segment_distribution(
  p_recency int, p_visits int, p_inactive int
)
returns table (segment text, segment_fa text, customer_count bigint, pct numeric)
language sql stable security definer set search_path = public as $fn$
  with classified as (
    select
      case
        when raw.recency_days <= p_recency and raw.frequency >= p_visits then 'champions'
        when raw.recency_days >  p_recency and raw.frequency >= p_visits then 'at_risk'
        when raw.recency_days <= p_recency and raw.frequency <  p_visits then 'new'
        else 'inactive'
      end as segment
    from public.customer_rfm_raw raw
    where public.is_manager()
  ),
  totals as (select count(*) as n from classified),
  counted as (select segment, count(*) as customer_count from classified group by segment)
  select
    seg.key as segment,
    case seg.key when 'champions' then 'مشتریان وفادار' when 'at_risk' then 'در خطر ریزش'
                 when 'new' then 'مشتریان جدید' else 'غیرفعال' end as segment_fa,
    coalesce(counted.customer_count, 0) as customer_count,
    case when (select n from totals) = 0 then 0
         else round(coalesce(counted.customer_count, 0)::numeric / (select n from totals) * 100, 1)
    end as pct
  from (values ('champions'), ('at_risk'), ('new'), ('inactive')) as seg(key)
  left join counted on counted.segment = seg.key;
$fn$;


-- >>>>>>>>>> supabase/migrations/v2.16_public_slots_privacy.sql
-- Migration v2.16 — close anonymous PII exposure on appointments.
-- Idempotent, no data changes.
--
-- Found while fixing v2.15 (stylist access): p_appt_select still allowed
-- `auth.uid() is null` unrestricted — meaning ANY anonymous visitor to the
-- public booking page could read the full appointments table (every
-- customer's name, phone, price) via a direct Supabase client call, since
-- bootstrap() fetches the whole table with select("*") on every app load,
-- logged in or not.
--
-- Fix: the public booking flow only ever needs OCCUPIED-SLOT data (who's
-- booked when, not who they are) to compute availability. That's now
-- served by a PII-free view. A customer looking up their OWN bookings by
-- phone (the existing "داشبورد من" trust model — typing your own number
-- is what proves ownership) gets a dedicated RPC scoped to that phone
-- only. The raw table's anonymous access is removed entirely.

-- 1) PII-free slots view — id, staff_id, date, start_min, end_min,
--    buffer_minutes, status only. No customer_name/phone/price/discount.
--    A plain view (not security_invoker) runs as its owner, not the
--    querying role, so this exposes ALL rows to anon regardless of the
--    base table's RLS — that's the point, scoped by column instead of by
--    row.
-- Column list differs from the version in schema.sql on a fresh install,
-- which CREATE OR REPLACE VIEW can't rename — drop first (later migrations
-- recreate it with salon scoping).
drop view if exists public.appointments_public_slots;
create or replace view public.appointments_public_slots as
select id, staff_id, date, start_min, end_min, buffer_minutes, status
from public.appointments;

grant select on public.appointments_public_slots to anon, authenticated;

-- 2) Customer self-lookup by phone — returns full rows (with PII) but only
--    for that one phone number. Security definer so it works with no
--    session; same trust boundary the app already uses everywhere else
--    (typing your own phone = proving it's yours).
create or replace function public.get_my_bookings(p_phone text)
returns setof public.appointments
language sql stable security definer set search_path = public as $fn$
  select * from public.appointments
  where p_phone ~ '^09[0-9]{9}$' and customer_phone = p_phone
  order by date desc, start_min desc;
$fn$;
grant execute on function public.get_my_bookings(text) to anon, authenticated;

-- 3) Remove the anonymous branch from p_appt_select entirely — anonymous
--    reads now go through the view/RPC above, never the raw table.
--    Manager (full) and stylist (own rows, from v2.15) are unchanged.
drop policy if exists p_appt_select on public.appointments;
create policy p_appt_select on public.appointments for select using (
  public.is_manager()
  or (public.is_staff() and public.my_role() = 'stylist' and staff_id = public.my_stylist_id())
);


-- >>>>>>>>>> supabase/migrations/v2.18_improvements.sql
-- Migration v2.18 — implements the improvement ideas noted in v2.17:
-- rate limiting on public RPCs, a feedback/NPS stats RPC for BI, and
-- pagination limits on queries that fetch the full customer base.
-- Idempotent, no data changes.

-- ----------------------------------------------------------------------------
-- 1) Lightweight rate limiting — a small event log + a checker function.
--    Not a general-purpose limiter; scoped to the two public RPCs that are
--    reachable with no login and take a phone number as their natural key
--    (get_my_bookings: enumeration risk; apply_referral: farming risk).
--    Internal bookkeeping only — RLS enabled with no policies, so it's
--    reachable exclusively through check_rate_limit() (security definer).
-- ----------------------------------------------------------------------------
create table if not exists public.rate_limit_events (
  id bigserial primary key,
  bucket text not null,
  created_at timestamptz not null default now()
);
create index if not exists rate_limit_events_bucket_idx on public.rate_limit_events (bucket, created_at);
alter table public.rate_limit_events enable row level security;

create or replace function public.check_rate_limit(p_bucket text, p_max_calls int, p_window_minutes int)
returns boolean
language plpgsql security definer set search_path = public as $fn$
declare recent_count int;
begin
  select count(*) into recent_count from public.rate_limit_events
   where bucket = p_bucket and created_at >= now() - (p_window_minutes || ' minutes')::interval;
  if recent_count >= p_max_calls then
    return false;
  end if;
  insert into public.rate_limit_events (bucket, created_at) values (p_bucket, now());
  -- Opportunistic cleanup instead of a separate cron job — low-probability
  -- so it doesn't add latency to most calls.
  if random() < 0.01 then
    delete from public.rate_limit_events where created_at < now() - interval '1 day';
  end if;
  return true;
end;
$fn$;
grant execute on function public.check_rate_limit(text, int, int) to anon, authenticated;

-- get_my_bookings: was `language sql stable` (no side effects) — adding a
-- rate-limit check means an insert now happens on every call, so this can
-- no longer be declared stable.
create or replace function public.get_my_bookings(p_phone text)
returns setof public.appointments
language plpgsql security definer set search_path = public as $fn$
begin
  if not public.check_rate_limit('get_my_bookings:' || coalesce(p_phone, ''), 20, 10) then
    raise exception 'تعداد درخواست بیش از حد مجاز است — چند دقیقه دیگر دوباره امتحان کنید';
  end if;
  return query
    select * from public.appointments
    where p_phone ~ '^09[0-9]{9}$' and customer_phone = p_phone
    order by date desc, start_min desc;
end;
$fn$;
grant execute on function public.get_my_bookings(text) to anon, authenticated;

create or replace function public.apply_referral(p_new_phone text, p_code text)
returns json language plpgsql security definer set search_path = public as $fn$
declare referrer record;
begin
  if not public.check_rate_limit('apply_referral:' || coalesce(p_new_phone, ''), 5, 10) then
    return json_build_object('ok', false, 'error', 'تعداد درخواست بیش از حد مجاز است — چند دقیقه دیگر دوباره امتحان کنید');
  end if;

  select * into referrer from public.customers where referral_code = upper(p_code);
  if referrer is null then return json_build_object('ok', false, 'error', 'کد معرف پیدا نشد'); end if;
  if referrer.phone = p_new_phone then return json_build_object('ok', false, 'error', 'کد معرف خودتان قابل استفاده نیست'); end if;
  if exists (select 1 from public.customers where phone = p_new_phone and referred_by is not null) then
    return json_build_object('ok', false, 'error', 'قبلاً از کد معرف استفاده کرده‌اید');
  end if;
  if not exists (select 1 from public.customers where phone = p_new_phone) then
    return json_build_object('ok', false, 'error', 'ابتدا باید یک نوبت برای این شماره ثبت شده باشد');
  end if;

  update public.customers set referred_by = referrer.phone where phone = p_new_phone;

  return json_build_object('ok', true);
end $fn$;
grant execute on function public.apply_referral(text, text) to anon, authenticated;

-- ----------------------------------------------------------------------------
-- 2) Feedback stats for BI (v2.14's feedbacks table was collected but never
--    surfaced anywhere). Manager-only, matching the "salon-wide reports
--    blocked for stylist" rule from v2.15 — also tightens v2.14's original
--    read policy (is_staff()) to match, for the same reason: feedback read
--    is a quality metric across every stylist's bookings, not scoped to
--    one's own.
-- ----------------------------------------------------------------------------
drop policy if exists p_feedback_read on public.feedbacks;
create policy p_feedback_read on public.feedbacks for select using (public.is_manager());

create or replace function public.get_feedback_stats()
returns table (
  total_count bigint, avg_rating numeric,
  rating_1 bigint, rating_2 bigint, rating_3 bigint, rating_4 bigint, rating_5 bigint
)
language sql stable security definer set search_path = public as $fn$
  select
    count(*)::bigint as total_count,
    round(avg(rating)::numeric, 2) as avg_rating,
    count(*) filter (where rating = 1)::bigint as rating_1,
    count(*) filter (where rating = 2)::bigint as rating_2,
    count(*) filter (where rating = 3)::bigint as rating_3,
    count(*) filter (where rating = 4)::bigint as rating_4,
    count(*) filter (where rating = 5)::bigint as rating_5
  from public.feedbacks
  where public.is_manager();
$fn$;
grant execute on function public.get_feedback_stats() to authenticated;

-- ----------------------------------------------------------------------------
-- 3) Pagination/limits on full-customer-base reads, so these stay fast as
--    the customer list grows. 500 is a generous cap for a single salon;
--    revisit with real cursor-based pagination if a deployment ever
--    exceeds it.
-- ----------------------------------------------------------------------------
create or replace function public.get_customer_rfm_segments()
returns table (
  phone text, name text, sms_opt_out boolean,
  recency_days int, frequency int, monetary bigint,
  segment text, segment_fa text,
  avg_gap_days numeric, personal_recency_limit int, is_vip boolean
)
language sql stable security definer set search_path = public as $fn$
  with settings as (
    select * from public.customer_segment_settings where id = 1
  ),
  gaps as (
    select
      customer_phone,
      (date - lag(date) over (partition by customer_phone order by date))::int as gap_days
    from public.appointments
    where status = 'completed'
  ),
  avg_gaps as (
    select customer_phone, avg(gap_days)::numeric as avg_gap_days
    from gaps
    where gap_days is not null and gap_days > 0
    group by customer_phone
  ),
  monetary_p80 as (
    select percentile_cont(0.80) within group (order by monetary)::bigint as p80
    from public.customer_rfm_raw
    where frequency > 0
  ),
  scored as (
    select
      raw.*,
      ag.avg_gap_days,
      case
        when coalesce(ag.avg_gap_days, 0) > 0
          then greatest(s.loyal_recency_days, round(ag.avg_gap_days * 1.5)::int)
        else s.loyal_recency_days
      end as personal_recency_limit,
      s.loyal_min_visits,
      mp.p80
    from public.customer_rfm_raw raw
    left join avg_gaps ag on ag.customer_phone = raw.phone
    cross join settings s
    cross join monetary_p80 mp
    where public.is_manager()
  )
  select
    phone, name, sms_opt_out, recency_days, frequency, monetary,
    case
      when recency_days <= personal_recency_limit and frequency >= loyal_min_visits then 'champions'
      when recency_days >  personal_recency_limit and frequency >= loyal_min_visits then 'at_risk'
      when recency_days <= personal_recency_limit and frequency <  loyal_min_visits then 'new'
      else 'inactive'
    end as segment,
    case
      when recency_days <= personal_recency_limit and frequency >= loyal_min_visits then 'مشتریان وفادار'
      when recency_days >  personal_recency_limit and frequency >= loyal_min_visits then 'در خطر ریزش'
      when recency_days <= personal_recency_limit and frequency <  loyal_min_visits then 'مشتریان جدید'
      else 'غیرفعال'
    end as segment_fa,
    avg_gap_days, personal_recency_limit,
    (recency_days <= personal_recency_limit
       and frequency >= loyal_min_visits
       and monetary >= coalesce(p80, monetary + 1)) as is_vip
  from scored
  order by monetary desc
  limit 500;
$fn$;

create or replace function public.get_customer_category_matrix()
returns table (
  phone text, name text, category text, category_fa text,
  visit_count int, last_visit_days int, line_status text, line_status_fa text
)
language sql stable security definer set search_path = public as $fn$
  with cat_stats as (
    select
      a.customer_phone as phone, c.name, s.category,
      count(a.id)::int as visit_count,
      extract(day from (now() - max(a.date)))::int as last_visit_days
    from public.appointments a
    join public.services s on s.id = a.service_id
    join public.customers c on c.phone = a.customer_phone
    where a.status = 'completed'
    group by a.customer_phone, c.name, s.category
  )
  select
    phone, name, category,
    case category
      when 'hair' then 'مو' when 'beard' then 'ریش' when 'color' then 'رنگ'
      when 'makeup' then 'میکاپ' when 'nails' then 'ناخن' when 'skin' then 'پوست'
      when 'permanent_makeup' then 'خدمات دائم' else category
    end as category_fa,
    visit_count, last_visit_days,
    case when last_visit_days <= 45 then 'active' when last_visit_days <= 90 then 'at_risk' else 'dormant' end as line_status,
    case when last_visit_days <= 45 then 'فعال در این خط خدمت'
         when last_visit_days <= 90 then 'در خطر ریزش در این خط خدمت'
         else 'غیرفعال در این خط خدمت' end as line_status_fa
  from cat_stats
  where public.is_manager()
  order by phone, category
  limit 2000; -- ~500 customers × ~4 category lines each, typical upper bound
$fn$;


-- >>>>>>>>>> supabase/migrations/v2.19_secure_public_booking.sql
-- Migration v2.19 — secure public booking management. Idempotent, no data
-- changes, does not alter or replace any prior migration.
--
-- PROBLEM: phone number alone (get_my_bookings(p_phone)) acted as the only
-- proof of ownership for viewing/cancelling/rescheduling a booking — anyone
-- who knew (or guessed) a real customer's phone number could act as them.
-- Separately, p_appt_insert had `with check (true)` (anyone could insert
-- any row with any price/discount/status) and p_appt_update's anonymous
-- branch had no ownership check at all (any appointment_id could be
-- cancelled/rescheduled by anyone who knew it). Neither appointment_id nor
-- phone number is a secret.
--
-- FIX: OTP-verified ownership. A customer requests a 6-digit code (sent by
-- SMS to their own phone — the actual proof step), verifies it, and
-- receives a random 256-bit access token (well above the 128-bit
-- minimum). That token — never the phone number or appointment_id alone —
-- is what every subsequent booking-management call requires. Only a hash
-- of both the OTP and the token is ever stored; the OTP is generated and
-- returned in plaintext exactly once, to a service-role-only function
-- callable solely from the send-sms Edge Function (never from a browser),
-- which sends it by SMS and returns nothing sensitive to the caller.
--
-- Booking creation, cancellation, and rescheduling now happen through
-- SECURITY DEFINER RPCs that compute price/discount/end_min from the
-- services/loyalty tables server-side — the browser's submitted price,
-- discount, duration, or status are never trusted. A GiST exclusion
-- constraint additionally makes double-booking the same stylist's time
-- impossible at the database level, closing the race-condition window
-- between "slot looked free" and "insert happened".

-- ----------------------------------------------------------------------------
-- 0) Extension needed for the overlap-exclusion constraint below.
-- ----------------------------------------------------------------------------
create extension if not exists btree_gist;

-- ----------------------------------------------------------------------------
-- 1) OTP challenges and access tokens — hash-only, RLS enabled with no
--    policies at all (default-deny for every direct client operation;
--    reachable exclusively through the SECURITY DEFINER functions below).
-- ----------------------------------------------------------------------------
create table if not exists public.booking_otp_challenges (
  id           uuid primary key default gen_random_uuid(),
  phone        text not null,
  otp_hash     text not null,
  salt         text not null,
  attempts     int not null default 0,
  max_attempts int not null default 5,
  consumed     boolean not null default false,
  expires_at   timestamptz not null,
  created_at   timestamptz not null default now()
);
create index if not exists booking_otp_challenges_phone_idx
  on public.booking_otp_challenges (phone, created_at desc);
alter table public.booking_otp_challenges enable row level security;

create table if not exists public.booking_access_tokens (
  id          uuid primary key default gen_random_uuid(),
  token_hash  text not null unique,
  phone       text not null,
  expires_at  timestamptz not null,
  revoked     boolean not null default false,
  created_at  timestamptz not null default now()
);
create index if not exists booking_access_tokens_hash_idx
  on public.booking_access_tokens (token_hash);
alter table public.booking_access_tokens enable row level security;

-- ----------------------------------------------------------------------------
-- 2) Overlap prevention at the database level — a GiST exclusion
--    constraint, not application logic. Two active (non-cancelled) rows
--    for the same stylist on the same date can never have overlapping
--    [start_min, end_min + buffer_minutes) ranges, enforced atomically by
--    Postgres itself regardless of how many requests arrive at once.
--    Postgres does not support NOT VALID on exclusion constraints (unlike
--    CHECK/FK constraints), so creation itself is wrapped in an exception
--    handler: if a real deployment already has legacy overlapping rows,
--    this produces a warning instead of aborting the migration — no data
--    is touched or deleted either way, but the constraint won't exist
--    until an operator resolves the conflicting rows and re-runs this
--    block.
-- ----------------------------------------------------------------------------
alter table public.appointments drop constraint if exists appointments_no_overlap;
do $$
begin
  alter table public.appointments add constraint appointments_no_overlap
    exclude using gist (
      staff_id with =,
      date with =,
      int4range(start_min, end_min + buffer_minutes) with &&
    ) where (staff_id is not null and status in ('pending', 'confirmed', 'rescheduled'));
exception when others then
  raise warning 'appointments_no_overlap could not be created — likely pre-existing overlapping legacy data (no data was touched or deleted). Resolve conflicting rows and re-run this migration to add the constraint. Detail: %', sqlerrm;
end $$;

-- ----------------------------------------------------------------------------
-- 3) appointments_public_slots — drop the id column. It carried no PII, but
--    an appointment id was (until this migration) usable to cancel/
--    reschedule via the old anonymous UPDATE policy; now that ownership
--    requires a verified token instead, the id itself grants nothing, but
--    it's still removed for defense in depth (nothing in the booking flow
--    reads it from this view — start_min/end_min/staff_id/date/buffer_
--    minutes/status is all the availability calculation ever used).
-- ----------------------------------------------------------------------------
drop view if exists public.appointments_public_slots;
create view public.appointments_public_slots as
select staff_id, date, start_min, end_min, buffer_minutes, status
from public.appointments;
grant select on public.appointments_public_slots to anon, authenticated;

-- ----------------------------------------------------------------------------
-- 4) Lock down direct anonymous access to the base table completely.
--    INSERT: was `with check (true)` — anyone could insert any row with any
--    price/status. Now no anon insert policy exists at all; creation is
--    exclusively through create_public_booking() below.
--    UPDATE: the old anonymous branch let anyone who knew an appointment_id
--    cancel/reschedule it — no ownership check. Removed entirely; cancel/
--    reschedule are exclusively through the token-verified RPCs below.
--    Manager/stylist branches (from v2.15) are unchanged.
-- ----------------------------------------------------------------------------
drop policy if exists p_appt_insert on public.appointments;
create policy p_appt_insert on public.appointments for insert with check (public.is_manager() or public.is_staff());

drop policy if exists p_appt_update on public.appointments;
create policy p_appt_update on public.appointments for update using (
  public.is_manager()
  or (public.is_staff() and public.my_role() = 'stylist' and staff_id = public.my_stylist_id())
) with check (
  public.is_manager()
  or (public.is_staff() and public.my_role() = 'stylist' and staff_id = public.my_stylist_id())
);

-- Explicit base grant for authenticated (manager/stylist) — appointments
-- previously had no explicit grant anywhere in schema.sql, relying
-- entirely on Supabase's implicit default table grants. RLS above still
-- fully governs which rows are visible/writable; this just makes the
-- privilege model self-contained instead of depending on a platform
-- default. anon gets nothing here — no policy grants it direct access.
grant select, insert, update on public.appointments to authenticated;

-- guard_anonymous_appt_update's `if auth.uid() is null` branch is now dead
-- code (no policy grants anon UPDATE anymore) but harmless to leave as-is —
-- it cannot fire without a matching RLS grant, and removing it isn't
-- necessary for correctness. Left untouched to minimize the diff.

-- ----------------------------------------------------------------------------
-- 5) OTP request — service_role ONLY. This is the one place the plaintext
--    OTP exists outside a customer's own phone; it must never be callable
--    by anon/authenticated (no such grant is given), only by the send-sms
--    Edge Function's admin client.
-- ----------------------------------------------------------------------------
create or replace function public.request_booking_otp_internal(p_phone text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_otp text; v_salt text; v_hash text; v_bytes bytea;
begin
  if p_phone !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شماره نامعتبر است');
  end if;
  if not public.check_rate_limit('otp_request:' || p_phone, 5, 10) then
    return json_build_object('ok', false, 'error', 'تعداد درخواست بیش از حد مجاز است — چند دقیقه دیگر دوباره امتحان کنید');
  end if;

  -- Invalidate any still-outstanding code for this phone — only the most
  -- recently requested OTP is ever valid.
  update public.booking_otp_challenges
     set consumed = true
   where phone = p_phone and consumed = false and expires_at > now();

  v_bytes := gen_random_bytes(4);
  v_otp := lpad((
    ((get_byte(v_bytes, 0)::bigint << 24) | (get_byte(v_bytes, 1)::bigint << 16)
     | (get_byte(v_bytes, 2)::bigint << 8) | get_byte(v_bytes, 3)::bigint) % 900000 + 100000
  )::text, 6, '0');
  v_salt := encode(gen_random_bytes(16), 'hex');
  v_hash := encode(digest(v_otp || v_salt, 'sha256'), 'hex');

  insert into public.booking_otp_challenges (phone, otp_hash, salt, expires_at)
  values (p_phone, v_hash, v_salt, now() + interval '5 minutes');

  -- Opportunistic cleanup (same pattern as check_rate_limit) — otherwise
  -- this table grows unbounded forever.
  if random() < 0.01 then
    delete from public.booking_otp_challenges where expires_at < now() - interval '1 day';
  end if;

  return json_build_object('ok', true, 'otp', v_otp, 'expires_in_seconds', 300);
end;
$fn$;
revoke all on function public.request_booking_otp_internal(text) from public, anon, authenticated;
grant execute on function public.request_booking_otp_internal(text) to service_role;

-- ----------------------------------------------------------------------------
-- 6) OTP verification — anon-callable (rate-limited + attempt-limited per
--    challenge). Success consumes the challenge and issues a fresh access
--    token; only its hash is stored, the plaintext is returned exactly
--    once, to the caller who just proved phone ownership.
-- ----------------------------------------------------------------------------
create or replace function public.verify_booking_otp(p_phone text, p_otp text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_challenge record; v_hash text; v_token text; v_token_hash text;
begin
  if p_phone !~ '^09[0-9]{9}$' or p_otp !~ '^[0-9]{6}$' then
    return json_build_object('ok', false, 'error', 'ورودی نامعتبر است');
  end if;
  if not public.check_rate_limit('otp_verify:' || p_phone, 10, 10) then
    return json_build_object('ok', false, 'error', 'تعداد تلاش بیش از حد مجاز است — چند دقیقه دیگر دوباره امتحان کنید');
  end if;

  select * into v_challenge from public.booking_otp_challenges
   where phone = p_phone and consumed = false and expires_at > now()
   order by created_at desc limit 1;

  if v_challenge is null then
    return json_build_object('ok', false, 'error', 'کدی یافت نشد یا منقضی شده — دوباره درخواست کنید');
  end if;
  if v_challenge.attempts >= v_challenge.max_attempts then
    update public.booking_otp_challenges set consumed = true where id = v_challenge.id;
    return json_build_object('ok', false, 'error', 'تعداد تلاش‌های مجاز تمام شد — دوباره درخواست کنید');
  end if;

  v_hash := encode(digest(p_otp || v_challenge.salt, 'sha256'), 'hex');
  if v_hash <> v_challenge.otp_hash then
    update public.booking_otp_challenges set attempts = attempts + 1 where id = v_challenge.id;
    return json_build_object('ok', false, 'error', 'کد اشتباه است');
  end if;

  update public.booking_otp_challenges set consumed = true where id = v_challenge.id;

  v_token := encode(gen_random_bytes(32), 'hex'); -- 256 bits
  v_token_hash := encode(digest(v_token, 'sha256'), 'hex');
  insert into public.booking_access_tokens (token_hash, phone, expires_at)
  values (v_token_hash, p_phone, now() + interval '20 minutes');

  if random() < 0.01 then
    delete from public.booking_access_tokens where expires_at < now() - interval '1 day';
  end if;

  return json_build_object('ok', true, 'token', v_token, 'expires_in_seconds', 1200);
end;
$fn$;
grant execute on function public.verify_booking_otp(text, text) to anon, authenticated;

-- ----------------------------------------------------------------------------
-- 7) Token → phone resolver, shared by every token-gated RPC below.
--    Rate-limited by the token's own hash (never the raw token, and this
--    never leaks whether a token exists — mismatched/expired/revoked all
--    resolve to the same null).
-- ----------------------------------------------------------------------------
create or replace function public.resolve_booking_token(p_token text)
returns text
language plpgsql security definer set search_path = public as $fn$
declare v_hash text; v_phone text;
begin
  if p_token is null or length(p_token) < 32 then
    return null;
  end if;
  v_hash := encode(digest(p_token, 'sha256'), 'hex');
  if not public.check_rate_limit('token_use:' || v_hash, 60, 10) then
    return null;
  end if;
  select phone into v_phone from public.booking_access_tokens
   where token_hash = v_hash and revoked = false and expires_at > now();
  return v_phone;
end;
$fn$;
revoke all on function public.resolve_booking_token(text) from public, anon, authenticated;

-- ----------------------------------------------------------------------------
-- 8) Token-gated booking access — replaces get_my_bookings(phone).
-- ----------------------------------------------------------------------------
drop function if exists public.get_my_bookings(text);

create or replace function public.get_my_bookings_with_token(p_token text)
returns setof public.appointments
language plpgsql security definer set search_path = public as $fn$
declare v_phone text;
begin
  v_phone := public.resolve_booking_token(p_token);
  if v_phone is null then
    return;
  end if;
  return query
    select * from public.appointments
    where customer_phone = v_phone
    order by date desc, start_min desc;
end;
$fn$;
grant execute on function public.get_my_bookings_with_token(text) to anon, authenticated;

create or replace function public.cancel_my_booking_with_token(p_token text, p_appointment_id text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_phone text; v_owner text;
begin
  v_phone := public.resolve_booking_token(p_token);
  if v_phone is null then
    return json_build_object('ok', false, 'error', 'نشست شما منقضی شده — دوباره وارد شوید');
  end if;
  select customer_phone into v_owner from public.appointments where id = p_appointment_id;
  if v_owner is null or v_owner <> v_phone then
    return json_build_object('ok', false, 'error', 'این نوبت متعلق به شما نیست');
  end if;
  update public.appointments set status = 'cancelled' where id = p_appointment_id;
  return json_build_object('ok', true);
end;
$fn$;
grant execute on function public.cancel_my_booking_with_token(text, text) to anon, authenticated;

create or replace function public.reschedule_my_booking_with_token(
  p_token text, p_appointment_id text, p_new_date date, p_new_start_min int
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_phone text; v_appt record; v_svc record;
  v_new_end int; v_app_dow int; v_wh record; v_wh_start int; v_wh_end int;
begin
  v_phone := public.resolve_booking_token(p_token);
  if v_phone is null then
    return json_build_object('ok', false, 'error', 'نشست شما منقضی شده — دوباره وارد شوید');
  end if;

  select * into v_appt from public.appointments where id = p_appointment_id;
  if v_appt is null or v_appt.customer_phone <> v_phone then
    return json_build_object('ok', false, 'error', 'این نوبت متعلق به شما نیست');
  end if;
  if p_new_date < current_date then
    return json_build_object('ok', false, 'error', 'تاریخ گذشته قابل انتخاب نیست');
  end if;
  if not exists (select 1 from public.approved_dates where date = p_new_date) then
    return json_build_object('ok', false, 'error', 'این روز برای رزرو باز نشده است');
  end if;

  select * into v_svc from public.services where id = v_appt.service_id;
  if v_svc is null then
    return json_build_object('ok', false, 'error', 'خدمت مرتبط با این نوبت یافت نشد');
  end if;
  v_new_end := p_new_start_min + v_svc.duration_minutes;

  -- Postgres dow: 0=Sunday..6=Saturday; this app's day_of_week: 0=Saturday..6=Friday.
  v_app_dow := (extract(dow from p_new_date)::int + 1) % 7;
  select * into v_wh from public.working_hours
   where day_of_week = v_app_dow and staff_id = v_appt.staff_id;
  if v_wh is null then
    select * into v_wh from public.working_hours
     where day_of_week = v_app_dow and staff_id is null;
  end if;
  if v_wh is null or v_wh.is_closed then
    return json_build_object('ok', false, 'error', 'در این روز سالن یا آرایشگر تعطیل است');
  end if;
  v_wh_start := split_part(v_wh.start_time, ':', 1)::int * 60 + split_part(v_wh.start_time, ':', 2)::int;
  v_wh_end := split_part(v_wh.end_time, ':', 1)::int * 60 + split_part(v_wh.end_time, ':', 2)::int;
  if p_new_start_min < v_wh_start or v_new_end > v_wh_end then
    return json_build_object('ok', false, 'error', 'خارج از ساعات کاری است');
  end if;

  begin
    update public.appointments
       set date = p_new_date, start_min = p_new_start_min, end_min = v_new_end,
           status = 'rescheduled', pending_date = null, pending_start_min = null, pending_end_min = null
     where id = p_appointment_id;
  exception when exclusion_violation then
    return json_build_object('ok', false, 'error', 'این زمان قبلاً رزرو شده — زمان دیگری انتخاب کنید');
  end;

  return json_build_object('ok', true);
end;
$fn$;
grant execute on function public.reschedule_my_booking_with_token(text, text, date, int) to anon, authenticated;

-- Explicit revocation — the revoked column existed from the start and was
-- always checked by resolve_booking_token, but nothing ever set it,
-- so a customer's "log out" only cleared client-side state, not the
-- server-side credential. Found during post-implementation loop testing.
create or replace function public.revoke_booking_token(p_token text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_hash text;
begin
  if p_token is null or length(p_token) < 32 then
    return json_build_object('ok', true); -- nothing to do; don't leak whether a short input "exists"
  end if;
  v_hash := encode(digest(p_token, 'sha256'), 'hex');
  update public.booking_access_tokens set revoked = true where token_hash = v_hash;
  return json_build_object('ok', true);
end;
$fn$;
grant execute on function public.revoke_booking_token(text) to anon, authenticated;

-- ----------------------------------------------------------------------------
-- 9) Server-computed booking creation — price, discount, end_min, and
--    initial status are computed here, never accepted from the client.
-- ----------------------------------------------------------------------------
create or replace function public.create_public_booking(
  p_service_id text, p_staff_id text, p_date date, p_start_min int,
  p_customer_name text, p_customer_phone text, p_customer_gender text,
  p_referral_code text default null
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_svc record; v_wh record; v_app_dow int; v_wh_start int; v_wh_end int;
  v_end_min int; v_id text; v_code text; v_original bigint; v_svc_discount bigint;
  v_after_svc bigint; v_loyalty_pct int := 0; v_final bigint; v_loyalty json; v_code_bytes bytea;
begin
  if p_customer_phone !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شماره موبایل نامعتبر است');
  end if;
  if coalesce(trim(p_customer_name), '') = '' then
    return json_build_object('ok', false, 'error', 'نام لازم است');
  end if;
  if p_customer_gender not in ('female', 'male') then
    return json_build_object('ok', false, 'error', 'جنسیت نامعتبر است');
  end if;
  if not public.check_rate_limit('create_booking:' || p_customer_phone, 10, 30) then
    return json_build_object('ok', false, 'error', 'تعداد درخواست بیش از حد مجاز است — کمی بعد دوباره امتحان کنید');
  end if;
  if p_date < current_date then
    return json_build_object('ok', false, 'error', 'تاریخ گذشته قابل انتخاب نیست');
  end if;
  if not exists (select 1 from public.approved_dates where date = p_date) then
    return json_build_object('ok', false, 'error', 'این روز برای رزرو باز نشده است');
  end if;

  select * into v_svc from public.services where id = p_service_id and is_active;
  if v_svc is null then
    return json_build_object('ok', false, 'error', 'خدمت یافت نشد یا غیرفعال است');
  end if;
  if v_svc.gender <> p_customer_gender then
    return json_build_object('ok', false, 'error', 'این خدمت با جنسیت انتخابی مطابقت ندارد');
  end if;

  if p_staff_id is not null and not exists (select 1 from public.stylists where id = p_staff_id and active) then
    return json_build_object('ok', false, 'error', 'آرایشگر یافت نشد یا غیرفعال است');
  end if;

  v_app_dow := (extract(dow from p_date)::int + 1) % 7;
  select * into v_wh from public.working_hours
   where day_of_week = v_app_dow and staff_id = p_staff_id;
  if v_wh is null then
    select * into v_wh from public.working_hours
     where day_of_week = v_app_dow and staff_id is null;
  end if;
  if v_wh is null or v_wh.is_closed then
    return json_build_object('ok', false, 'error', 'در این روز سالن یا آرایشگر تعطیل است');
  end if;
  v_wh_start := split_part(v_wh.start_time, ':', 1)::int * 60 + split_part(v_wh.start_time, ':', 2)::int;
  v_wh_end := split_part(v_wh.end_time, ':', 1)::int * 60 + split_part(v_wh.end_time, ':', 2)::int;
  v_end_min := p_start_min + v_svc.duration_minutes;
  if p_start_min < v_wh_start or v_end_min > v_wh_end then
    return json_build_object('ok', false, 'error', 'خارج از ساعات کاری است');
  end if;

  -- Price: service's own discount, then the customer's current loyalty-tier
  -- discount stacked on top (same order as the client's v2.17 logic) —
  -- computed here from loyalty_settings/customers, never from client input.
  v_original := coalesce(v_svc.price, 0);
  v_svc_discount := case
    when v_svc.discount_type = 'percent' then round(v_original * v_svc.discount_value / 100.0)
    when v_svc.discount_type = 'fixed' then v_svc.discount_value
    else 0
  end;
  v_after_svc := greatest(0, v_original - v_svc_discount);
  if v_svc.price is not null then
    v_loyalty := public.customer_loyalty(p_customer_phone);
    if (v_loyalty->>'found')::boolean then
      v_loyalty_pct := coalesce((v_loyalty->>'discount_percent')::int, 0);
    end if;
  end if;
  v_final := case when v_svc.price is null then null
                  else greatest(0, v_after_svc - round(v_after_svc * v_loyalty_pct / 100.0)) end;

  v_id := 'apt-' || substr(md5(gen_random_uuid()::text), 1, 16);
  v_code_bytes := gen_random_bytes(4);
  v_code := 'MN-' || lpad((
    ((get_byte(v_code_bytes, 0)::bigint << 24) | (get_byte(v_code_bytes, 1)::bigint << 16)
     | (get_byte(v_code_bytes, 2)::bigint << 8) | get_byte(v_code_bytes, 3)::bigint) % 90000 + 10000
  )::text, 5, '0');

  begin
    insert into public.appointments (
      id, customer_name, customer_phone, customer_gender, service_id, staff_id,
      staff_name, date, start_min, end_min, buffer_minutes, status,
      tracking_code, original_price, discount_type, discount_value, discount_reason, final_price
    ) values (
      v_id, trim(p_customer_name), p_customer_phone, p_customer_gender, p_service_id, p_staff_id,
      coalesce((select name from public.stylists where id = p_staff_id), ''),
      p_date, p_start_min, v_end_min, v_svc.buffer_minutes, 'pending',
      v_code, v_original, v_svc.discount_type, v_svc.discount_value,
      case when v_loyalty_pct > 0 then v_svc.discount_reason || case when v_svc.discount_reason <> '' then ' · ' else '' end || v_loyalty_pct || '٪ تخفیف باشگاه مشتریان' else v_svc.discount_reason end,
      v_final
    );
  exception when exclusion_violation then
    return json_build_object('ok', false, 'error', 'این زمان قبلاً رزرو شده — زمان دیگری انتخاب کنید');
  end;

  if p_referral_code is not null and length(trim(p_referral_code)) > 0 then
    perform public.apply_referral(p_customer_phone, p_referral_code);
  end if;

  return json_build_object(
    'ok', true, 'id', v_id, 'tracking_code', v_code, 'final_price', v_final,
    'original_price', v_original, 'staff_name', coalesce((select name from public.stylists where id = p_staff_id), '')
  );
end;
$fn$;
grant execute on function public.create_public_booking(text, text, date, int, text, text, text, text) to anon, authenticated;


-- >>>>>>>>>> supabase/migrations/v2.20_db_only_test_mode.sql
-- Migration v2.20 — DB-only OTP test path, no Edge Function required.
-- Idempotent, no data changes, does not modify v2.19 or any earlier
-- migration.
--
-- v2.19's SMS_DRY_RUN path still requires deploying the send-sms Edge
-- Function and setting a CLI secret — real steps some testers haven't
-- gotten to yet. This adds a second, independent path that needs neither:
-- a manager flips one boolean directly in the database (one SQL line, no
-- CLI, no deploy), and the booking-management OTP flow works end-to-end
-- through direct RPC calls only.
--
-- Security posture, unchanged from v2.19's principles:
--   - Off by default (sms_test_mode = false) — an absent/default
--     configuration never enables a weaker path.
--   - Turning it on is an explicit, deliberate action by whoever controls
--     the database — never inferred from "no Edge Function deployed" or
--     any other absence.
--   - Even when on, the plaintext OTP is returned only to the same
--     caller who just requested it for their own phone — never to any
--     other user. Same trust boundary as SMS_DRY_RUN in v2.19, same rate
--     limiting, same hash-only storage, same 5-minute expiry.
--   - This does not bypass verify_booking_otp, token issuance, or any
--     ownership check anywhere else — it only replaces how the OTP gets
--     to the tester (direct RPC response instead of SMS), for this one
--     narrow, explicitly-enabled case.

-- ----------------------------------------------------------------------------
-- 1) A single settings row. Readable by anyone (it's one boolean, not
--    sensitive — knowing whether test mode is on/off grants nothing by
--    itself), writable by managers only.
-- ----------------------------------------------------------------------------
create table if not exists public.app_settings (
  id            int primary key default 1 check (id = 1),
  sms_test_mode boolean not null default false
);
insert into public.app_settings (id) values (1) on conflict (id) do nothing;

alter table public.app_settings enable row level security;
drop policy if exists p_app_settings_read on public.app_settings;
create policy p_app_settings_read on public.app_settings for select using (true);
drop policy if exists p_app_settings_write on public.app_settings;
create policy p_app_settings_write on public.app_settings for update using (public.is_manager()) with check (public.is_manager());
grant select on public.app_settings to anon, authenticated;
grant update on public.app_settings to authenticated;

-- ----------------------------------------------------------------------------
-- 2) Test-mode OTP request — callable directly by anon/authenticated (no
--    service_role needed, so no Edge Function needed), but refuses to do
--    anything unless sms_test_mode is explicitly true. Mirrors
--    request_booking_otp_internal's generation logic exactly; the only
--    difference is returning the plaintext code in the response instead
--    of handing it to an SMS-sending step.
-- ----------------------------------------------------------------------------
create or replace function public.request_booking_otp_test(p_phone text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_otp text; v_salt text; v_hash text; v_bytes bytea; v_test_mode boolean;
begin
  select sms_test_mode into v_test_mode from public.app_settings where id = 1;
  if not coalesce(v_test_mode, false) then
    return json_build_object('ok', false, 'error', 'حالت تست فعال نیست');
  end if;
  if p_phone !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شماره نامعتبر است');
  end if;
  if not public.check_rate_limit('otp_request_test:' || p_phone, 5, 10) then
    return json_build_object('ok', false, 'error', 'تعداد درخواست بیش از حد مجاز است — چند دقیقه دیگر دوباره امتحان کنید');
  end if;

  update public.booking_otp_challenges
     set consumed = true
   where phone = p_phone and consumed = false and expires_at > now();

  v_bytes := gen_random_bytes(4);
  v_otp := lpad((
    ((get_byte(v_bytes, 0)::bigint << 24) | (get_byte(v_bytes, 1)::bigint << 16)
     | (get_byte(v_bytes, 2)::bigint << 8) | get_byte(v_bytes, 3)::bigint) % 900000 + 100000
  )::text, 6, '0');
  v_salt := encode(gen_random_bytes(16), 'hex');
  v_hash := encode(digest(v_otp || v_salt, 'sha256'), 'hex');

  insert into public.booking_otp_challenges (phone, otp_hash, salt, expires_at)
  values (p_phone, v_hash, v_salt, now() + interval '5 minutes');

  if random() < 0.01 then
    delete from public.booking_otp_challenges where expires_at < now() - interval '1 day';
  end if;

  return json_build_object('ok', true, 'test_otp', v_otp, 'expires_in_seconds', 300);
end;
$fn$;
grant execute on function public.request_booking_otp_test(text) to anon, authenticated;


-- >>>>>>>>>> supabase/migrations/v2.21_schedule_grants.sql
-- Migration v2.21 — fix: stylists could not save their own working hours.
-- Idempotent, no data changes, does not modify any earlier migration.
--
-- ROOT CAUSE: working_hours, time_offs, and approved_dates never had an
-- explicit GRANT anywhere in schema.sql — they relied entirely on
-- Supabase's implicit default table privileges for anon/authenticated.
-- v2.19 already fixed this exact fragility for appointments (see that
-- migration's comments); these three tables were missed at the time.
-- On any project without Supabase's original broad default grant (e.g.
-- one that's had prior manual privilege hardening), every write —
-- including a stylist saving their own hours via the already-correct RLS
-- policy from v2.15 — fails with a bare "permission denied for table
-- working_hours", before RLS is even evaluated. Confirmed by loading the
-- real schema into a plain Postgres instance (which has no such implicit
-- default) and reproducing the exact failure as the stylist role.
--
-- The existing RLS policies (p_sched_write on working_hours/time_offs:
-- manager full access, stylist own rows only; p_sched_write on
-- approved_dates: manager only) are completely unchanged — this only adds
-- the missing base grants they depend on. anon needs SELECT on all three
-- because bootstrap() reads them for the public booking flow's
-- availability calculation, before any login.

grant select on public.working_hours to anon, authenticated;
grant insert, update, delete on public.working_hours to authenticated;

grant select on public.time_offs to anon, authenticated;
grant insert, update, delete on public.time_offs to authenticated;

grant select on public.approved_dates to anon, authenticated;
grant insert, update, delete on public.approved_dates to authenticated;


-- >>>>>>>>>> supabase/migrations/v2.22_missing_grants_fix.sql
-- Migration v2.22 — fix: stylist self-registration was completely broken,
-- and while reproducing it, a wider systemic gap was found and fixed too:
-- 13 tables across the whole schema had zero explicit grants, relying
-- entirely on Supabase's implicit default privileges. Idempotent, no data
-- changes, does not modify any earlier migration.
--
-- ROOT CAUSE: registerStylist() (src/lib/auth.js, wired up in the already
-- fully-built StylistAuthPanel UI — "ورود آرایشگر" → "ثبت‌نام") inserts a
-- row into stylists as its first step. stylists' only write policy
-- (p_mgr_write) requires is_manager(), which reads the caller's role from
-- public.users — but a person who has JUST signed up has no users row yet
-- (that row is only created in registerStylist()'s LAST step). Confirmed
-- by reproducing this exact sequence against a real Postgres instance:
-- `permission denied for table stylists`.
--
-- FIX: a narrow, additional INSERT policy for stylists, allowing a
-- self-registration row ONLY when:
--   1. the caller genuinely has no profile yet (no public.users row for
--      their auth.uid() — this can only be true once, at first
--      registration; the moment registerStylist()'s users insert
--      succeeds, this becomes permanently false for that person), and
--   2. the phone number in the row being inserted matches their own
--      authenticated identity (the local part of auth.email(), which is
--      always `${phone}@<domain>` for this app's synthetic-email auth
--      model — see phoneToEmail() in src/lib/supabase.js), so nobody can
--      use this carve-out to insert a stylist profile for a phone number
--      other than the one they just verified ownership of via Supabase
--      Auth signup.
-- This is purely additive to the existing p_mgr_write policy (RLS
-- policies for the same command are OR'd together) — managers keep their
-- full existing stylists access unchanged.

drop policy if exists p_stylists_selfreg on public.stylists;
create policy p_stylists_selfreg on public.stylists for insert
  with check (
    not exists (select 1 from public.users where id = auth.uid())
    and split_part(coalesce(auth.email(), ''), '@', 1) = phone
  );

-- ----------------------------------------------------------------------------
-- Part 2 — while reproducing the bug above, the actual failure encountered
-- first was `permission denied for table users` (users had zero explicit
-- grants at all, so even its own, already-correct RLS policies were
-- unreachable). A full audit of every table in the schema against its
-- actual grant statements found 13 tables in this same state — the same
-- class of fragility already fixed individually for appointments (v2.19)
-- and working_hours/time_offs/approved_dates (v2.21), just not caught
-- everywhere at once until now. Each grant below is derived directly from
-- that table's own existing, unchanged RLS policies (visible in
-- schema.sql) — nothing here loosens what RLS actually permits; it only
-- makes the privilege model explicit instead of depending on a platform
-- default that may not hold on every project.
-- ----------------------------------------------------------------------------

grant select on public.audit_log to authenticated;

grant select, insert, update, delete on public.campaigns to authenticated;
grant select, insert, update, delete on public.campaign_targets to authenticated;
grant select, insert, update, delete on public.customers to authenticated;
grant select, insert, update, delete on public.expenses to authenticated;
grant select, insert, update, delete on public.sms_templates to authenticated;

grant select on public.loyalty_ledger to authenticated;
grant select, insert on public.sms_messages to authenticated;

grant select on public.loyalty_settings to anon, authenticated;
grant insert, update, delete on public.loyalty_settings to authenticated;

grant select on public.services to anon, authenticated;
grant insert, update, delete on public.services to authenticated;

grant select on public.stylists to anon, authenticated;
grant insert, update, delete on public.stylists to authenticated;

grant select, insert, update, delete on public.users to authenticated;

grant select, insert on public.waitlist to anon, authenticated;
grant delete on public.waitlist to authenticated;


-- >>>>>>>>>> supabase/migrations/v2.23_segment_settings_fix.sql
-- Migration v2.23 — fix two real contradictions in customer segmentation
-- (تنظیمات دسته‌بندی مشتریان). Idempotent, no data changes, does not
-- modify any earlier migration.
--
-- CONTRADICTION 1: inactive_after_days (UI label: "روز عدم مراجعه برای
-- «غیرفعال»") was collected from the manager, validated (must be greater
-- than loyal_recency_days), and saved to customer_segment_settings — but
-- was NEVER referenced in either get_customer_rfm_segments() or
-- preview_customer_segment_distribution()'s actual classification logic.
-- "inactive" was just the leftover bucket for anyone not
-- champions/at_risk/new, entirely determined by loyal_recency_days and
-- loyal_min_visits. Changing this setting had zero effect on results —
-- confirmed directly in the SQL: preview_customer_segment_distribution
-- even had a code comment acknowledging "it isn't referenced further in
-- this query."
--
-- FIX: inactive_after_days now genuinely separates "در خطر ریزش"
-- (at_risk — lapsed, but still within the grace window, and was
-- previously loyal — worth a win-back campaign) from "غیرفعال" (inactive
-- — lapsed beyond the grace window, regardless of how loyal they were
-- before, OR was never loyal to begin with). champions/new are unchanged.
--
-- CONTRADICTION 2: get_customer_rfm_segments() computes a PERSONALIZED
-- recency threshold per customer (adjusted upward for customers whose own
-- average gap between visits is naturally longer than the salon default —
-- v2.11's "personal_recency_limit"), but preview_customer_segment_
-- distribution() classified against the FLAT p_recency parameter only,
-- with no personalization at all. This meant the preview could show
-- meaningfully different numbers than what actually happens after saving
-- (e.g. customers whose natural visit cadence is longer than the salon
-- default would be undercounted as champions in the preview, and
-- overcounted as at_risk/inactive).
--
-- FIX: preview now computes the exact same avg_gap_days-based
-- personalization as the live function, using the hypothetical
-- (p_recency, p_visits, p_inactive) parameters instead of the saved
-- settings row — so what the preview shows is what saving will produce.

create or replace function public.get_customer_rfm_segments()
returns table (
  phone text, name text, sms_opt_out boolean,
  recency_days int, frequency int, monetary bigint,
  segment text, segment_fa text,
  avg_gap_days numeric, personal_recency_limit int, is_vip boolean
)
language sql stable security definer set search_path = public as $fn$
  with settings as (
    select * from public.customer_segment_settings where id = 1
  ),
  gaps as (
    select
      customer_phone,
      (date - lag(date) over (partition by customer_phone order by date))::int as gap_days
    from public.appointments
    where status = 'completed'
  ),
  avg_gaps as (
    select customer_phone, avg(gap_days)::numeric as avg_gap_days
    from gaps
    where gap_days is not null and gap_days > 0
    group by customer_phone
  ),
  monetary_p80 as (
    select percentile_cont(0.80) within group (order by monetary)::bigint as p80
    from public.customer_rfm_raw
    where frequency > 0
  ),
  scored as (
    select
      raw.*,
      ag.avg_gap_days,
      case
        when coalesce(ag.avg_gap_days, 0) > 0
          then greatest(s.loyal_recency_days, round(ag.avg_gap_days * 1.5)::int)
        else s.loyal_recency_days
      end as personal_recency_limit,
      s.loyal_min_visits,
      s.inactive_after_days,
      mp.p80
    from public.customer_rfm_raw raw
    left join avg_gaps ag on ag.customer_phone = raw.phone
    cross join settings s
    cross join monetary_p80 mp
    where public.is_manager()
  )
  select
    phone, name, sms_opt_out, recency_days, frequency, monetary,
    case
      when recency_days <= personal_recency_limit and frequency >= loyal_min_visits then 'champions'
      when recency_days <= personal_recency_limit and frequency <  loyal_min_visits then 'new'
      when recency_days >  personal_recency_limit and recency_days <= inactive_after_days
           and frequency >= loyal_min_visits then 'at_risk'
      else 'inactive'
    end as segment,
    case
      when recency_days <= personal_recency_limit and frequency >= loyal_min_visits then 'مشتریان وفادار'
      when recency_days <= personal_recency_limit and frequency <  loyal_min_visits then 'مشتریان جدید'
      when recency_days >  personal_recency_limit and recency_days <= inactive_after_days
           and frequency >= loyal_min_visits then 'در خطر ریزش'
      else 'غیرفعال'
    end as segment_fa,
    avg_gap_days, personal_recency_limit,
    (recency_days <= personal_recency_limit
       and frequency >= loyal_min_visits
       and monetary >= coalesce(p80, monetary + 1)) as is_vip
  from scored
  order by monetary desc
  limit 500;
$fn$;

create or replace function public.preview_customer_segment_distribution(
  p_recency int, p_visits int, p_inactive int
)
returns table (segment text, segment_fa text, customer_count bigint, pct numeric)
language sql stable security definer set search_path = public as $fn$
  with gaps as (
    select
      customer_phone,
      (date - lag(date) over (partition by customer_phone order by date))::int as gap_days
    from public.appointments
    where status = 'completed'
  ),
  avg_gaps as (
    select customer_phone, avg(gap_days)::numeric as avg_gap_days
    from gaps
    where gap_days is not null and gap_days > 0
    group by customer_phone
  ),
  with_limit as (
    select
      raw.recency_days, raw.frequency,
      case
        when coalesce(ag.avg_gap_days, 0) > 0
          then greatest(p_recency, round(ag.avg_gap_days * 1.5)::int)
        else p_recency
      end as personal_limit
    from public.customer_rfm_raw raw
    left join avg_gaps ag on ag.customer_phone = raw.phone
    where public.is_manager()
  ),
  classified as (
    select
      case
        when recency_days <= personal_limit and frequency >= p_visits then 'champions'
        when recency_days <= personal_limit and frequency <  p_visits then 'new'
        when recency_days >  personal_limit and recency_days <= p_inactive
             and frequency >= p_visits then 'at_risk'
        else 'inactive'
      end as segment
    from with_limit
  ),
  totals as (select count(*) as n from classified),
  counted as (
    select segment, count(*) as customer_count
    from classified
    group by segment
  )
  select
    seg.key as segment,
    case seg.key
      when 'champions' then 'مشتریان وفادار'
      when 'at_risk'   then 'در خطر ریزش'
      when 'new'       then 'مشتریان جدید'
      else                  'غیرفعال'
    end as segment_fa,
    coalesce(counted.customer_count, 0) as customer_count,
    case when (select n from totals) = 0 then 0
         else round(coalesce(counted.customer_count, 0)::numeric / (select n from totals) * 100, 1)
    end as pct
  from (values ('champions'), ('at_risk'), ('new'), ('inactive')) as seg(key)
  left join counted on counted.segment = seg.key;
$fn$;


-- >>>>>>>>>> supabase/migrations/v2.24_multitenant_part1_schema.sql
-- ============================================================================
-- Migration v2.24 — Multi-Tenant SaaS foundation (part 1 of 3: schema)
-- ============================================================================
-- Converts this app from single-tenant to shared-schema multi-tenant,
-- using salon_id (not schema-per-tenant or database-per-tenant) — the
-- standard, proven Supabase pattern at this scale (300+ salons), and the
-- one that builds directly on top of this project's existing, heavily-
-- tested RLS architecture (v2.15 through v2.23) rather than discarding it.
--
-- SAFE MIGRATION PATTERN (expand → backfill → contract), applied to every
-- existing table so this runs against a live database with real data,
-- with zero data loss and zero downtime-causing locks from a premature
-- NOT NULL:
--   1. ALTER TABLE ... ADD COLUMN salon_id uuid  (nullable — instant, no
--      table rewrite/lock on modern Postgres)
--   2. UPDATE ... SET salon_id = <the one pre-existing salon>  (backfills
--      every row this project already has, so it becomes salon #1 —
--      nothing is deleted or reset)
--   3. ALTER TABLE ... ALTER COLUMN salon_id SET NOT NULL  (now safe,
--      every row already has a value)
--   4. add the FK constraint, composite indexes, and salon-scoped RLS
--
-- Idempotent: every statement uses IF NOT EXISTS / OR REPLACE / DROP-then-
-- CREATE for policies, and the backfill only touches rows where
-- salon_id IS NULL, so re-running this migration is a no-op the second
-- time. Does not modify any earlier migration.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1) The tenants table itself.
-- ----------------------------------------------------------------------------
create table if not exists public.salons (
  id         uuid primary key default gen_random_uuid(),
  slug       text not null unique check (slug ~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$'),
  name       text not null,
  active     boolean not null default true,
  created_at timestamptz not null default now()
);
create index if not exists salons_slug_idx on public.salons (slug) where active;

-- The one salon this project already runs as, before this migration. Every
-- existing row across every table below is backfilled to belong to this
-- salon — nothing about the current, live deployment changes behavior.
insert into public.salons (id, slug, name)
select '00000000-0000-0000-0000-000000000001'::uuid, 'default', 'آرایشگاه و سالن زیبایی مانا'
where not exists (select 1 from public.salons where id = '00000000-0000-0000-0000-000000000001'::uuid);

-- ----------------------------------------------------------------------------
-- 2) salon_id, added to every existing table — expand step (nullable).
-- ----------------------------------------------------------------------------
alter table public.users                    add column if not exists salon_id uuid;
alter table public.stylists                 add column if not exists salon_id uuid;
alter table public.services                 add column if not exists salon_id uuid;
alter table public.customers                add column if not exists salon_id uuid;
alter table public.appointments             add column if not exists salon_id uuid;
alter table public.time_offs                add column if not exists salon_id uuid;
alter table public.working_hours            add column if not exists salon_id uuid;
alter table public.approved_dates           add column if not exists salon_id uuid;
alter table public.expenses                 add column if not exists salon_id uuid;
alter table public.waitlist                 add column if not exists salon_id uuid;
alter table public.sms_templates            add column if not exists salon_id uuid;
alter table public.sms_messages             add column if not exists salon_id uuid;
alter table public.campaigns                add column if not exists salon_id uuid;
alter table public.campaign_targets         add column if not exists salon_id uuid;
alter table public.campaign_logs            add column if not exists salon_id uuid;
alter table public.campaign_conversions     add column if not exists salon_id uuid;
alter table public.loyalty_ledger           add column if not exists salon_id uuid;
alter table public.loyalty_settings         add column if not exists salon_id uuid;
alter table public.customer_segment_settings add column if not exists salon_id uuid;
alter table public.audit_log                add column if not exists salon_id uuid;
alter table public.booking_otp_challenges   add column if not exists salon_id uuid;
alter table public.booking_access_tokens    add column if not exists salon_id uuid;
alter table public.app_settings             add column if not exists salon_id uuid;
-- rate_limit_events is intentionally excluded: its bucket keys are already
-- constructed per-call (e.g. 'otp_request:<phone>') and only ever read
-- back by the exact same key within check_rate_limit() itself — adding a
-- tenant dimension here would need every existing bucket-key string
-- changed to embed salon_id too; simpler and equally correct to prefix
-- salon_id into the bucket key at each call site instead (part 3 of this
-- migration set covers the RPC changes).

-- ----------------------------------------------------------------------------
-- 3) current_salon_id() — the single choke point every RLS policy and every
--    SECURITY DEFINER RPC below calls to find "which salon is this request
--    for". Reads from the caller's own users row — the exact same pattern
--    my_role()/is_staff()/is_manager() already use (see schema.sql), so
--    this is the simplest correct option (explicitly prioritized: "سادگی
--    کد") and needs no extra Supabase Auth Hook configuration to deploy.
--
--    PERFORMANCE NOTE (flagged, not silently deferred — see the checklist
--    in the delivery notes): every RLS check below does one extra lookup
--    against public.users via this function. At 300+ salons with heavy
--    traffic, the standard next step is moving salon_id into a custom JWT
--    claim (via a Supabase Auth Hook) so this becomes a claim read with no
--    table lookup at all — a drop-in replacement for this same function
--    signature, zero call-site changes needed anywhere else.
-- ----------------------------------------------------------------------------
create or replace function public.current_salon_id() returns uuid
language sql stable security definer set search_path = public as $fn$
  select salon_id from public.users where id = auth.uid();
$fn$;
grant execute on function public.current_salon_id() to anon, authenticated;

-- ----------------------------------------------------------------------------
-- 4) Backfill — every existing row becomes part of the one pre-existing
--    salon. This is the step that guarantees zero data loss: nothing here
--    deletes, resets, or reseeds anything, it only labels existing rows.
-- ----------------------------------------------------------------------------
do $$
declare v_salon_id uuid := '00000000-0000-0000-0000-000000000001'::uuid;
begin
  update public.users                    set salon_id = v_salon_id where salon_id is null;
  update public.stylists                 set salon_id = v_salon_id where salon_id is null;
  update public.services                 set salon_id = v_salon_id where salon_id is null;
  update public.customers                set salon_id = v_salon_id where salon_id is null;
  update public.appointments             set salon_id = v_salon_id where salon_id is null;
  update public.time_offs                set salon_id = v_salon_id where salon_id is null;
  update public.working_hours            set salon_id = v_salon_id where salon_id is null;
  update public.approved_dates           set salon_id = v_salon_id where salon_id is null;
  update public.expenses                 set salon_id = v_salon_id where salon_id is null;
  update public.waitlist                 set salon_id = v_salon_id where salon_id is null;
  update public.sms_templates            set salon_id = v_salon_id where salon_id is null;
  update public.sms_messages             set salon_id = v_salon_id where salon_id is null;
  update public.campaigns                set salon_id = v_salon_id where salon_id is null;
  update public.campaign_targets         set salon_id = v_salon_id where salon_id is null;
  update public.campaign_logs            set salon_id = v_salon_id where salon_id is null;
  update public.campaign_conversions     set salon_id = v_salon_id where salon_id is null;
  update public.loyalty_ledger           set salon_id = v_salon_id where salon_id is null;
  update public.loyalty_settings         set salon_id = v_salon_id where salon_id is null;
  update public.customer_segment_settings set salon_id = v_salon_id where salon_id is null;
  update public.audit_log                set salon_id = v_salon_id where salon_id is null;
  update public.booking_otp_challenges   set salon_id = v_salon_id where salon_id is null;
  update public.booking_access_tokens    set salon_id = v_salon_id where salon_id is null;
  update public.app_settings             set salon_id = v_salon_id where salon_id is null;
end $$;

-- ----------------------------------------------------------------------------
-- 5) Contract — enforce NOT NULL now that every row has a value, and add
--    the FK relationship to salons. Wrapped per-table so one unexpected
--    NULL (which the backfill above should never leave) reports exactly
--    which table has a problem instead of aborting the whole migration
--    silently.
-- ----------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array[
    'users','stylists','services','customers','appointments','time_offs',
    'working_hours','approved_dates','expenses','waitlist','sms_templates',
    'sms_messages','campaigns','campaign_targets','campaign_logs',
    'campaign_conversions','loyalty_ledger','loyalty_settings',
    'customer_segment_settings','audit_log','booking_otp_challenges',
    'booking_access_tokens','app_settings'
  ] loop
    execute format('alter table public.%I alter column salon_id set not null', t);
    if not exists (
      select 1 from pg_constraint where conname = t || '_salon_id_fkey' and conrelid = ('public.' || t)::regclass
    ) then
      execute format(
        'alter table public.%I add constraint %I foreign key (salon_id) references public.salons (id) on delete cascade',
        t, t || '_salon_id_fkey'
      );
    end if;
  end loop;
end $$;


-- >>>>>>>>>> supabase/migrations/v2.24_multitenant_part2_keys_indexes.sql
-- ============================================================================
-- Migration v2.24 — Multi-Tenant SaaS foundation (part 2 of 3: composite
-- keys and indexes)
-- ============================================================================
-- Two tables had a business key that was only safe under single-tenancy
-- and must become composite now that the SAME phone number or calendar
-- date is legitimately independent data per salon:
--   - customers: phone was the primary key. Under multi-tenancy the same
--     phone number is a DIFFERENT customer at salon A vs salon B — the
--     real key is (salon_id, phone).
--   - approved_dates: date was the primary key (one calendar globally).
--     Each salon must be able to independently open/close the same
--     calendar date — the real key is (salon_id, date).
-- Two foreign keys point at customers(phone) and must be widened to match
-- its new composite key, or every insert into those tables would break.
-- Idempotent (checks pg_constraint/pg_indexes before altering).
-- ============================================================================

-- ----------------------------------------------------------------------------
-- customers: phone -> (salon_id, phone). Both dependent foreign keys
-- (loyalty_ledger.customer_phone, customers.referred_by) must be dropped
-- FIRST — Postgres refuses to drop a primary key that something else
-- still references — then re-added against the new composite key.
-- The whole block is skipped if the PK is already the composite key
-- (true on every run after the first), so re-running never tries to
-- drop a PK that newly-added FKs from a prior run now also depend on.
-- ----------------------------------------------------------------------------
alter table public.loyalty_ledger add column if not exists salon_id uuid;
update public.loyalty_ledger set salon_id = '00000000-0000-0000-0000-000000000001'::uuid where salon_id is null;
alter table public.loyalty_ledger alter column salon_id set not null;

do $$
declare v_is_composite boolean;
begin
  select (array_agg(attname::text order by attname) = array['phone', 'salon_id'])
    into v_is_composite
    from pg_constraint c
    join unnest(c.conkey) as k(attnum) on true
    join pg_attribute a on a.attrelid = c.conrelid and a.attnum = k.attnum
    where c.conname = 'customers_pkey' and c.conrelid = 'public.customers'::regclass
    group by c.conname;

  if not coalesce(v_is_composite, false) then
    if exists (select 1 from pg_constraint where conname = 'loyalty_ledger_customer_phone_fkey') then
      alter table public.loyalty_ledger drop constraint loyalty_ledger_customer_phone_fkey;
    end if;
    if exists (select 1 from pg_constraint where conname = 'customers_referred_by_fkey') then
      alter table public.customers drop constraint customers_referred_by_fkey;
    end if;
    alter table public.customers drop constraint customers_pkey;
    alter table public.customers add constraint customers_pkey primary key (salon_id, phone);
  end if;
end $$;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'loyalty_ledger_salon_phone_fkey') then
    alter table public.loyalty_ledger add constraint loyalty_ledger_salon_phone_fkey
      foreign key (salon_id, customer_phone) references public.customers (salon_id, phone) on delete cascade;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'customers_referred_by_salon_fkey') then
    alter table public.customers add constraint customers_referred_by_salon_fkey
      foreign key (salon_id, referred_by) references public.customers (salon_id, phone) on delete set null;
  end if;
end $$;

-- ----------------------------------------------------------------------------
-- approved_dates: date -> (salon_id, date). No dependent foreign keys
-- reference this table, so this is a straightforward key swap.
-- ----------------------------------------------------------------------------
do $$
begin
  if exists (select 1 from pg_constraint where conname = 'approved_dates_pkey' and conrelid = 'public.approved_dates'::regclass) then
    alter table public.approved_dates drop constraint approved_dates_pkey;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'approved_dates_pkey' and conrelid = 'public.approved_dates'::regclass) then
    alter table public.approved_dates add constraint approved_dates_pkey primary key (salon_id, date);
  end if;
end $$;

-- ----------------------------------------------------------------------------
-- users.phone: was globally unique; a phone number can now legitimately
-- be staff at more than one salon (each a separate auth identity — see
-- the delivery checklist for the follow-up synthetic-email limitation
-- this still has). Scope uniqueness to (salon_id, phone) instead.
-- ----------------------------------------------------------------------------
do $$
begin
  if exists (select 1 from pg_constraint where conname = 'users_phone_key') then
    alter table public.users drop constraint users_phone_key;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'users_salon_phone_key') then
    alter table public.users add constraint users_salon_phone_key unique (salon_id, phone);
  end if;
end $$;

-- working_hours: the existing "one salon-wide row per weekday" index
-- (staff_id is null) must become one-per-TENANT-per-weekday, not a single
-- global row shared by every salon.
drop index if exists working_hours_salon_uniq;
create unique index if not exists working_hours_tenant_default_uniq
  on public.working_hours (salon_id, day_of_week) where staff_id is null;

-- sms_messages: the existing idempotency key must also be scoped per
-- salon (two different salons legitimately sending an identical
-- idempotency key — e.g. both derived the same way from an
-- appointment id namespaced only within their own data — must not
-- collide with each other).
drop index if exists sms_messages_idempotency_key_uidx;
create unique index if not exists sms_messages_salon_idempotency_key_uidx
  on public.sms_messages (salon_id, idempotency_key) where idempotency_key is not null;

-- campaign_conversions: unique(appointment_id) already can't collide
-- across salons since appointment ids are already globally distinct
-- (uid()-generated) — no change needed there.

-- ----------------------------------------------------------------------------
-- Composite indexes for the hot query paths at 300+-salon scale. Every
-- one of these leads with salon_id, since every real query in this app
-- is always scoped to "the current salon" first (RLS enforces this is
-- true for every access path, not just an optimization hint).
-- ----------------------------------------------------------------------------
create index if not exists appointments_salon_date_idx        on public.appointments (salon_id, date);
create index if not exists appointments_salon_staff_date_idx  on public.appointments (salon_id, staff_id, date);
create index if not exists appointments_salon_phone_idx       on public.appointments (salon_id, customer_phone);
create index if not exists appointments_salon_status_idx      on public.appointments (salon_id, status);
create index if not exists customers_salon_idx                on public.customers (salon_id);
create index if not exists stylists_salon_idx                 on public.stylists (salon_id) where active;
create index if not exists services_salon_idx                 on public.services (salon_id) where is_active;
create index if not exists sms_messages_salon_sent_idx        on public.sms_messages (salon_id, sent_at);
create index if not exists expenses_salon_date_idx            on public.expenses (salon_id, date);
create index if not exists loyalty_ledger_salon_phone_idx     on public.loyalty_ledger (salon_id, customer_phone);
create index if not exists campaign_logs_salon_sent_idx        on public.campaign_logs (salon_id, sent_at);
create index if not exists users_salon_idx                    on public.users (salon_id);


-- >>>>>>>>>> supabase/migrations/v2.24_multitenant_part3_rls.sql
-- ============================================================================
-- Migration v2.24 — Multi-Tenant SaaS foundation (part 3 of 3: RLS + views)
-- ============================================================================
-- The security-critical part. Every policy below is DROPPED and RECREATED
-- with the exact same role logic it already had, plus one additional,
-- unconditional requirement: salon_id = current_salon_id(). This is a
-- pure AND — it can only narrow what a role could already see/do, never
-- widen it, so nothing here changes single-tenant behavior (with only one
-- salon in the database, current_salon_id() resolves to that one salon
-- for everyone, same net effect as before).
--
-- current_salon_id() now serves two different callers:
--   - Authenticated staff (managers/stylists): resolved from their OWN
--     users row — unspoofable, tied to their real login.
--   - Anonymous public visitors (the booking flow): resolved from an
--     explicit `x-salon-id` request header, set by the frontend once it
--     has resolved the salon from the URL slug (see the delivery notes
--     for exactly how/where the frontend sets this).
--
-- The header path is a correctness mechanism for public browsing, not a
-- security boundary — and it doesn't need to be one. It only ever governs
-- tables that were ALREADY globally public pre-multi-tenancy (services,
-- stylists, working hours, approved dates — a salon's public menu/hours,
-- not customer data): the isolation of actual customer/business data
-- (appointments, customers, expenses, revenue, staff accounts) never
-- depends on this header anywhere below — those policies additionally
-- require is_manager()/is_staff()/matching stylist ownership, which is
-- ALWAYS derived from the caller's own authenticated users row.
-- ============================================================================

create or replace function public.current_salon_id() returns uuid
language sql stable security definer set search_path = public as $fn$
  select coalesce(
    (select salon_id from public.users where id = auth.uid()),
    nullif(current_setting('request.headers', true)::json ->> 'x-salon-id', '')::uuid
  );
$fn$;
grant execute on function public.current_salon_id() to anon, authenticated;

-- ----------------------------------------------------------------------------
-- Public-read loop (services, stylists, working_hours, time_offs,
-- approved_dates, loyalty_settings) — was `using (true)`, now scoped to
-- the requesting salon (staff: their own; public: the x-salon-id header).
-- ----------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['services','stylists','working_hours','time_offs','approved_dates','loyalty_settings'] loop
    execute format('drop policy if exists p_read_public on public.%I', t);
    execute format('create policy p_read_public on public.%I for select using (salon_id = public.current_salon_id())', t);
  end loop;
end $$;

-- ----------------------------------------------------------------------------
-- Manager-write loop (services, stylists, expenses, campaigns,
-- campaign_targets, sms_templates, loyalty_settings, customers).
-- ----------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['services','stylists','expenses','campaigns','campaign_targets','sms_templates','loyalty_settings','customers'] loop
    execute format('drop policy if exists p_mgr_write on public.%I', t);
    execute format(
      'create policy p_mgr_write on public.%I for all using (public.is_manager() and salon_id = public.current_salon_id()) with check (public.is_manager() and salon_id = public.current_salon_id())',
      t
    );
  end loop;
end $$;

-- Stylist self-registration: unchanged phone-matches-identity check, plus
-- the new stylist must be joining the salon their own signup declared via
-- the x-salon-id header (a brand-new person has no users row yet, so the
-- users-row branch of current_salon_id() is never available to them at
-- this exact moment — the header is the only source, by construction).
drop policy if exists p_stylists_selfreg on public.stylists;
create policy p_stylists_selfreg on public.stylists for insert
  with check (
    not exists (select 1 from public.users where id = auth.uid())
    and split_part(coalesce(auth.email(), ''), '@', 1) = phone
    and salon_id = public.current_salon_id()
  );

-- ----------------------------------------------------------------------------
-- Manager-only read loop (expenses, campaigns, campaign_targets,
-- sms_messages, sms_templates, loyalty_ledger).
-- ----------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['expenses','campaigns','campaign_targets','sms_messages','sms_templates','loyalty_ledger'] loop
    execute format('drop policy if exists p_staff_read on public.%I', t);
    execute format(
      'create policy p_staff_read on public.%I for select using (public.is_manager() and salon_id = public.current_salon_id())',
      t
    );
  end loop;
end $$;

-- customers: special stylist-scoped read policy (kept exactly as it was,
-- just salon-scoped in addition).
drop policy if exists p_staff_read on public.customers;
create policy p_staff_read on public.customers for select using (
  salon_id = public.current_salon_id()
  and (
    public.is_manager()
    or exists (
      select 1 from public.appointments a
      where a.customer_phone = customers.phone
        and a.salon_id = customers.salon_id
        and a.staff_id = public.my_stylist_id()
    )
  )
);

-- ----------------------------------------------------------------------------
-- Schedule surfaces (working_hours, time_offs, approved_dates):
-- manager does anything within their salon; a stylist edits only their
-- own rows within their own salon.
-- ----------------------------------------------------------------------------
drop policy if exists p_sched_write on public.working_hours;
create policy p_sched_write on public.working_hours for all
  using (
    salon_id = public.current_salon_id()
    and (public.is_manager() or (public.is_staff() and public.my_role() = 'stylist' and staff_id = public.my_stylist_id()))
  )
  with check (
    salon_id = public.current_salon_id()
    and (public.is_manager() or (public.is_staff() and public.my_role() = 'stylist' and staff_id = public.my_stylist_id()))
  );

drop policy if exists p_sched_write on public.time_offs;
create policy p_sched_write on public.time_offs for all
  using (
    salon_id = public.current_salon_id()
    and (public.is_manager() or (public.is_staff() and public.my_role() = 'stylist' and staff_id = public.my_stylist_id()))
  )
  with check (
    salon_id = public.current_salon_id()
    and (public.is_manager() or (public.is_staff() and public.my_role() = 'stylist' and staff_id = public.my_stylist_id()))
  );

drop policy if exists p_sched_write on public.approved_dates;
create policy p_sched_write on public.approved_dates for all
  using (salon_id = public.current_salon_id() and public.is_manager())
  with check (salon_id = public.current_salon_id() and public.is_manager());

-- ----------------------------------------------------------------------------
-- appointments — select/insert/update/delete.
-- ----------------------------------------------------------------------------
drop policy if exists p_appt_select on public.appointments;
create policy p_appt_select on public.appointments for select using (
  salon_id = public.current_salon_id()
  and (
    public.is_manager()
    or (public.is_staff() and public.my_role() = 'stylist' and staff_id = public.my_stylist_id())
  )
);

drop policy if exists p_appt_insert on public.appointments;
create policy p_appt_insert on public.appointments for insert
  with check (salon_id = public.current_salon_id() and (public.is_manager() or public.is_staff()));

drop policy if exists p_appt_update on public.appointments;
create policy p_appt_update on public.appointments for update using (
  salon_id = public.current_salon_id()
  and (
    public.is_manager()
    or (public.is_staff() and public.my_role() = 'stylist' and staff_id = public.my_stylist_id())
  )
);

drop policy if exists p_appt_delete on public.appointments;
create policy p_appt_delete on public.appointments for delete
  using (salon_id = public.current_salon_id() and public.is_manager());

-- ----------------------------------------------------------------------------
-- waitlist — public insert/select (matches the public booking flow),
-- staff-only delete, all salon-scoped.
-- ----------------------------------------------------------------------------
drop policy if exists p_wait_insert on public.waitlist;
create policy p_wait_insert on public.waitlist for insert with check (salon_id = public.current_salon_id());
drop policy if exists p_wait_select on public.waitlist;
create policy p_wait_select on public.waitlist for select using (salon_id = public.current_salon_id());
drop policy if exists p_wait_delete on public.waitlist;
create policy p_wait_delete on public.waitlist for delete
  using (salon_id = public.current_salon_id() and public.is_staff());

-- ----------------------------------------------------------------------------
-- sms_messages insert (managers only, plus the Edge Function's service-role
-- path which already bypasses RLS entirely — unaffected).
-- ----------------------------------------------------------------------------
drop policy if exists p_sms_insert on public.sms_messages;
create policy p_sms_insert on public.sms_messages for insert
  with check (salon_id = public.current_salon_id() and public.is_manager());

-- ----------------------------------------------------------------------------
-- users — self-read/self-insert unchanged in spirit; manager access and
-- the read-any-user-at-my-salon branch both salon-scoped.
-- ----------------------------------------------------------------------------
drop policy if exists p_users_self on public.users;
create policy p_users_self on public.users for select using (
  id = auth.uid() or (public.is_manager() and salon_id = public.current_salon_id())
);
drop policy if exists p_users_mgr on public.users;
create policy p_users_mgr on public.users for all
  using (public.is_manager() and salon_id = public.current_salon_id())
  with check (public.is_manager() and salon_id = public.current_salon_id());
drop policy if exists p_users_selfins on public.users;
create policy p_users_selfins on public.users for insert
  with check (id = auth.uid() and salon_id = public.current_salon_id());

-- ----------------------------------------------------------------------------
-- audit_log, customer_segment_settings, campaign_logs, campaign_conversions,
-- app_settings — all manager-scoped reads/writes, now also salon-scoped.
-- ----------------------------------------------------------------------------
drop policy if exists p_audit_read on public.audit_log;
create policy p_audit_read on public.audit_log for select
  using (public.is_manager() and salon_id = public.current_salon_id());

drop policy if exists p_segment_settings_read on public.customer_segment_settings;
create policy p_segment_settings_read on public.customer_segment_settings for select
  using (public.is_manager() and salon_id = public.current_salon_id());
drop policy if exists p_segment_settings_write on public.customer_segment_settings;
create policy p_segment_settings_write on public.customer_segment_settings for all
  using (public.is_manager() and salon_id = public.current_salon_id())
  with check (public.is_manager() and salon_id = public.current_salon_id());

drop policy if exists p_campaign_logs_read on public.campaign_logs;
create policy p_campaign_logs_read on public.campaign_logs for select
  using (public.is_manager() and salon_id = public.current_salon_id());
drop policy if exists p_campaign_logs_write on public.campaign_logs;
create policy p_campaign_logs_write on public.campaign_logs for insert
  with check (public.is_manager() and salon_id = public.current_salon_id());

drop policy if exists p_campaign_conversions_read on public.campaign_conversions;
create policy p_campaign_conversions_read on public.campaign_conversions for select
  using (public.is_manager() and salon_id = public.current_salon_id());

drop policy if exists p_app_settings_read on public.app_settings;
create policy p_app_settings_read on public.app_settings for select
  using (salon_id = public.current_salon_id());
drop policy if exists p_app_settings_write on public.app_settings;
create policy p_app_settings_write on public.app_settings for update
  using (public.is_manager() and salon_id = public.current_salon_id())
  with check (public.is_manager() and salon_id = public.current_salon_id());

-- ----------------------------------------------------------------------------
-- appointments_public_slots — was completely unscoped (selected from
-- every salon's appointments with no filter at all: a real cross-tenant
-- data leak of staff_id/date/time slot availability). Now filtered to the
-- requesting salon, using the SAME current_salon_id() the rest of this
-- migration relies on (a plain function call, works the same inside a
-- view as anywhere else).
-- ----------------------------------------------------------------------------
create or replace view public.appointments_public_slots as
select staff_id, date, start_min, end_min, buffer_minutes, status
from public.appointments
where salon_id = public.current_salon_id();


-- >>>>>>>>>> supabase/migrations/v2.24_multitenant_part4_settings_trigger_fix.sql
-- ============================================================================
-- Migration v2.24 — Multi-Tenant SaaS foundation (part 4 of 4: settings
-- singletons + the sync_customer_from_appointment trigger)
-- ============================================================================
-- Found during real-Postgres testing of parts 1-3 (not discovered by code
-- review alone — this is exactly why every migration in this project gets
-- tested against a live database before delivery):
--
-- BUG A: loyalty_settings, customer_segment_settings, and app_settings
-- were each a global singleton (id int primary key default 1, check
-- id = 1) — literally impossible for a second salon to ever get its own
-- settings row, since the primary key only ever allows one row, period.
-- Fixed by re-keying all three on salon_id instead.
--
-- BUG B (blocking — breaks every single appointment write, confirmed by a
-- real "no unique or exclusion constraint matching ON CONFLICT" trigger
-- error during testing): sync_customer_from_appointment() hardcoded
-- `on conflict (phone)` for the customers upsert, `where id = 1` for both
-- loyalty_settings lookups, and phone-only matching for campaign_targets/
-- customers updates — none of which account for the new composite keys
-- or tenant boundaries from parts 1-3. A booking from a customer at
-- salon A could otherwise attribute a win-back return to salon B's
-- campaign, or use salon B's loyalty point rules, purely by phone
-- coincidence. Completely rewritten below with salon_id threaded through
-- every step.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Re-key the three settings singletons on salon_id.
-- ----------------------------------------------------------------------------
alter table public.loyalty_settings drop constraint if exists loyalty_settings_pkey;
alter table public.loyalty_settings drop constraint if exists loyalty_settings_id_check;
alter table public.loyalty_settings drop column if exists id;
alter table public.loyalty_settings add constraint loyalty_settings_pkey primary key (salon_id);

alter table public.customer_segment_settings drop constraint if exists customer_segment_settings_pkey;
alter table public.customer_segment_settings drop constraint if exists customer_segment_settings_id_check;
alter table public.customer_segment_settings drop column if exists id;
alter table public.customer_segment_settings add constraint customer_segment_settings_pkey primary key (salon_id);

alter table public.app_settings drop constraint if exists app_settings_pkey;
alter table public.app_settings drop constraint if exists app_settings_id_check;
alter table public.app_settings drop column if exists id;
alter table public.app_settings add constraint app_settings_pkey primary key (salon_id);

-- Every existing salon (in practice, just the one pre-existing salon at
-- this point) gets a settings row if it doesn't already have one —
-- covers both a fresh install and an upgrade from parts 1-3 in the same
-- transaction.
insert into public.loyalty_settings (salon_id)
select id from public.salons where id not in (select salon_id from public.loyalty_settings);
insert into public.customer_segment_settings (salon_id)
select id from public.salons where id not in (select salon_id from public.customer_segment_settings);
insert into public.app_settings (salon_id)
select id from public.salons where id not in (select salon_id from public.app_settings);

-- New salons, created after this migration, automatically get their own
-- default settings rows the moment they're created — no follow-up step
-- needed anywhere else (frontend, onboarding flow, etc.) to provision them.
create or replace function public.provision_salon_defaults() returns trigger
language plpgsql security definer set search_path = public as $fn$
begin
  insert into public.loyalty_settings (salon_id) values (new.id) on conflict (salon_id) do nothing;
  insert into public.customer_segment_settings (salon_id) values (new.id) on conflict (salon_id) do nothing;
  insert into public.app_settings (salon_id) values (new.id) on conflict (salon_id) do nothing;
  return new;
end;
$fn$;
drop trigger if exists trg_provision_salon_defaults on public.salons;
create trigger trg_provision_salon_defaults
  after insert on public.salons
  for each row execute function public.provision_salon_defaults();

-- ----------------------------------------------------------------------------
-- sync_customer_from_appointment() — full rewrite, salon_id threaded
-- through every lookup, upsert, and update.
-- ----------------------------------------------------------------------------
create or replace function public.sync_customer_from_appointment() returns trigger
language plpgsql security definer set search_path = public as $fn$
declare pts int; ref_phone text; ref_pts int;
begin
  if new.customer_phone !~ '^09[0-9]{9}$' then
    return new;
  end if;

  insert into public.customers (salon_id, phone, name, gender, last_booking_at)
  values (new.salon_id, new.customer_phone, new.customer_name, new.customer_gender, now())
  on conflict (salon_id, phone) do update
    set name            = coalesce(nullif(public.customers.name, ''), excluded.name),
        last_booking_at = now();

  -- Phase 3: a booking from a targeted customer counts as a win-back
  -- return — scoped to campaigns from the SAME salon only, so a customer
  -- returning at salon B is never attributed to salon A's campaign just
  -- because they share a phone number.
  update public.campaign_targets ct
     set returned = true, returned_at = now()
   where ct.customer_phone = new.customer_phone
     and ct.salon_id = new.salon_id
     and ct.returned = false
     and exists (select 1 from public.campaigns c
                  where c.id = ct.campaign_id and c.salon_id = new.salon_id and c.status = 'sent');

  update public.campaigns c
     set returned_count = (select count(*) from public.campaign_targets t
                            where t.campaign_id = c.id and t.returned)
   where c.salon_id = new.salon_id and c.status = 'sent';

  -- Phase 4: award points once, when the visit is actually completed —
  -- using THIS salon's own loyalty rules, never another salon's.
  if new.status = 'completed'
     and coalesce(old.status, '') <> 'completed'
     and new.points_awarded = 0 then
    select coalesce(s.loyalty_points, ls.points_per_visit) into pts
      from public.loyalty_settings ls
      left join public.services s on s.id = new.service_id and s.salon_id = new.salon_id
     where ls.salon_id = new.salon_id;
    pts := coalesce(pts, 10);

    insert into public.loyalty_ledger (salon_id, customer_phone, delta, reason, appointment_id)
    values (new.salon_id, new.customer_phone, pts, 'visit', new.id);

    update public.customers
       set loyalty_points = loyalty_points + pts,
           total_visits   = total_visits + 1
     where phone = new.customer_phone and salon_id = new.salon_id;

    new.points_awarded := pts;
  end if;

  -- Anti-fraud: both the referrer's AND the new customer's own referral
  -- bonus, scoped to the same salon throughout (referred_by lookup,
  -- loyalty_settings rules, and both loyalty_ledger inserts/updates).
  if new.status = 'completed' and new.referral_verified = true then
    select referred_by into ref_phone from public.customers
     where phone = new.customer_phone and salon_id = new.salon_id;
    if ref_phone is not null and ref_phone <> new.customer_phone
       and not exists (
         select 1 from public.loyalty_ledger
          where reason = 'referral' and appointment_id = new.id and salon_id = new.salon_id
       ) then
      select referral_points into ref_pts from public.loyalty_settings where salon_id = new.salon_id;
      ref_pts := coalesce(ref_pts, 50);
      insert into public.loyalty_ledger (salon_id, customer_phone, delta, reason, appointment_id) values
        (new.salon_id, ref_phone, ref_pts, 'referral', new.id),
        (new.salon_id, new.customer_phone, ref_pts, 'referral', new.id);
      update public.customers set loyalty_points = loyalty_points + ref_pts
       where phone in (ref_phone, new.customer_phone) and salon_id = new.salon_id;
    end if;
  end if;

  return new;
end;
$fn$;

-- ----------------------------------------------------------------------------
-- guard_anonymous_appt_update() — found broken the same way during
-- testing: its audit_log insert never set salon_id, which is now NOT
-- NULL. This trigger fires on every appointment update (self-service
-- cancel/reschedule, and every staff edit), so this was blocking, not
-- cosmetic — confirmed by a real constraint-violation error when marking
-- an appointment completed. Only the audit_log insert needed salon_id
-- added; everything else in this trigger is unchanged.
-- ----------------------------------------------------------------------------
create or replace function public.guard_anonymous_appt_update() returns trigger
language plpgsql security definer set search_path = public as $fn$
begin
  if auth.uid() is null then
    if new.customer_phone is distinct from old.customer_phone
       or new.customer_name is distinct from old.customer_name
       or new.staff_id is distinct from old.staff_id
       or new.service_id is distinct from old.service_id
       or new.final_price is distinct from old.final_price
       or new.original_price is distinct from old.original_price
       or new.discount_type is distinct from old.discount_type
       or new.discount_value is distinct from old.discount_value
       or new.referral_verified is distinct from old.referral_verified then
      raise exception 'این تغییر برای مشتری مجاز نیست — فقط لغو یا جابه‌جایی زمان مجاز است';
    end if;
    insert into public.audit_log (salon_id, event, actor, detail) values (
      new.salon_id, 'appointment_self_update', null,
      jsonb_build_object('appointment_id', new.id, 'from_status', old.status, 'to_status', new.status)
    );
  elsif public.my_role() = 'stylist' and not public.is_manager() then
    if new.customer_phone is distinct from old.customer_phone
       or new.customer_name is distinct from old.customer_name
       or new.staff_id is distinct from old.staff_id
       or new.service_id is distinct from old.service_id
       or new.final_price is distinct from old.final_price
       or new.original_price is distinct from old.original_price
       or new.discount_type is distinct from old.discount_type
       or new.discount_value is distinct from old.discount_value then
      raise exception 'این تغییر خارج از اختیار آرایشگر است';
    end if;
  end if;
  return new;
end;
$fn$;

-- ----------------------------------------------------------------------------
-- audit_role_change() — the third and last audit_log insert in the whole
-- schema with the same missing-salon_id bug (found by grepping every
-- occurrence after finding the first two by testing). Fires on users
-- table updates, so new.salon_id refers to the affected user's own salon.
-- ----------------------------------------------------------------------------
create or replace function public.audit_role_change() returns trigger
language plpgsql security definer set search_path = public as $fn$
begin
  if new.role is distinct from old.role then
    insert into public.audit_log (salon_id, event, actor, detail) values (
      new.salon_id, 'role_change', auth.uid(),
      jsonb_build_object('user_id', new.id, 'phone', new.phone, 'from_role', old.role, 'to_role', new.role)
    );
  end if;
  return new;
end;
$fn$;


-- >>>>>>>>>> supabase/migrations/v2.24_multitenant_part5_customer_rpcs.sql
-- ============================================================================
-- Migration v2.24 — Multi-Tenant SaaS foundation (part 5: customer-facing
-- RPCs — OTP/token family, booking creation, loyalty, referrals)
-- ============================================================================
-- Everything in this file was, before this migration, keyed by phone
-- number ALONE with no salon awareness at all — meaning a customer who
-- has booked at two different salons on this platform would see BOTH
-- salons' appointments merged together in "داشبورد من" at either one,
-- and a booking's price/loyalty tier could be computed from the wrong
-- salon's settings. Every function below now threads salon_id through
-- every lookup, insert, and ownership check.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- resolve_booking_token: now returns (phone, salon_id) together instead of
-- a bare phone string, so every function built on it can verify BOTH that
-- the token belongs to this phone AND that the booking being acted on
-- belongs to the SAME salon the token was issued for.
-- ----------------------------------------------------------------------------
drop function if exists public.resolve_booking_token(text);
create function public.resolve_booking_token(p_token text)
returns table (phone text, salon_id uuid)
language plpgsql security definer set search_path = public as $fn$
declare v_hash text;
begin
  if p_token is null or length(p_token) < 32 then
    return;
  end if;
  v_hash := encode(digest(p_token, 'sha256'), 'hex');
  if not public.check_rate_limit('token_use:' || v_hash, 60, 10) then
    return;
  end if;
  return query
    select t.phone, t.salon_id from public.booking_access_tokens t
     where t.token_hash = v_hash and t.revoked = false and t.expires_at > now();
end;
$fn$;
revoke all on function public.resolve_booking_token(text) from public, anon, authenticated;

-- request_booking_otp_internal: service_role only (the Edge Function's
-- admin client). Now takes the salon explicitly, since the caller here
-- has no session of its own to derive one from — the Edge Function
-- resolves it from the request the frontend sends (see delivery notes).
create or replace function public.request_booking_otp_internal(p_phone text, p_salon_id uuid)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_otp text; v_salt text; v_hash text; v_bytes bytea;
begin
  if p_phone !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شماره نامعتبر است');
  end if;
  if p_salon_id is null or not exists (select 1 from public.salons where id = p_salon_id and active) then
    return json_build_object('ok', false, 'error', 'سالن نامعتبر است');
  end if;
  if not public.check_rate_limit('otp_request:' || p_salon_id || ':' || p_phone, 5, 10) then
    return json_build_object('ok', false, 'error', 'تعداد درخواست بیش از حد مجاز است — چند دقیقه دیگر دوباره امتحان کنید');
  end if;

  update public.booking_otp_challenges
     set consumed = true
   where phone = p_phone and salon_id = p_salon_id and consumed = false and expires_at > now();

  v_bytes := gen_random_bytes(4);
  v_otp := lpad((
    ((get_byte(v_bytes, 0)::bigint << 24) | (get_byte(v_bytes, 1)::bigint << 16)
     | (get_byte(v_bytes, 2)::bigint << 8) | get_byte(v_bytes, 3)::bigint) % 900000 + 100000
  )::text, 6, '0');
  v_salt := encode(gen_random_bytes(16), 'hex');
  v_hash := encode(digest(v_otp || v_salt, 'sha256'), 'hex');

  insert into public.booking_otp_challenges (salon_id, phone, otp_hash, salt, expires_at)
  values (p_salon_id, p_phone, v_hash, v_salt, now() + interval '5 minutes');

  if random() < 0.01 then
    delete from public.booking_otp_challenges where expires_at < now() - interval '1 day';
  end if;

  return json_build_object('ok', true, 'otp', v_otp, 'expires_in_seconds', 300);
end;
$fn$;
-- The old (text)-only signature (and any grants on it) is removed
-- entirely by the drop below — no separate revoke needed, and a revoke
-- targeting a signature that may already be gone (on a second run of
-- this migration) would itself fail without IF EXISTS.
drop function if exists public.request_booking_otp_internal(text);
grant execute on function public.request_booking_otp_internal(text, uuid) to service_role;

-- verify_booking_otp: anon-callable — salon derived from current_salon_id()
-- (the x-salon-id header), matching every other public-path function.
create or replace function public.verify_booking_otp(p_phone text, p_otp text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_challenge record; v_hash text; v_token text; v_token_hash text; v_salon_id uuid;
begin
  if p_phone !~ '^09[0-9]{9}$' or p_otp !~ '^[0-9]{6}$' then
    return json_build_object('ok', false, 'error', 'ورودی نامعتبر است');
  end if;
  v_salon_id := public.current_salon_id();
  if v_salon_id is null then
    return json_build_object('ok', false, 'error', 'سالن نامعتبر است');
  end if;
  if not public.check_rate_limit('otp_verify:' || v_salon_id || ':' || p_phone, 10, 10) then
    return json_build_object('ok', false, 'error', 'تعداد تلاش بیش از حد مجاز است — چند دقیقه دیگر دوباره امتحان کنید');
  end if;

  select * into v_challenge from public.booking_otp_challenges
   where phone = p_phone and salon_id = v_salon_id and consumed = false and expires_at > now()
   order by created_at desc limit 1;

  if v_challenge is null then
    return json_build_object('ok', false, 'error', 'کدی یافت نشد یا منقضی شده — دوباره درخواست کنید');
  end if;
  if v_challenge.attempts >= v_challenge.max_attempts then
    update public.booking_otp_challenges set consumed = true where id = v_challenge.id;
    return json_build_object('ok', false, 'error', 'تعداد تلاش‌های مجاز تمام شد — دوباره درخواست کنید');
  end if;

  v_hash := encode(digest(p_otp || v_challenge.salt, 'sha256'), 'hex');
  if v_hash <> v_challenge.otp_hash then
    update public.booking_otp_challenges set attempts = attempts + 1 where id = v_challenge.id;
    return json_build_object('ok', false, 'error', 'کد اشتباه است');
  end if;

  update public.booking_otp_challenges set consumed = true where id = v_challenge.id;

  v_token := encode(gen_random_bytes(32), 'hex');
  v_token_hash := encode(digest(v_token, 'sha256'), 'hex');
  insert into public.booking_access_tokens (salon_id, token_hash, phone, expires_at)
  values (v_salon_id, v_token_hash, p_phone, now() + interval '20 minutes');

  if random() < 0.01 then
    delete from public.booking_access_tokens where expires_at < now() - interval '1 day';
  end if;

  return json_build_object('ok', true, 'token', v_token, 'expires_in_seconds', 1200);
end;
$fn$;
grant execute on function public.verify_booking_otp(text, text) to anon, authenticated;

-- Token-gated booking access, now filtering by the resolved (phone, salon_id) pair.
create or replace function public.get_my_bookings_with_token(p_token text)
returns setof public.appointments
language plpgsql security definer set search_path = public as $fn$
declare v_phone text; v_salon_id uuid;
begin
  select r.phone, r.salon_id into v_phone, v_salon_id from public.resolve_booking_token(p_token) r;
  if v_phone is null then
    return;
  end if;
  return query
    select * from public.appointments
    where customer_phone = v_phone and salon_id = v_salon_id
    order by date desc, start_min desc;
end;
$fn$;
grant execute on function public.get_my_bookings_with_token(text) to anon, authenticated;

create or replace function public.cancel_my_booking_with_token(p_token text, p_appointment_id text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_phone text; v_salon_id uuid; v_owner text; v_owner_salon uuid;
begin
  select r.phone, r.salon_id into v_phone, v_salon_id from public.resolve_booking_token(p_token) r;
  if v_phone is null then
    return json_build_object('ok', false, 'error', 'نشست شما منقضی شده — دوباره وارد شوید');
  end if;
  select customer_phone, salon_id into v_owner, v_owner_salon from public.appointments where id = p_appointment_id;
  if v_owner is null or v_owner <> v_phone or v_owner_salon <> v_salon_id then
    return json_build_object('ok', false, 'error', 'این نوبت متعلق به شما نیست');
  end if;
  update public.appointments set status = 'cancelled' where id = p_appointment_id;
  return json_build_object('ok', true);
end;
$fn$;
grant execute on function public.cancel_my_booking_with_token(text, text) to anon, authenticated;

create or replace function public.reschedule_my_booking_with_token(
  p_token text, p_appointment_id text, p_new_date date, p_new_start_min int
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_phone text; v_salon_id uuid; v_appt record; v_svc record;
  v_new_end int; v_app_dow int; v_wh record; v_wh_start int; v_wh_end int;
begin
  select r.phone, r.salon_id into v_phone, v_salon_id from public.resolve_booking_token(p_token) r;
  if v_phone is null then
    return json_build_object('ok', false, 'error', 'نشست شما منقضی شده — دوباره وارد شوید');
  end if;

  select * into v_appt from public.appointments where id = p_appointment_id;
  if v_appt is null or v_appt.customer_phone <> v_phone or v_appt.salon_id <> v_salon_id then
    return json_build_object('ok', false, 'error', 'این نوبت متعلق به شما نیست');
  end if;
  if p_new_date < current_date then
    return json_build_object('ok', false, 'error', 'تاریخ گذشته قابل انتخاب نیست');
  end if;
  if not exists (select 1 from public.approved_dates where date = p_new_date and salon_id = v_salon_id) then
    return json_build_object('ok', false, 'error', 'این روز برای رزرو باز نشده است');
  end if;

  select * into v_svc from public.services where id = v_appt.service_id and salon_id = v_salon_id;
  if v_svc is null then
    return json_build_object('ok', false, 'error', 'خدمت مرتبط با این نوبت یافت نشد');
  end if;
  v_new_end := p_new_start_min + v_svc.duration_minutes;

  v_app_dow := (extract(dow from p_new_date)::int + 1) % 7;
  select * into v_wh from public.working_hours
   where day_of_week = v_app_dow and staff_id = v_appt.staff_id and salon_id = v_salon_id;
  if v_wh is null then
    select * into v_wh from public.working_hours
     where day_of_week = v_app_dow and staff_id is null and salon_id = v_salon_id;
  end if;
  if v_wh is null or v_wh.is_closed then
    return json_build_object('ok', false, 'error', 'در این روز سالن یا آرایشگر تعطیل است');
  end if;
  v_wh_start := split_part(v_wh.start_time, ':', 1)::int * 60 + split_part(v_wh.start_time, ':', 2)::int;
  v_wh_end := split_part(v_wh.end_time, ':', 1)::int * 60 + split_part(v_wh.end_time, ':', 2)::int;
  if p_new_start_min < v_wh_start or v_new_end > v_wh_end then
    return json_build_object('ok', false, 'error', 'خارج از ساعات کاری است');
  end if;

  begin
    update public.appointments
       set date = p_new_date, start_min = p_new_start_min, end_min = v_new_end,
           status = 'rescheduled', pending_date = null, pending_start_min = null, pending_end_min = null
     where id = p_appointment_id;
  exception when exclusion_violation then
    return json_build_object('ok', false, 'error', 'این زمان قبلاً رزرو شده — زمان دیگری انتخاب کنید');
  end;

  return json_build_object('ok', true);
end;
$fn$;
grant execute on function public.reschedule_my_booking_with_token(text, text, date, int) to anon, authenticated;

-- request_booking_otp_test: salon derived from current_salon_id(); reads
-- the now-per-salon app_settings row for that salon's own test-mode flag.
create or replace function public.request_booking_otp_test(p_phone text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_otp text; v_salt text; v_hash text; v_bytes bytea; v_test_mode boolean; v_salon_id uuid;
begin
  v_salon_id := public.current_salon_id();
  if v_salon_id is null then
    return json_build_object('ok', false, 'error', 'سالن نامعتبر است');
  end if;
  select sms_test_mode into v_test_mode from public.app_settings where salon_id = v_salon_id;
  if not coalesce(v_test_mode, false) then
    return json_build_object('ok', false, 'error', 'حالت تست فعال نیست');
  end if;
  if p_phone !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شماره نامعتبر است');
  end if;
  if not public.check_rate_limit('otp_request_test:' || v_salon_id || ':' || p_phone, 5, 10) then
    return json_build_object('ok', false, 'error', 'تعداد درخواست بیش از حد مجاز است — چند دقیقه دیگر دوباره امتحان کنید');
  end if;

  update public.booking_otp_challenges
     set consumed = true
   where phone = p_phone and salon_id = v_salon_id and consumed = false and expires_at > now();

  v_bytes := gen_random_bytes(4);
  v_otp := lpad((
    ((get_byte(v_bytes, 0)::bigint << 24) | (get_byte(v_bytes, 1)::bigint << 16)
     | (get_byte(v_bytes, 2)::bigint << 8) | get_byte(v_bytes, 3)::bigint) % 900000 + 100000
  )::text, 6, '0');
  v_salt := encode(gen_random_bytes(16), 'hex');
  v_hash := encode(digest(v_otp || v_salt, 'sha256'), 'hex');

  insert into public.booking_otp_challenges (salon_id, phone, otp_hash, salt, expires_at)
  values (v_salon_id, p_phone, v_hash, v_salt, now() + interval '5 minutes');

  if random() < 0.01 then
    delete from public.booking_otp_challenges where expires_at < now() - interval '1 day';
  end if;

  return json_build_object('ok', true, 'test_otp', v_otp, 'expires_in_seconds', 300);
end;
$fn$;
grant execute on function public.request_booking_otp_test(text) to anon, authenticated;

-- ----------------------------------------------------------------------------
-- customer_loyalty / redeem_loyalty_reward / apply_referral — every
-- customers/loyalty_settings/loyalty_ledger lookup now salon-scoped.
-- ----------------------------------------------------------------------------
create or replace function public.customer_loyalty(p_phone text)
returns json language plpgsql stable security definer set search_path = public as $fn$
declare c record; ls record; tier int; disc int; v_salon_id uuid;
begin
  v_salon_id := public.current_salon_id();
  select * into ls from public.loyalty_settings where salon_id = v_salon_id;
  select * into c from public.customers where phone = p_phone and salon_id = v_salon_id;
  if c is null or ls is null then
    return json_build_object('found', false, 'points', 0, 'discount_percent', 0, 'history', '[]'::json, 'referrals', '[]'::json);
  end if;
  tier := floor(c.loyalty_points::numeric / greatest(ls.points_per_tier, 1));
  disc := least(tier * ls.discount_per_tier, ls.max_discount);
  return json_build_object(
    'found', true,
    'name', c.name,
    'points', c.loyalty_points,
    'total_visits', c.total_visits,
    'referral_code', c.referral_code,
    'discount_percent', disc,
    'max_discount', ls.max_discount,
    'at_cap', disc >= ls.max_discount,
    'points_to_next_tier', greatest(ls.points_per_tier - (c.loyalty_points % greatest(ls.points_per_tier, 1)), 0),
    'history', coalesce((
      select json_agg(json_build_object('delta', l.delta, 'reason', l.reason, 'at', l.created_at) order by l.created_at desc)
        from (select * from public.loyalty_ledger where customer_phone = p_phone and salon_id = v_salon_id
               order by created_at desc limit 30) l
    ), '[]'::json),
    'referrals', coalesce((
      select json_agg(json_build_object('name', r.name, 'phone', r.phone, 'total_visits', r.total_visits, 'joined_at', r.created_at) order by r.created_at desc)
        from public.customers r where r.referred_by = p_phone and r.salon_id = v_salon_id
    ), '[]'::json)
  );
end $fn$;
grant execute on function public.customer_loyalty(text) to anon, authenticated;

create or replace function public.redeem_loyalty_reward(p_phone text)
returns json language plpgsql security definer set search_path = public as $fn$
declare c record; ls record; tier int; disc int; v_salon_id uuid;
begin
  if not (public.is_manager() or public.my_role() = 'stylist') then
    return json_build_object('ok', false, 'error', 'اجازهٔ این کار را ندارید');
  end if;
  v_salon_id := public.current_salon_id();
  select * into ls from public.loyalty_settings where salon_id = v_salon_id;
  select * into c from public.customers where phone = p_phone and salon_id = v_salon_id;
  if c is null then return json_build_object('ok', false, 'error', 'مشتری پیدا نشد'); end if;

  tier := floor(c.loyalty_points::numeric / greatest(ls.points_per_tier, 1));
  disc := least(tier * ls.discount_per_tier, ls.max_discount);
  if disc < ls.max_discount then
    return json_build_object('ok', false, 'error', 'مشتری هنوز به سقف تخفیف نرسیده');
  end if;
  if c.loyalty_points <= 0 then
    return json_build_object('ok', false, 'error', 'امتیازی برای استفاده نیست');
  end if;

  insert into public.loyalty_ledger (salon_id, customer_phone, delta, reason) values (v_salon_id, p_phone, -c.loyalty_points, 'redeemed');
  update public.customers set loyalty_points = 0 where phone = p_phone and salon_id = v_salon_id;

  return json_build_object('ok', true, 'redeemed_discount_percent', disc);
end $fn$;
grant execute on function public.redeem_loyalty_reward(text) to authenticated;

create or replace function public.apply_referral(p_new_phone text, p_code text)
returns json language plpgsql security definer set search_path = public as $fn$
declare referrer record; v_salon_id uuid;
begin
  v_salon_id := public.current_salon_id();
  if v_salon_id is null then
    return json_build_object('ok', false, 'error', 'سالن نامعتبر است');
  end if;
  if not public.check_rate_limit('apply_referral:' || v_salon_id || ':' || coalesce(p_new_phone, ''), 5, 10) then
    return json_build_object('ok', false, 'error', 'تعداد درخواست بیش از حد مجاز است — چند دقیقه دیگر دوباره امتحان کنید');
  end if;

  select * into referrer from public.customers where referral_code = upper(p_code) and salon_id = v_salon_id;
  if referrer is null then return json_build_object('ok', false, 'error', 'کد معرف پیدا نشد'); end if;
  if referrer.phone = p_new_phone then return json_build_object('ok', false, 'error', 'کد معرف خودتان قابل استفاده نیست'); end if;
  if exists (select 1 from public.customers where phone = p_new_phone and salon_id = v_salon_id and referred_by is not null) then
    return json_build_object('ok', false, 'error', 'قبلاً از کد معرف استفاده کرده‌اید');
  end if;
  if not exists (select 1 from public.customers where phone = p_new_phone and salon_id = v_salon_id) then
    return json_build_object('ok', false, 'error', 'ابتدا باید یک نوبت برای این شماره ثبت شده باشد');
  end if;

  update public.customers set referred_by = referrer.phone where phone = p_new_phone and salon_id = v_salon_id;

  return json_build_object('ok', true);
end $fn$;
grant execute on function public.apply_referral(text, text) to anon, authenticated;

-- customers.referral_code was globally unique — widen to per-salon, since
-- two independent salons on the platform have no reason to share a single
-- code namespace across all 300+ of them.
do $$
begin
  if exists (select 1 from pg_constraint where conname = 'customers_referral_code_key') then
    alter table public.customers drop constraint customers_referral_code_key;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'customers_salon_referral_code_key') then
    alter table public.customers add constraint customers_salon_referral_code_key unique (salon_id, referral_code);
  end if;
end $$;

-- ----------------------------------------------------------------------------
-- create_public_booking — the core public booking flow. Salon derived
-- from current_salon_id() (the x-salon-id header); every lookup and the
-- appointments insert itself now scoped to it.
-- ----------------------------------------------------------------------------
create or replace function public.create_public_booking(
  p_service_id text, p_staff_id text, p_date date, p_start_min int,
  p_customer_name text, p_customer_phone text, p_customer_gender text,
  p_referral_code text default null
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_svc record; v_wh record; v_app_dow int; v_wh_start int; v_wh_end int;
  v_end_min int; v_id text; v_code text; v_original bigint; v_svc_discount bigint;
  v_after_svc bigint; v_loyalty_pct int := 0; v_final bigint; v_loyalty json; v_code_bytes bytea;
  v_salon_id uuid;
begin
  v_salon_id := public.current_salon_id();
  if v_salon_id is null then
    return json_build_object('ok', false, 'error', 'سالن نامعتبر است');
  end if;
  if p_customer_phone !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شماره موبایل نامعتبر است');
  end if;
  if coalesce(trim(p_customer_name), '') = '' then
    return json_build_object('ok', false, 'error', 'نام لازم است');
  end if;
  if p_customer_gender not in ('female', 'male') then
    return json_build_object('ok', false, 'error', 'جنسیت نامعتبر است');
  end if;
  if not public.check_rate_limit('create_booking:' || v_salon_id || ':' || p_customer_phone, 10, 30) then
    return json_build_object('ok', false, 'error', 'تعداد درخواست بیش از حد مجاز است — کمی بعد دوباره امتحان کنید');
  end if;
  if p_date < current_date then
    return json_build_object('ok', false, 'error', 'تاریخ گذشته قابل انتخاب نیست');
  end if;
  if not exists (select 1 from public.approved_dates where date = p_date and salon_id = v_salon_id) then
    return json_build_object('ok', false, 'error', 'این روز برای رزرو باز نشده است');
  end if;

  select * into v_svc from public.services where id = p_service_id and salon_id = v_salon_id and is_active;
  if v_svc is null then
    return json_build_object('ok', false, 'error', 'خدمت یافت نشد یا غیرفعال است');
  end if;
  if v_svc.gender <> p_customer_gender then
    return json_build_object('ok', false, 'error', 'این خدمت با جنسیت انتخابی مطابقت ندارد');
  end if;

  if p_staff_id is not null and not exists (select 1 from public.stylists where id = p_staff_id and salon_id = v_salon_id and active) then
    return json_build_object('ok', false, 'error', 'آرایشگر یافت نشد یا غیرفعال است');
  end if;

  v_app_dow := (extract(dow from p_date)::int + 1) % 7;
  select * into v_wh from public.working_hours
   where day_of_week = v_app_dow and staff_id = p_staff_id and salon_id = v_salon_id;
  if v_wh is null then
    select * into v_wh from public.working_hours
     where day_of_week = v_app_dow and staff_id is null and salon_id = v_salon_id;
  end if;
  if v_wh is null or v_wh.is_closed then
    return json_build_object('ok', false, 'error', 'در این روز سالن یا آرایشگر تعطیل است');
  end if;
  v_wh_start := split_part(v_wh.start_time, ':', 1)::int * 60 + split_part(v_wh.start_time, ':', 2)::int;
  v_wh_end := split_part(v_wh.end_time, ':', 1)::int * 60 + split_part(v_wh.end_time, ':', 2)::int;
  v_end_min := p_start_min + v_svc.duration_minutes;
  if p_start_min < v_wh_start or v_end_min > v_wh_end then
    return json_build_object('ok', false, 'error', 'خارج از ساعات کاری است');
  end if;

  v_original := coalesce(v_svc.price, 0);
  v_svc_discount := case
    when v_svc.discount_type = 'percent' then round(v_original * v_svc.discount_value / 100.0)
    when v_svc.discount_type = 'fixed' then v_svc.discount_value
    else 0
  end;
  v_after_svc := greatest(0, v_original - v_svc_discount);
  if v_svc.price is not null then
    v_loyalty := public.customer_loyalty(p_customer_phone);
    if (v_loyalty->>'found')::boolean then
      v_loyalty_pct := coalesce((v_loyalty->>'discount_percent')::int, 0);
    end if;
  end if;
  v_final := case when v_svc.price is null then null
                  else greatest(0, v_after_svc - round(v_after_svc * v_loyalty_pct / 100.0)) end;

  v_id := 'apt-' || substr(md5(gen_random_uuid()::text), 1, 16);
  v_code_bytes := gen_random_bytes(4);
  v_code := 'MN-' || lpad((
    ((get_byte(v_code_bytes, 0)::bigint << 24) | (get_byte(v_code_bytes, 1)::bigint << 16)
     | (get_byte(v_code_bytes, 2)::bigint << 8) | get_byte(v_code_bytes, 3)::bigint) % 90000 + 10000
  )::text, 5, '0');

  begin
    insert into public.appointments (
      id, salon_id, customer_name, customer_phone, customer_gender, service_id, staff_id,
      staff_name, date, start_min, end_min, buffer_minutes, status,
      tracking_code, original_price, discount_type, discount_value, discount_reason, final_price
    ) values (
      v_id, v_salon_id, trim(p_customer_name), p_customer_phone, p_customer_gender, p_service_id, p_staff_id,
      coalesce((select name from public.stylists where id = p_staff_id and salon_id = v_salon_id), ''),
      p_date, p_start_min, v_end_min, v_svc.buffer_minutes, 'pending',
      v_code, v_original, v_svc.discount_type, v_svc.discount_value,
      case when v_loyalty_pct > 0 then v_svc.discount_reason || case when v_svc.discount_reason <> '' then ' · ' else '' end || v_loyalty_pct || '٪ تخفیف باشگاه مشتریان' else v_svc.discount_reason end,
      v_final
    );
  exception when exclusion_violation then
    return json_build_object('ok', false, 'error', 'این زمان قبلاً رزرو شده — زمان دیگری انتخاب کنید');
  end;

  if p_referral_code is not null and length(trim(p_referral_code)) > 0 then
    perform public.apply_referral(p_customer_phone, p_referral_code);
  end if;

  return json_build_object(
    'ok', true, 'id', v_id, 'tracking_code', v_code, 'final_price', v_final,
    'original_price', v_original, 'staff_name', coalesce((select name from public.stylists where id = p_staff_id and salon_id = v_salon_id), '')
  );
end;
$fn$;
grant execute on function public.create_public_booking(text, text, date, int, text, text, text, text) to anon, authenticated;


-- >>>>>>>>>> supabase/migrations/v2.24_multitenant_part6_rfm.sql
-- ============================================================================
-- Migration v2.24 — Multi-Tenant SaaS foundation (part 6: customer
-- segmentation RPCs)
-- ============================================================================
-- customer_rfm_raw joined customers to appointments by customer_phone
-- alone, with no salon_id match — since the same phone number can now be
-- a genuinely different customer at two different salons (part 2), this
-- join could attribute salon B's appointments to salon A's customer row
-- sharing that phone number. get_customer_rfm_segments() and
-- preview_customer_segment_distribution() both also read
-- customer_segment_settings via the old `where id = 1` singleton pattern,
-- which no longer exists after part 4 re-keyed that table on salon_id.
-- ============================================================================

drop view if exists public.customer_rfm_raw;
create view public.customer_rfm_raw as
select
  c.salon_id,
  c.phone,
  c.name,
  c.sms_opt_out,
  coalesce(extract(day from (now() - max(a.date)))::int, 9999) as recency_days,
  count(a.id) as frequency,
  coalesce(sum(a.final_price), 0) as monetary
from public.customers c
left join public.appointments a
  on a.customer_phone = c.phone and a.salon_id = c.salon_id and a.status = 'completed'
group by c.salon_id, c.phone, c.name, c.sms_opt_out;

create or replace function public.get_customer_rfm_segments()
returns table (
  phone text, name text, sms_opt_out boolean,
  recency_days int, frequency int, monetary bigint,
  segment text, segment_fa text,
  avg_gap_days numeric, personal_recency_limit int, is_vip boolean
)
language sql stable security definer set search_path = public as $fn$
  with settings as (
    select * from public.customer_segment_settings where salon_id = public.current_salon_id()
  ),
  gaps as (
    select
      customer_phone, salon_id,
      (date - lag(date) over (partition by customer_phone, salon_id order by date))::int as gap_days
    from public.appointments
    where status = 'completed' and salon_id = public.current_salon_id()
  ),
  avg_gaps as (
    select customer_phone, avg(gap_days)::numeric as avg_gap_days
    from gaps
    where gap_days is not null and gap_days > 0
    group by customer_phone
  ),
  monetary_p80 as (
    select percentile_cont(0.80) within group (order by monetary)::bigint as p80
    from public.customer_rfm_raw
    where frequency > 0 and salon_id = public.current_salon_id()
  ),
  scored as (
    select
      raw.*,
      ag.avg_gap_days,
      case
        when coalesce(ag.avg_gap_days, 0) > 0
          then greatest(s.loyal_recency_days, round(ag.avg_gap_days * 1.5)::int)
        else s.loyal_recency_days
      end as personal_recency_limit,
      s.loyal_min_visits,
      s.inactive_after_days,
      mp.p80
    from public.customer_rfm_raw raw
    left join avg_gaps ag on ag.customer_phone = raw.phone
    cross join settings s
    cross join monetary_p80 mp
    where public.is_manager() and raw.salon_id = public.current_salon_id()
  )
  select
    phone, name, sms_opt_out, recency_days, frequency, monetary,
    case
      when recency_days <= personal_recency_limit and frequency >= loyal_min_visits then 'champions'
      when recency_days <= personal_recency_limit and frequency <  loyal_min_visits then 'new'
      when recency_days >  personal_recency_limit and recency_days <= inactive_after_days
           and frequency >= loyal_min_visits then 'at_risk'
      else 'inactive'
    end as segment,
    case
      when recency_days <= personal_recency_limit and frequency >= loyal_min_visits then 'مشتریان وفادار'
      when recency_days <= personal_recency_limit and frequency <  loyal_min_visits then 'مشتریان جدید'
      when recency_days >  personal_recency_limit and recency_days <= inactive_after_days
           and frequency >= loyal_min_visits then 'در خطر ریزش'
      else 'غیرفعال'
    end as segment_fa,
    avg_gap_days, personal_recency_limit,
    (recency_days <= personal_recency_limit
       and frequency >= loyal_min_visits
       and monetary >= coalesce(p80, monetary + 1)) as is_vip
  from scored
  order by monetary desc
  limit 500;
$fn$;

create or replace function public.preview_customer_segment_distribution(
  p_recency int, p_visits int, p_inactive int
)
returns table (segment text, segment_fa text, customer_count bigint, pct numeric)
language sql stable security definer set search_path = public as $fn$
  with gaps as (
    select
      customer_phone, salon_id,
      (date - lag(date) over (partition by customer_phone, salon_id order by date))::int as gap_days
    from public.appointments
    where status = 'completed' and salon_id = public.current_salon_id()
  ),
  avg_gaps as (
    select customer_phone, avg(gap_days)::numeric as avg_gap_days
    from gaps
    where gap_days is not null and gap_days > 0
    group by customer_phone
  ),
  with_limit as (
    select
      raw.recency_days, raw.frequency,
      case
        when coalesce(ag.avg_gap_days, 0) > 0
          then greatest(p_recency, round(ag.avg_gap_days * 1.5)::int)
        else p_recency
      end as personal_limit
    from public.customer_rfm_raw raw
    left join avg_gaps ag on ag.customer_phone = raw.phone
    where public.is_manager() and raw.salon_id = public.current_salon_id()
  ),
  classified as (
    select
      case
        when recency_days <= personal_limit and frequency >= p_visits then 'champions'
        when recency_days <= personal_limit and frequency <  p_visits then 'new'
        when recency_days >  personal_limit and recency_days <= p_inactive
             and frequency >= p_visits then 'at_risk'
        else 'inactive'
      end as segment
    from with_limit
  ),
  totals as (select count(*) as n from classified),
  counted as (
    select segment, count(*) as customer_count
    from classified
    group by segment
  )
  select
    seg.key as segment,
    case seg.key
      when 'champions' then 'مشتریان وفادار'
      when 'at_risk'   then 'در خطر ریزش'
      when 'new'       then 'مشتریان جدید'
      else                  'غیرفعال'
    end as segment_fa,
    coalesce(counted.customer_count, 0) as customer_count,
    case when (select n from totals) = 0 then 0
         else round(coalesce(counted.customer_count, 0)::numeric / (select n from totals) * 100, 1)
    end as pct
  from (values ('champions'), ('at_risk'), ('new'), ('inactive')) as seg(key)
  left join counted on counted.segment = seg.key;
$fn$;


-- >>>>>>>>>> supabase/migrations/v2.24_multitenant_part7_salons_rls.sql
-- ============================================================================
-- Migration v2.24 — Multi-Tenant SaaS foundation (part 7: RLS for the
-- salons table itself)
-- ============================================================================
-- Found while designing the frontend tenant-resolution flow: salons never
-- got RLS enabled or any grant at all in parts 1-6. Resolving a URL slug
-- to a salon_id is necessarily the FIRST thing the frontend does, before
-- any salon context (and therefore the x-salon-id header) exists — so
-- this lookup can't depend on current_salon_id() the way every other
-- policy in this migration set does. A public, slug-based read (name/id/
-- slug/active only — a directory entry, not sensitive) is the standard,
-- correct answer: anyone choosing which salon's booking page to open
-- necessarily needs this exact lookup to work with no prior context.
-- Row-level write access stays fully locked down (service_role only, for
-- provisioning new salons — no self-service tenant creation from the
-- client in this delivery; see the checklist).
-- ============================================================================

alter table public.salons enable row level security;

drop policy if exists p_salons_read on public.salons;
create policy p_salons_read on public.salons for select using (active);

grant select on public.salons to anon, authenticated;
-- No insert/update/delete policy at all: default-deny for every direct
-- client operation. New salons are provisioned via the service_role key
-- only (an admin/ops path outside this app, e.g. Supabase SQL editor or
-- a future dedicated onboarding Edge Function — deliberately not exposed
-- to any authenticated app user in this delivery).


-- >>>>>>>>>> supabase/migrations/v2.25_autopilot_part1_lifecycle.sql
-- ============================================================================
-- Migration v2.25 — Autopilot 2.0: post-service lifecycle + weekly
-- reconciliation (part 1 of 3: status lifecycle, feedback RLS + trigger)
-- ============================================================================
-- Adds two new appointment statuses:
--   pending_verification — set automatically once appointment_time +
--     duration has elapsed for a confirmed/rescheduled booking (part 2's
--     scheduled function). Not yet confirmed as attended.
--   archived_unconfirmed — a pending_verification booking nobody ever
--     resolved (neither the customer via feedback nor the owner via
--     reconciliation) within 7 days. Terminal, and — critically — NEVER
--     awards loyalty/referral points or counts as revenue (see part 2's
--     archive function and the isRevenueEligible() frontend helper).
--
-- Also folds in a real, pre-existing gap found while working on this:
-- public.feedbacks (from v2.14) and its v2.18 hardening (manager-only
-- read, get_feedback_stats()) were never actually present in schema.sql —
-- confirmed by grepping the file directly. This migration adds the
-- complete, current definition of both to schema.sql for the first time,
-- alongside the feedback-loop changes below.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 0) sms_messages gets a 'cancelled' status (cron-reminders' new abort-
--    before-send check) and two new kinds for the weekly dispatch
--    (reconciliation_prompt, weekly_summary).
-- ----------------------------------------------------------------------------
alter table public.sms_messages drop constraint if exists sms_messages_status_check;
alter table public.sms_messages add constraint sms_messages_status_check
  check (status in ('queued','sent','failed','delivered','cancelled'));
alter table public.sms_messages drop constraint if exists sms_messages_kind_check;
alter table public.sms_messages add constraint sms_messages_kind_check
  check (kind in ('confirmation','reminder','cancellation','reschedule','campaign','loyalty','custom','reconciliation_prompt','weekly_summary'));

-- ----------------------------------------------------------------------------
-- 1) Status check constraint — add the two new terminal/intermediate
--    statuses. Every existing status value is untouched.
-- ----------------------------------------------------------------------------
alter table public.appointments drop constraint if exists appointments_status_check;
alter table public.appointments add constraint appointments_status_check
  check (status in (
    'pending','confirmed','cancelled','rescheduled','completed','no_show',
    'reschedule_proposed','pending_verification','archived_unconfirmed'
  ));

-- ----------------------------------------------------------------------------
-- 2) feedbacks — full definition (table + salon_id + all policies +
--    get_feedback_stats), consolidating v2.14 + v2.18 + this migration's
--    changes into schema.sql for the first time, plus:
--    - salon_id, derived server-side from the referenced appointment (a
--      BEFORE INSERT trigger, not a client-supplied value — can't be
--      spoofed, and works even though the public feedback page has no
--      salon/session context of its own).
--    - insert policy widened to allow pending_verification, not just
--      completed (the whole point of this feature: the customer's rating
--      IS the confirmation).
--    - an AFTER INSERT trigger that upgrades the appointment to
--      'completed' in the same transaction — which in turn fires
--      sync_customer_from_appointment exactly once, the normal way
--      (old.status = 'pending_verification', new.status = 'completed'),
--      so loyalty/referral/RFM all follow their EXISTING, already-
--      idempotent path with no special-casing needed here.
-- ----------------------------------------------------------------------------
create table if not exists public.feedbacks (
  id         text primary key default 'fb-' || substr(md5(gen_random_uuid()::text), 1, 12),
  salon_id   uuid not null references public.salons(id) on delete cascade,
  booking_id text not null unique references public.appointments(id) on delete cascade,
  rating     int not null check (rating between 1 and 5),
  tags       text[] not null default '{}',
  comment    text not null default '',
  created_at timestamptz not null default now()
);
alter table public.feedbacks add column if not exists salon_id uuid;
update public.feedbacks f set salon_id = a.salon_id
  from public.appointments a where a.id = f.booking_id and f.salon_id is null;
do $$
begin
  if exists (select 1 from public.feedbacks where salon_id is null) then
    raise exception 'feedbacks has orphaned rows with no resolvable salon_id — resolve before re-running';
  end if;
  alter table public.feedbacks alter column salon_id set not null;
exception when others then null; -- already not-null from a prior run
end $$;
create index if not exists feedbacks_created_at_idx on public.feedbacks (created_at);
create index if not exists feedbacks_salon_idx on public.feedbacks (salon_id);

alter table public.feedbacks enable row level security;

create or replace function public.set_feedback_salon_id() returns trigger
language plpgsql security definer set search_path = public as $fn$
begin
  select salon_id into new.salon_id from public.appointments where id = new.booking_id;
  return new;
end;
$fn$;
drop trigger if exists trg_set_feedback_salon_id on public.feedbacks;
create trigger trg_set_feedback_salon_id
  before insert on public.feedbacks
  for each row execute function public.set_feedback_salon_id();

-- Helper for the insert policy below — RLS policy EXPRESSIONS evaluate
-- whatever tables they reference with the CALLING role's own privileges,
-- never bypassed by anything else (confirmed directly: a raw
-- `exists (select from appointments ...)` here failed with a real
-- "permission denied for table appointments", since anon correctly has no
-- direct grant on appointments — by design, since v2.19). Wrapping the
-- same lookup in a SECURITY DEFINER function makes it resolve with the
-- function owner's privileges instead, the same pattern every other
-- cross-table RLS check in this schema already relies on (is_manager(),
-- current_salon_id(), etc.) — this was simply the first policy that
-- needed it for a table the caller has no base grant on at all.
create or replace function public.appointment_status_for_feedback(p_booking_id text)
returns text
language sql stable security definer set search_path = public as $fn$
  select status from public.appointments where id = p_booking_id;
$fn$;
grant execute on function public.appointment_status_for_feedback(text) to anon, authenticated;

drop policy if exists p_feedback_insert on public.feedbacks;
create policy p_feedback_insert on public.feedbacks
  for insert
  with check (
    public.appointment_status_for_feedback(booking_id) in ('completed', 'pending_verification')
  );

drop policy if exists p_feedback_read on public.feedbacks;
create policy p_feedback_read on public.feedbacks for select
  using (public.is_manager() and salon_id = public.current_salon_id());

grant select, insert on public.feedbacks to anon, authenticated;

create or replace function public.upgrade_appointment_on_feedback() returns trigger
language plpgsql security definer set search_path = public as $fn$
begin
  update public.appointments
     set status = 'completed'
   where id = new.booking_id and status = 'pending_verification';
  return new;
end;
$fn$;
drop trigger if exists trg_upgrade_appointment_on_feedback on public.feedbacks;
create trigger trg_upgrade_appointment_on_feedback
  after insert on public.feedbacks
  for each row execute function public.upgrade_appointment_on_feedback();

create or replace function public.get_feedback_stats()
returns table (
  total_count bigint, avg_rating numeric,
  rating_1 bigint, rating_2 bigint, rating_3 bigint, rating_4 bigint, rating_5 bigint
)
language sql stable security definer set search_path = public as $fn$
  select
    count(*)::bigint as total_count,
    round(avg(rating)::numeric, 2) as avg_rating,
    count(*) filter (where rating = 1)::bigint as rating_1,
    count(*) filter (where rating = 2)::bigint as rating_2,
    count(*) filter (where rating = 3)::bigint as rating_3,
    count(*) filter (where rating = 4)::bigint as rating_4,
    count(*) filter (where rating = 5)::bigint as rating_5
  from public.feedbacks
  where public.is_manager() and salon_id = public.current_salon_id();
$fn$;
grant execute on function public.get_feedback_stats() to authenticated;

-- ----------------------------------------------------------------------------
-- 3) report_appointment_no_show — the OTHER half of the feedback-page
--    interaction ("client indicates non-attendance"). Deliberately
--    separate from the feedbacks table/RPC above: rating a visit you
--    didn't have doesn't make sense, so this skips feedbacks entirely and
--    moves the appointment straight to 'no_show'. Same bearer-token trust
--    model as feedback submission (booking_id is already an opaque,
--    unguessable-in-practice id — see v2.14's original rationale).
-- ----------------------------------------------------------------------------
create or replace function public.report_appointment_no_show(p_booking_id text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_status text;
begin
  select status into v_status from public.appointments where id = p_booking_id;
  if v_status is null then
    return json_build_object('ok', false, 'error', 'نوبت پیدا نشد');
  end if;
  if v_status <> 'pending_verification' then
    return json_build_object('ok', false, 'error', 'این نوبت قابل‌گزارش نیست');
  end if;
  update public.appointments set status = 'no_show' where id = p_booking_id;
  return json_build_object('ok', true);
end;
$fn$;
grant execute on function public.report_appointment_no_show(text) to anon, authenticated;


-- >>>>>>>>>> supabase/migrations/v2.25_autopilot_part2_scheduling_reconciliation.sql
-- ============================================================================
-- Migration v2.25 — Autopilot 2.0 (part 2 of 3: scheduled transitions +
-- reconciliation token system + submit_reconciliation_batch)
-- ============================================================================
-- Two functions meant to run on a schedule (pg_cron, or any external
-- scheduler hitting a thin Edge Function wrapper — see the delivery notes
-- for exactly how to wire this up; this migration provides the SQL side
-- either approach calls):
--   transition_elapsed_appointments() — confirmed/rescheduled whose
--     appointment_time + duration has passed become pending_verification.
--     Intended to run every 15-30 minutes.
--   archive_stale_pending_verifications() — pending_verification older
--     than 7 days becomes archived_unconfirmed. NEVER completed — the
--     hard policy from the spec: unverified income is never auto-
--     confirmed, only ever auto-archived out of the pending queue.
--     Intended to run once a day.
--
-- Both are SECURITY DEFINER, take no parameters, and are safe to call
-- repeatedly (idempotent — only touch rows still in the source status).
--
-- TIMEZONE NOTE: like the existing cron-reminders Edge Function, this
-- assumes one fixed wall-clock offset for every salon (matching this
-- codebase's current single-offset assumption — SALON_TZ_OFFSET_MINUTES).
-- A deployment spanning multiple timezones would need a
-- salons.tz_offset_minutes column and per-salon arithmetic below; flagged
-- in the checklist, not silently assumed away.
-- ============================================================================

create or replace function public.transition_elapsed_appointments(p_tz_offset_minutes int default 210)
returns int
language plpgsql security definer set search_path = public as $fn$
declare v_count int;
begin
  with elapsed as (
    update public.appointments
       set status = 'pending_verification'
     where status in ('confirmed', 'rescheduled')
       and (date + (end_min || ' minutes')::interval) < (now() + (p_tz_offset_minutes || ' minutes')::interval)
    returning 1
  )
  select count(*) into v_count from elapsed;
  return v_count;
end;
$fn$;
-- Not granted to anon/authenticated — only ever invoked by the scheduler
-- via a service_role-authenticated call (an Edge Function, or pg_cron's
-- own execution context, which already runs as a privileged role).

create or replace function public.archive_stale_pending_verifications()
returns int
language plpgsql security definer set search_path = public as $fn$
declare v_count int;
begin
  with archived as (
    update public.appointments
       set status = 'archived_unconfirmed'
     where status = 'pending_verification'
       and updated_at < now() - interval '7 days'
    returning 1
  )
  select count(*) into v_count from archived;
  return v_count;
end;
$fn$;

-- ----------------------------------------------------------------------------
-- Reconciliation tokens — the owner's "magic link" credential, same shape
-- and trust model as the customer OTP/token system (booking_access_tokens
-- from v2.19): random 256-bit token, only its sha256 hash stored, short
-- expiry, single-salon scope, revocable.
-- ----------------------------------------------------------------------------
create table if not exists public.reconciliation_tokens (
  id         bigint generated always as identity primary key,
  salon_id   uuid not null references public.salons(id) on delete cascade,
  token_hash text not null unique,
  expires_at timestamptz not null,
  used_at    timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists reconciliation_tokens_salon_idx on public.reconciliation_tokens (salon_id);
alter table public.reconciliation_tokens enable row level security;
-- No policies at all: reachable only via the SECURITY DEFINER functions
-- below (same pattern as booking_otp_challenges/booking_access_tokens).

create or replace function public.create_reconciliation_token(p_salon_id uuid)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_token text; v_hash text;
begin
  v_token := encode(gen_random_bytes(32), 'hex');
  v_hash := encode(digest(v_token, 'sha256'), 'hex');
  insert into public.reconciliation_tokens (salon_id, token_hash, expires_at)
  values (p_salon_id, v_hash, now() + interval '72 hours');
  if random() < 0.05 then
    delete from public.reconciliation_tokens where expires_at < now() - interval '7 days';
  end if;
  return json_build_object('ok', true, 'token', v_token);
end;
$fn$;
-- Not granted to anon/authenticated — only the weekly-dispatch Edge
-- Function (service_role) ever mints one of these.

create or replace function public.resolve_reconciliation_token(p_token text)
returns uuid
language sql stable security definer set search_path = public as $fn$
  select salon_id from public.reconciliation_tokens
   where token_hash = encode(digest(coalesce(p_token, ''), 'sha256'), 'hex')
     and used_at is null and expires_at > now();
$fn$;

-- ----------------------------------------------------------------------------
-- get_reconciliation_queue — what the owner's magic-link page loads: every
-- pending_verification appointment for their salon, oldest first.
-- ----------------------------------------------------------------------------
create or replace function public.get_reconciliation_queue(p_token text)
returns table (
  id text, customer_name text, customer_phone text, service_id text,
  staff_id text, date date, start_min int, final_price bigint
)
language plpgsql stable security definer set search_path = public as $fn$
declare v_salon_id uuid;
begin
  v_salon_id := public.resolve_reconciliation_token(p_token);
  if v_salon_id is null then
    return;
  end if;
  return query
    select a.id, a.customer_name, a.customer_phone, a.service_id, a.staff_id, a.date, a.start_min, a.final_price
    from public.appointments a
    where a.salon_id = v_salon_id and a.status = 'pending_verification'
    order by a.date asc, a.start_min asc;
end;
$fn$;
grant execute on function public.get_reconciliation_queue(text) to anon, authenticated;

-- ----------------------------------------------------------------------------
-- submit_reconciliation_batch — the actual write. p_decisions is a JSON
-- array of {"id": "<appointment id>", "decision": "completed" | "no_show"}.
-- Strict tenant check: every appointment id must belong to the token's own
-- salon and still be pending_verification, or it's silently skipped (never
-- an error that would block the rest of a legitimate batch) — this is the
-- "strict tenant checks" requirement: an id from another salon, or
-- already resolved by someone else in the meantime, simply can't be
-- touched through this path, token or no token.
-- ----------------------------------------------------------------------------
create or replace function public.submit_reconciliation_batch(p_token text, p_decisions jsonb)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_salon_id uuid;
  v_decision jsonb;
  v_completed int := 0;
  v_no_show int := 0;
  v_skipped int := 0;
begin
  v_salon_id := public.resolve_reconciliation_token(p_token);
  if v_salon_id is null then
    return json_build_object('ok', false, 'error', 'این لینک منقضی یا نامعتبر است');
  end if;
  if jsonb_typeof(p_decisions) <> 'array' then
    return json_build_object('ok', false, 'error', 'ورودی نامعتبر است');
  end if;

  for v_decision in select * from jsonb_array_elements(p_decisions) loop
    if v_decision->>'decision' not in ('completed', 'no_show') then
      v_skipped := v_skipped + 1;
      continue;
    end if;
    update public.appointments
       set status = v_decision->>'decision'
     where id = v_decision->>'id'
       and salon_id = v_salon_id
       and status = 'pending_verification';
    if found then
      if v_decision->>'decision' = 'completed' then v_completed := v_completed + 1;
      else v_no_show := v_no_show + 1; end if;
    else
      v_skipped := v_skipped + 1;
    end if;
  end loop;

  return json_build_object('ok', true, 'completed', v_completed, 'no_show', v_no_show, 'skipped', v_skipped);
end;
$fn$;
grant execute on function public.submit_reconciliation_batch(text, jsonb) to anon, authenticated;


-- >>>>>>>>>> supabase/migrations/v2.26_predictive_part1_rebooking_tokens.sql
-- ============================================================================
-- Migration v2.26 — Predictive Autopilot (part 1 of 3): rebooking token
-- system (the shared mechanism behind Feature 2, used by both Feature 1's
-- closure-cancellation SMS and Feature 3's predictive re-engagement SMS)
-- ============================================================================
-- SECURITY DESIGN NOTE (deliberate departure from the spec's literal URL
-- shape): the spec's example URL is
--   /book?service_id={service_id}&client_id={client_id}&preferred_dates=...&token={secure_token}
-- Putting client_id and service_id in the URL ALONGSIDE the token invites
-- exactly the bug this changes: if the booking-creation step ever reads
-- customer identity from client_id instead of from the verified token,
-- anyone can edit the URL and book — or worse, directly CONFIRM a
-- booking — as a different customer, with zero verification. The actual
-- link this migration generates (see create_rebooking_token and its
-- callers in parts 2-3) carries ONLY the opaque token:
--   /book?token={secure_token}
-- service_id/staff_id/customer_phone are still available to the frontend
-- for pre-filling the page (via resolve_rebooking_token below), but they
-- come FROM the token's own resolution, server-side — never from a URL
-- parameter the client could edit. The actual write
-- (create_booking_from_rebooking_token, part 2) takes ONLY a token and a
-- chosen date/time; it has no customer_phone or service_id parameter at
-- all, so there is nothing for a tampered URL to override.
-- ============================================================================

create table if not exists public.rebooking_tokens (
  id               bigint generated always as identity primary key,
  salon_id         uuid not null references public.salons(id) on delete cascade,
  token_hash       text not null unique,
  customer_phone   text not null,
  customer_name    text not null default '',
  service_id       text references public.services(id) on delete set null,
  staff_id         text references public.stylists(id) on delete set null,
  reason           text not null default 'manual' check (reason in ('closure', 'predictive', 'manual')),
  expires_at       timestamptz not null,
  used_at          timestamptz,
  created_at       timestamptz not null default now()
);
create index if not exists rebooking_tokens_salon_idx on public.rebooking_tokens (salon_id);
alter table public.rebooking_tokens enable row level security;
-- No policies at all — reachable only through the SECURITY DEFINER
-- functions below, same pattern as every other token table in this app.

create or replace function public.create_rebooking_token(
  p_salon_id uuid, p_customer_phone text, p_service_id text default null,
  p_staff_id text default null, p_reason text default 'manual'
)
returns text
language plpgsql security definer set search_path = public as $fn$
declare v_token text; v_hash text; v_name text;
begin
  select name into v_name from public.customers where salon_id = p_salon_id and phone = p_customer_phone;
  v_token := encode(gen_random_bytes(32), 'hex');
  v_hash := encode(digest(v_token, 'sha256'), 'hex');
  insert into public.rebooking_tokens (salon_id, token_hash, customer_phone, customer_name, service_id, staff_id, reason, expires_at)
  values (p_salon_id, v_hash, p_customer_phone, coalesce(v_name, ''), p_service_id, p_staff_id, p_reason, now() + interval '14 days');
  if random() < 0.02 then
    delete from public.rebooking_tokens where expires_at < now() - interval '30 days';
  end if;
  return v_token;
end;
$fn$;
-- Not granted to anon/authenticated directly — only ever called FROM
-- another SECURITY DEFINER function (handle_closure_announcement, the
-- predictive cron function), never by a client request. A manager-facing
-- "send a rebooking link manually" action would call it the same way
-- these do, through a thin wrapper RPC with its own manager/tenant check
-- — not by granting this one directly, to keep the single-use/expiry
-- bookkeeping in one place.

-- ----------------------------------------------------------------------------
-- resolve_rebooking_token — what the /book page calls on load to find out
-- what it's actually offering (salon, suggested service/staff, the
-- customer's own name for a personalized greeting) — all derived from the
-- token, never echoed back from whatever the client happened to pass in
-- the URL.
-- ----------------------------------------------------------------------------
create or replace function public.resolve_rebooking_token(p_token text)
returns json
language sql stable security definer set search_path = public as $fn$
  select case when rt.id is null then json_build_object('ok', false, 'error', 'این لینک منقضی یا نامعتبر است')
    else json_build_object(
      'ok', true,
      'salon_id', rt.salon_id,
      'salon_name', s.name,
      'salon_slug', s.slug,
      'customer_name', rt.customer_name,
      'service_id', rt.service_id,
      'service_name', svc.name,
      'staff_id', rt.staff_id,
      'staff_name', st.name
    )
  end
  from (select 1) as dummy
  left join public.rebooking_tokens rt
    on rt.token_hash = encode(digest(coalesce(p_token, ''), 'sha256'), 'hex')
   and rt.used_at is null and rt.expires_at > now()
  left join public.salons s on s.id = rt.salon_id
  left join public.services svc on svc.id = rt.service_id and svc.salon_id = rt.salon_id
  left join public.stylists st on st.id = rt.staff_id and st.salon_id = rt.salon_id;
$fn$;
grant execute on function public.resolve_rebooking_token(text) to anon, authenticated;

-- ----------------------------------------------------------------------------
-- create_booking_from_rebooking_token — the actual write. Deliberately
-- takes ONLY the token plus scheduling choices (date, time, optional
-- staff override) — no customer_phone, no service_id parameter at all.
-- Everything identity-bearing comes from resolving the token itself, so
-- there is no field here a tampered request could override to book (or
-- worse, instantly CONFIRM) as someone else. Mirrors create_public_
-- booking's own validation (closures, working hours, exclusion handling)
-- but sets status = 'confirmed' directly — the token already represents a
-- verified, pre-existing customer relationship, so skipping the manual
-- review step a brand-new anonymous booking would need is a reasonable,
-- bounded exception, not a general bypass.
-- ----------------------------------------------------------------------------
create or replace function public.create_booking_from_rebooking_token(
  p_token text, p_date date, p_start_min int, p_staff_id text default null
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_rt record; v_svc record; v_wh record; v_app_dow int; v_wh_start int; v_wh_end int;
  v_end_min int; v_id text; v_code text; v_original bigint; v_svc_discount bigint;
  v_after_svc bigint; v_loyalty_pct int := 0; v_final bigint; v_loyalty json; v_code_bytes bytea;
  v_staff_id text;
begin
  select * into v_rt from public.rebooking_tokens
   where token_hash = encode(digest(coalesce(p_token, ''), 'sha256'), 'hex')
     and used_at is null and expires_at > now();
  if v_rt is null then
    return json_build_object('ok', false, 'error', 'این لینک منقضی یا نامعتبر است');
  end if;
  if v_rt.service_id is null then
    return json_build_object('ok', false, 'error', 'این لینک برای خدمت مشخصی نیست');
  end if;
  if p_date < current_date then
    return json_build_object('ok', false, 'error', 'تاریخ گذشته قابل انتخاب نیست');
  end if;
  if not exists (select 1 from public.approved_dates where date = p_date and salon_id = v_rt.salon_id) then
    return json_build_object('ok', false, 'error', 'این روز برای رزرو باز نشده است');
  end if;
  if exists (select 1 from public.salon_closures where salon_id = v_rt.salon_id and closure_date = p_date and is_active) then
    return json_build_object('ok', false, 'error', 'سالن در این روز تعطیل است');
  end if;

  -- Staff can be the one the customer originally had, or a different one
  -- the customer actively chooses on the booking page — either way it's
  -- just "who performs the service", not an identity field, so it's safe
  -- to accept as a direct parameter (validated against this same salon).
  v_staff_id := coalesce(p_staff_id, v_rt.staff_id);
  select * into v_svc from public.services where id = v_rt.service_id and salon_id = v_rt.salon_id and is_active;
  if v_svc is null then
    return json_build_object('ok', false, 'error', 'خدمت یافت نشد یا غیرفعال است');
  end if;
  if v_staff_id is not null and not exists (select 1 from public.stylists where id = v_staff_id and salon_id = v_rt.salon_id and active) then
    return json_build_object('ok', false, 'error', 'آرایشگر یافت نشد یا غیرفعال است');
  end if;

  v_app_dow := (extract(dow from p_date)::int + 1) % 7;
  select * into v_wh from public.working_hours
   where day_of_week = v_app_dow and staff_id = v_staff_id and salon_id = v_rt.salon_id;
  if v_wh is null then
    select * into v_wh from public.working_hours
     where day_of_week = v_app_dow and staff_id is null and salon_id = v_rt.salon_id;
  end if;
  if v_wh is null or v_wh.is_closed then
    return json_build_object('ok', false, 'error', 'در این روز سالن یا آرایشگر تعطیل است');
  end if;
  v_wh_start := split_part(v_wh.start_time, ':', 1)::int * 60 + split_part(v_wh.start_time, ':', 2)::int;
  v_wh_end := split_part(v_wh.end_time, ':', 1)::int * 60 + split_part(v_wh.end_time, ':', 2)::int;
  v_end_min := p_start_min + v_svc.duration_minutes;
  if p_start_min < v_wh_start or v_end_min > v_wh_end then
    return json_build_object('ok', false, 'error', 'خارج از ساعات کاری است');
  end if;

  v_original := coalesce(v_svc.price, 0);
  v_svc_discount := case
    when v_svc.discount_type = 'percent' then round(v_original * v_svc.discount_value / 100.0)
    when v_svc.discount_type = 'fixed' then v_svc.discount_value
    else 0
  end;
  v_after_svc := greatest(0, v_original - v_svc_discount);
  if v_svc.price is not null then
    v_loyalty := public.customer_loyalty(v_rt.customer_phone);
    if (v_loyalty->>'found')::boolean then
      v_loyalty_pct := coalesce((v_loyalty->>'discount_percent')::int, 0);
    end if;
  end if;
  v_final := case when v_svc.price is null then null
                  else greatest(0, v_after_svc - round(v_after_svc * v_loyalty_pct / 100.0)) end;

  v_id := 'apt-' || substr(md5(gen_random_uuid()::text), 1, 16);
  v_code_bytes := gen_random_bytes(4);
  v_code := 'MN-' || lpad((
    ((get_byte(v_code_bytes, 0)::bigint << 24) | (get_byte(v_code_bytes, 1)::bigint << 16)
     | (get_byte(v_code_bytes, 2)::bigint << 8) | get_byte(v_code_bytes, 3)::bigint) % 90000 + 10000
  )::text, 5, '0');

  begin
    insert into public.appointments (
      id, salon_id, customer_name, customer_phone, customer_gender, service_id, staff_id,
      staff_name, date, start_min, end_min, buffer_minutes, status,
      tracking_code, original_price, discount_type, discount_value, discount_reason, final_price
    ) values (
      v_id, v_rt.salon_id,
      coalesce(nullif(v_rt.customer_name, ''), (select name from public.customers where salon_id = v_rt.salon_id and phone = v_rt.customer_phone), ''),
      v_rt.customer_phone, v_svc.gender, v_rt.service_id, v_staff_id,
      coalesce((select name from public.stylists where id = v_staff_id and salon_id = v_rt.salon_id), ''),
      p_date, p_start_min, v_end_min, v_svc.buffer_minutes, 'confirmed',
      v_code, v_original, v_svc.discount_type, v_svc.discount_value,
      case when v_loyalty_pct > 0 then v_svc.discount_reason || case when v_svc.discount_reason <> '' then ' · ' else '' end || v_loyalty_pct || '٪ تخفیف باشگاه مشتریان' else v_svc.discount_reason end,
      v_final
    );
  exception when exclusion_violation then
    return json_build_object('ok', false, 'error', 'این زمان قبلاً رزرو شده — زمان دیگری انتخاب کنید');
  end;

  update public.rebooking_tokens set used_at = now() where id = v_rt.id;

  return json_build_object(
    'ok', true, 'id', v_id, 'tracking_code', v_code, 'final_price', v_final,
    'original_price', v_original, 'staff_name', coalesce((select name from public.stylists where id = v_staff_id and salon_id = v_rt.salon_id), '')
  );
end;
$fn$;
grant execute on function public.create_booking_from_rebooking_token(text, date, int, text) to anon, authenticated;

-- ----------------------------------------------------------------------------
-- get_available_slots_for_rebooking — what the /book page calls once the
-- customer picks a date, to show real open time slots (in
-- service-duration-sized steps) for the token's salon/service/staff.
-- Read-only; reuses the same working-hours/closure/overlap rules
-- create_booking_from_rebooking_token itself enforces on write, so what's
-- offered here is always actually bookable.
-- ----------------------------------------------------------------------------
create or replace function public.get_available_slots_for_rebooking(p_token text, p_date date, p_staff_id text default null)
returns table (start_min int)
language plpgsql stable security definer set search_path = public as $fn$
declare
  v_rt record; v_svc record; v_wh record; v_app_dow int; v_wh_start int; v_wh_end int;
  v_staff_id text; v_step int; v_t int;
begin
  select * into v_rt from public.rebooking_tokens
   where token_hash = encode(digest(coalesce(p_token, ''), 'sha256'), 'hex')
     and used_at is null and expires_at > now();
  if v_rt is null or v_rt.service_id is null then
    return;
  end if;
  if p_date < current_date
     or not exists (select 1 from public.approved_dates where date = p_date and salon_id = v_rt.salon_id)
     or exists (select 1 from public.salon_closures where salon_id = v_rt.salon_id and closure_date = p_date and is_active)
  then
    return;
  end if;

  v_staff_id := coalesce(p_staff_id, v_rt.staff_id);
  select * into v_svc from public.services where id = v_rt.service_id and salon_id = v_rt.salon_id and is_active;
  if v_svc is null then
    return;
  end if;

  v_app_dow := (extract(dow from p_date)::int + 1) % 7;
  select * into v_wh from public.working_hours
   where day_of_week = v_app_dow and staff_id = v_staff_id and salon_id = v_rt.salon_id;
  if v_wh is null then
    select * into v_wh from public.working_hours
     where day_of_week = v_app_dow and staff_id is null and salon_id = v_rt.salon_id;
  end if;
  if v_wh is null or v_wh.is_closed then
    return;
  end if;
  v_wh_start := split_part(v_wh.start_time, ':', 1)::int * 60 + split_part(v_wh.start_time, ':', 2)::int;
  v_wh_end := split_part(v_wh.end_time, ':', 1)::int * 60 + split_part(v_wh.end_time, ':', 2)::int;
  v_step := greatest(15, v_svc.duration_minutes);

  v_t := v_wh_start;
  while v_t + v_svc.duration_minutes <= v_wh_end loop
    if v_staff_id is null or not exists (
      select 1 from public.appointments ap
      where ap.salon_id = v_rt.salon_id and ap.staff_id = v_staff_id and ap.date = p_date
        and ap.status in ('pending', 'confirmed', 'rescheduled')
        and int4range(ap.start_min, ap.end_min + ap.buffer_minutes) && int4range(v_t, v_t + v_svc.duration_minutes + v_svc.buffer_minutes)
    ) then
      start_min := v_t;
      return next;
    end if;
    v_t := v_t + v_step;
  end loop;
end;
$fn$;
grant execute on function public.get_available_slots_for_rebooking(text, date, text) to anon, authenticated;


-- >>>>>>>>>> supabase/migrations/v2.26_predictive_part2_closures.sql
-- ============================================================================
-- Migration v2.26 — Predictive Autopilot (part 1 of 3): Smart Absence &
-- Holiday Management (Zero-Touch Closure)
-- ============================================================================
-- A closure needs to do TWO things, not just one: cancel appointments that
-- already exist on that date, AND stop NEW bookings from being made on it.
-- The spec's own text only describes the first half explicitly — this
-- migration implements both, since a closure that still lets customers
-- book fresh appointments on the "closed" day would be a logical
-- contradiction, not a smaller version of the feature.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1) New terminal status: cancelled_by_salon — distinct from a customer's
--    own cancellation, so analytics/reporting can tell the two apart (a
--    salon-initiated cancellation is a service failure worth tracking
--    separately from a customer changing their mind). Revenue eligibility
--    is unaffected either way (isRevenueEligible only ever allows
--    'completed' — see v2.25), and this status is excluded from the
--    overlap-prevention exclusion constraint exactly like 'cancelled'
--    already is (see the update to appointments_no_overlap below — it
--    only ever covered pending/confirmed/rescheduled, so a cancelled_by_
--    salon row was never going to block a new booking in that slot;
--    no constraint change needed there specifically, confirmed by reading
--    it again here).
-- ----------------------------------------------------------------------------
alter table public.appointments drop constraint if exists appointments_status_check;
alter table public.appointments add constraint appointments_status_check
  check (status in (
    'pending','confirmed','cancelled','rescheduled','completed','no_show',
    'reschedule_proposed','pending_verification','archived_unconfirmed',
    'cancelled_by_salon'
  ));

-- ----------------------------------------------------------------------------
-- 2) salon_closures — richer than approved_dates (which is just a plain
--    open/closed flag): a reason, a note, and independent of whether the
--    date was ever marked "open" in the first place.
-- ----------------------------------------------------------------------------
create table if not exists public.salon_closures (
  id            text primary key default 'clo-' || substr(md5(gen_random_uuid()::text), 1, 12),
  salon_id      uuid not null references public.salons(id) on delete cascade,
  closure_date  date not null,
  closure_type  text not null check (closure_type in ('holiday', 'maintenance', 'personal_leave')),
  notes         text not null default '',
  is_active     boolean not null default true,
  created_at    timestamptz not null default now(),
  unique (salon_id, closure_date)
);
create index if not exists salon_closures_salon_date_idx on public.salon_closures (salon_id, closure_date) where is_active;

alter table public.salon_closures enable row level security;
drop policy if exists p_closures_read on public.salon_closures;
create policy p_closures_read on public.salon_closures for select
  using (salon_id = public.current_salon_id());
drop policy if exists p_closures_write on public.salon_closures;
create policy p_closures_write on public.salon_closures for all
  using (public.is_manager() and salon_id = public.current_salon_id())
  with check (public.is_manager() and salon_id = public.current_salon_id());
grant select on public.salon_closures to anon, authenticated;
grant insert, update, delete on public.salon_closures to authenticated;

-- ----------------------------------------------------------------------------
-- 3) handle_closure_announcement — marks the date closed, cancels every
--    affected confirmed/rescheduled appointment, and QUEUES a rebooking
--    SMS for each (via sms_messages, picked up by cron-reminders' existing
--    DRAIN step — this RPC runs inside the database and has no way to
--    call an SMS provider directly, so it queues rather than sends; see
--    part 2 for the rebooking-token/link generation it uses per message).
-- ----------------------------------------------------------------------------
create or replace function public.handle_closure_announcement(
  p_salon_id uuid, p_closure_date date, p_closure_type text, p_notes text default ''
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_appt record;
  v_affected int := 0;
  v_reason_note text;
  v_token text;
  v_body text;
  v_salon_name text;
begin
  if not (public.is_manager() and p_salon_id = public.current_salon_id()) then
    return json_build_object('ok', false, 'error', 'دسترسی مجاز نیست');
  end if;
  if p_closure_type not in ('holiday', 'maintenance', 'personal_leave') then
    return json_build_object('ok', false, 'error', 'نوع تعطیلی نامعتبر است');
  end if;

  insert into public.salon_closures (salon_id, closure_date, closure_type, notes, is_active)
  values (p_salon_id, p_closure_date, p_closure_type, coalesce(p_notes, ''), true)
  on conflict (salon_id, closure_date) do update
    set closure_type = excluded.closure_type, notes = excluded.notes, is_active = true;

  select name into v_salon_name from public.salons where id = p_salon_id;
  v_reason_note := case p_closure_type
    when 'holiday' then ''
    else ' (تعطیلی ناگهانی به دلیل ' || case p_closure_type when 'maintenance' then 'تعمیرات' else 'مرخصی' end || ')'
  end;

  for v_appt in
    select * from public.appointments
     where salon_id = p_salon_id and date = p_closure_date
       and status in ('confirmed', 'rescheduled')
  loop
    update public.appointments set status = 'cancelled_by_salon' where id = v_appt.id;
    v_affected := v_affected + 1;

    -- A single-use rebooking token (part 1) tied to this customer's own
    -- phone and service — never the raw phone/service in the SMS URL
    -- itself, only an opaque token the frontend/RPC resolve server-side.
    v_token := public.create_rebooking_token(p_salon_id, v_appt.customer_phone, v_appt.service_id, v_appt.staff_id, 'closure');

    v_body := coalesce(v_salon_name, 'سالن') || ': متاسفانه نوبت شما در این تاریخ به دلیل تعطیلی لغو شد' || v_reason_note || '. '
      || 'برای رزرو زمان جدید لمس کنید: '
      || coalesce(current_setting('app.base_url', true), '') || '/book?token=' || v_token;

    insert into public.sms_messages (salon_id, to_phone, body, kind, appointment_id, status, scheduled_for)
    values (p_salon_id, v_appt.customer_phone, v_body, 'cancellation', v_appt.id, 'queued', now());
  end loop;

  return json_build_object('ok', true, 'affected_appointments', v_affected);
end;
$fn$;
grant execute on function public.handle_closure_announcement(uuid, date, text, text) to authenticated;

-- ----------------------------------------------------------------------------
-- 4) Integration: create_public_booking must also refuse a date that has
--    an active closure — otherwise closing a day cancels existing bookings
--    but silently lets new ones land on the very same date, which isn't a
--    smaller version of "closed", it's a contradiction of it.
-- ----------------------------------------------------------------------------
create or replace function public.create_public_booking(
  p_service_id text, p_staff_id text, p_date date, p_start_min int,
  p_customer_name text, p_customer_phone text, p_customer_gender text,
  p_referral_code text default null
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_svc record; v_wh record; v_app_dow int; v_wh_start int; v_wh_end int;
  v_end_min int; v_id text; v_code text; v_original bigint; v_svc_discount bigint;
  v_after_svc bigint; v_loyalty_pct int := 0; v_final bigint; v_loyalty json; v_code_bytes bytea;
  v_salon_id uuid;
begin
  v_salon_id := public.current_salon_id();
  if v_salon_id is null then
    return json_build_object('ok', false, 'error', 'سالن نامعتبر است');
  end if;
  if p_customer_phone !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شماره موبایل نامعتبر است');
  end if;
  if coalesce(trim(p_customer_name), '') = '' then
    return json_build_object('ok', false, 'error', 'نام لازم است');
  end if;
  if p_customer_gender not in ('female', 'male') then
    return json_build_object('ok', false, 'error', 'جنسیت نامعتبر است');
  end if;
  if not public.check_rate_limit('create_booking:' || v_salon_id || ':' || p_customer_phone, 10, 30) then
    return json_build_object('ok', false, 'error', 'تعداد درخواست بیش از حد مجاز است — کمی بعد دوباره امتحان کنید');
  end if;
  if p_date < current_date then
    return json_build_object('ok', false, 'error', 'تاریخ گذشته قابل انتخاب نیست');
  end if;
  if not exists (select 1 from public.approved_dates where date = p_date and salon_id = v_salon_id) then
    return json_build_object('ok', false, 'error', 'این روز برای رزرو باز نشده است');
  end if;
  if exists (select 1 from public.salon_closures where salon_id = v_salon_id and closure_date = p_date and is_active) then
    return json_build_object('ok', false, 'error', 'سالن در این روز تعطیل است');
  end if;

  select * into v_svc from public.services where id = p_service_id and salon_id = v_salon_id and is_active;
  if v_svc is null then
    return json_build_object('ok', false, 'error', 'خدمت یافت نشد یا غیرفعال است');
  end if;
  if v_svc.gender <> p_customer_gender then
    return json_build_object('ok', false, 'error', 'این خدمت با جنسیت انتخابی مطابقت ندارد');
  end if;

  if p_staff_id is not null and not exists (select 1 from public.stylists where id = p_staff_id and salon_id = v_salon_id and active) then
    return json_build_object('ok', false, 'error', 'آرایشگر یافت نشد یا غیرفعال است');
  end if;

  v_app_dow := (extract(dow from p_date)::int + 1) % 7;
  select * into v_wh from public.working_hours
   where day_of_week = v_app_dow and staff_id = p_staff_id and salon_id = v_salon_id;
  if v_wh is null then
    select * into v_wh from public.working_hours
     where day_of_week = v_app_dow and staff_id is null and salon_id = v_salon_id;
  end if;
  if v_wh is null or v_wh.is_closed then
    return json_build_object('ok', false, 'error', 'در این روز سالن یا آرایشگر تعطیل است');
  end if;
  v_wh_start := split_part(v_wh.start_time, ':', 1)::int * 60 + split_part(v_wh.start_time, ':', 2)::int;
  v_wh_end := split_part(v_wh.end_time, ':', 1)::int * 60 + split_part(v_wh.end_time, ':', 2)::int;
  v_end_min := p_start_min + v_svc.duration_minutes;
  if p_start_min < v_wh_start or v_end_min > v_wh_end then
    return json_build_object('ok', false, 'error', 'خارج از ساعات کاری است');
  end if;

  v_original := coalesce(v_svc.price, 0);
  v_svc_discount := case
    when v_svc.discount_type = 'percent' then round(v_original * v_svc.discount_value / 100.0)
    when v_svc.discount_type = 'fixed' then v_svc.discount_value
    else 0
  end;
  v_after_svc := greatest(0, v_original - v_svc_discount);
  if v_svc.price is not null then
    v_loyalty := public.customer_loyalty(p_customer_phone);
    if (v_loyalty->>'found')::boolean then
      v_loyalty_pct := coalesce((v_loyalty->>'discount_percent')::int, 0);
    end if;
  end if;
  v_final := case when v_svc.price is null then null
                  else greatest(0, v_after_svc - round(v_after_svc * v_loyalty_pct / 100.0)) end;

  v_id := 'apt-' || substr(md5(gen_random_uuid()::text), 1, 16);
  v_code_bytes := gen_random_bytes(4);
  v_code := 'MN-' || lpad((
    ((get_byte(v_code_bytes, 0)::bigint << 24) | (get_byte(v_code_bytes, 1)::bigint << 16)
     | (get_byte(v_code_bytes, 2)::bigint << 8) | get_byte(v_code_bytes, 3)::bigint) % 90000 + 10000
  )::text, 5, '0');

  begin
    insert into public.appointments (
      id, salon_id, customer_name, customer_phone, customer_gender, service_id, staff_id,
      staff_name, date, start_min, end_min, buffer_minutes, status,
      tracking_code, original_price, discount_type, discount_value, discount_reason, final_price
    ) values (
      v_id, v_salon_id, trim(p_customer_name), p_customer_phone, p_customer_gender, p_service_id, p_staff_id,
      coalesce((select name from public.stylists where id = p_staff_id and salon_id = v_salon_id), ''),
      p_date, p_start_min, v_end_min, v_svc.buffer_minutes, 'pending',
      v_code, v_original, v_svc.discount_type, v_svc.discount_value,
      case when v_loyalty_pct > 0 then v_svc.discount_reason || case when v_svc.discount_reason <> '' then ' · ' else '' end || v_loyalty_pct || '٪ تخفیف باشگاه مشتریان' else v_svc.discount_reason end,
      v_final
    );
  exception when exclusion_violation then
    return json_build_object('ok', false, 'error', 'این زمان قبلاً رزرو شده — زمان دیگری انتخاب کنید');
  end;

  if p_referral_code is not null and length(trim(p_referral_code)) > 0 then
    perform public.apply_referral(p_customer_phone, p_referral_code);
  end if;

  return json_build_object(
    'ok', true, 'id', v_id, 'tracking_code', v_code, 'final_price', v_final,
    'original_price', v_original, 'staff_name', coalesce((select name from public.stylists where id = p_staff_id and salon_id = v_salon_id), '')
  );
end;
$fn$;
grant execute on function public.create_public_booking(text, text, date, int, text, text, text, text) to anon, authenticated;


-- >>>>>>>>>> supabase/migrations/v2.26_predictive_part3_engine.sql
-- ============================================================================
-- Migration v2.26 — Predictive Autopilot (part 3 of 3): Predictive
-- Re-booking Engine
-- ============================================================================
-- Reuses part 1's rebooking_tokens/create_rebooking_token wholesale — the
-- spec explicitly frames this as the SAME dynamic-link mechanism as
-- Feature 2, just triggered by a different reason ('predictive' vs
-- 'closure'), so there's no separate token table or link format here.
-- ============================================================================

alter table public.services add column if not exists average_cycle_days int;
alter table public.services drop constraint if exists services_average_cycle_days_check;
alter table public.services add constraint services_average_cycle_days_check
  check (average_cycle_days is null or average_cycle_days > 0);

alter table public.sms_messages drop constraint if exists sms_messages_kind_check;
alter table public.sms_messages add constraint sms_messages_kind_check
  check (kind in ('confirmation','reminder','cancellation','reschedule','campaign','loyalty','custom','reconciliation_prompt','weekly_summary','predictive_rebooking'));

-- ----------------------------------------------------------------------------
-- run_predictive_rebooking — daily job. For every active salon, every
-- service with average_cycle_days set, finds each customer's own most
-- recent COMPLETED visit for that service, and queues an outreach SMS
-- when today falls in a short window around their typical due date
-- (cycle - 3 days through cycle + 2 days — a few days wide since this
-- only runs once a day and shouldn't miss someone or double-send across
-- runs).
--
-- Two exclusions that matter as much as the inclusion rule:
--   - a customer who ALREADY has an upcoming (pending/confirmed/
--     rescheduled/pending_verification) booking for the SAME service is
--     skipped outright — nagging someone who's already rebooked is
--     exactly the kind of "automation that annoys customers" this
--     feature is supposed to avoid, not cause.
--   - a customer who already got a 'predictive' token for this service
--     within the last 10 days is skipped too, so drifting through the
--     few-day window on consecutive daily runs doesn't send the same
--     nudge repeatedly.
-- ----------------------------------------------------------------------------
create or replace function public.run_predictive_rebooking()
returns int
language plpgsql security definer set search_path = public as $fn$
declare
  v_candidate record;
  v_token text;
  v_body text;
  v_sent int := 0;
begin
  for v_candidate in
    with last_visit as (
      select
        a.salon_id, a.customer_phone, a.service_id,
        max(a.date) as last_date,
        (array_agg(a.customer_name order by a.date desc))[1] as customer_name,
        (array_agg(a.staff_id order by a.date desc))[1] as staff_id
      from public.appointments a
      where a.status = 'completed'
      group by a.salon_id, a.customer_phone, a.service_id
    )
    select
      lv.salon_id, lv.customer_phone, lv.customer_name, lv.service_id, lv.staff_id,
      s.name as service_name, s.average_cycle_days, lv.last_date,
      sal.name as salon_name
    from last_visit lv
    join public.services s on s.id = lv.service_id and s.salon_id = lv.salon_id and s.is_active
    join public.salons sal on sal.id = lv.salon_id and sal.active
    where s.average_cycle_days is not null
      and current_date between
            lv.last_date + (s.average_cycle_days - 3)
        and lv.last_date + (s.average_cycle_days + 2)
      -- not already upcoming for the same service
      and not exists (
        select 1 from public.appointments up
        where up.salon_id = lv.salon_id and up.customer_phone = lv.customer_phone and up.service_id = lv.service_id
          and up.status in ('pending', 'confirmed', 'rescheduled', 'pending_verification')
          and up.date >= current_date
      )
      -- not already nudged recently for this same service
      and not exists (
        select 1 from public.rebooking_tokens rt
        where rt.salon_id = lv.salon_id and rt.customer_phone = lv.customer_phone and rt.service_id = lv.service_id
          and rt.reason = 'predictive' and rt.created_at > now() - interval '10 days'
      )
      -- respects opt-out — this is a retention/marketing nudge, not a
      -- transactional message, and the queued-message send path (unlike
      -- send-sms's direct "send" action) has no opt-out check of its own
      and not coalesce(
        (select c.sms_opt_out from public.customers c where c.salon_id = lv.salon_id and c.phone = lv.customer_phone),
        false
      )
  loop
    v_token := public.create_rebooking_token(
      v_candidate.salon_id, v_candidate.customer_phone, v_candidate.service_id, v_candidate.staff_id, 'predictive'
    );

    v_body := 'سلام ' || nullif(trim(v_candidate.customer_name), '') || E'\n' ||
      'وقتشه برای ' || v_candidate.service_name || ' بعدی‌تون وقت بگیرید! برای حفظ ظاهرتون و رزرو زمان دلخواه، لمس کنید: ' ||
      coalesce(current_setting('app.base_url', true), '') || '/book?token=' || v_token;

    insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
    values (v_candidate.salon_id, v_candidate.customer_phone, v_body, 'predictive_rebooking', 'queued', now());

    v_sent := v_sent + 1;
  end loop;

  return v_sent;
end;
$fn$;
-- Not granted to anon/authenticated — only ever invoked by the daily
-- scheduler (an Edge Function using the service_role key), same access
-- pattern as transition_elapsed_appointments()/archive_stale_pending_
-- verifications() from v2.25.


-- >>>>>>>>>> supabase/migrations/v2.27_sms_fixes.sql
-- ============================================================================
-- Migration v2.27 — SMS fixes found during a user-reported investigation
-- ============================================================================
-- sms_messages.kind never included 'reschedule_proposed', 'feedback_request',
-- or 'feedback_followup' — three kinds the frontend has been sending via
-- sendBookingSms()/queueFeedbackFollowup() all along. The actual SMS still
-- goes out (the provider call doesn't check this constraint), but the
-- audit-log insert for it fails — and since the Edge Function inserts a
-- whole batch of audit rows in one INSERT, a single row with one of these
-- three kinds silently takes down the audit logging for every OTHER
-- message in that same batch too (Postgres aborts the entire INSERT on a
-- constraint violation, not just the offending row). Confirmed by
-- reproducing the exact constraint violation against real Postgres.
-- Also adds staff_new_booking, for the new stylist-notification message
-- added alongside this fix (see src/App.jsx).
-- ============================================================================

alter table public.sms_messages drop constraint if exists sms_messages_kind_check;
alter table public.sms_messages add constraint sms_messages_kind_check
  check (kind in (
    'confirmation','reminder','cancellation','reschedule','campaign','loyalty','custom',
    'reconciliation_prompt','weekly_summary','predictive_rebooking',
    'reschedule_proposed','feedback_request','feedback_followup','staff_new_booking'
  ));


-- >>>>>>>>>> supabase/migrations/v2.28_hands_off_automation.sql
-- ============================================================================
-- Migration v2.28 — Hands-off automation
-- ============================================================================
-- Goal: stylists and the salon manager should only need the app for things
-- that genuinely need a person. Three pieces, each switchable per salon in
-- app_settings (all ON by default):
--
--   1. auto_confirm_bookings — a booking that already passed every server
--      check in create_public_booking (working hours, closures, overlap
--      exclusion constraint) is created 'confirmed' instead of 'pending'.
--      Implemented as a BEFORE INSERT trigger so every creation path
--      (public booking, rebooking tokens) gets it without redefining each
--      RPC. Side effects that were silently broken for unconfirmed
--      bookings now just work: reminders (cron-reminders only sends for
--      confirmed/rescheduled) and the post-visit lifecycle
--      (transition_elapsed_appointments only picks up confirmed/
--      rescheduled).
--
--   2. auto_open_days + booking_window_days — instead of someone opening
--      each day by hand, open_booking_window() keeps the next N days in
--      approved_dates for every salon that has it on. Days that must stay
--      shut use the existing closures / time-off, exactly as before. The
--      existing RPCs that check approved_dates are untouched.
--      This also replaces the 'salon-roll-approved-dates' cron job, which
--      has been failing since v2.24 (it inserted without salon_id and used
--      the pre-multitenant `on conflict (date)` key).
--
--   3. staff_daily_digest / manager_daily_digest — queue_daily_digests()
--      queues ONE morning SMS per stylist with their day, and one short
--      summary per owner/manager (only when there's something to say).
--      Rows go into sms_messages as 'queued'; the existing cron-reminders
--      drain sends them, so there's no new Edge Function to deploy.
--
-- Schedule (see supabase/cron.sql):
--   select public.open_booking_window();   -- daily
--   select public.queue_daily_digests();   -- daily, before opening time
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 0) The salon's own calendar date. The database runs in UTC, so between
--    00:00 and 03:30 Tehran time current_date is still "yesterday".
--    Override with: alter database postgres set app.timezone = '...';
-- ----------------------------------------------------------------------------
create or replace function public.salon_today() returns date
language sql stable as $$
  select (now() at time zone coalesce(nullif(current_setting('app.timezone', true), ''), 'Asia/Tehran'))::date
$$;
grant execute on function public.salon_today() to anon, authenticated;

-- ----------------------------------------------------------------------------
-- 1) Settings
-- ----------------------------------------------------------------------------
alter table public.app_settings add column if not exists auto_confirm_bookings boolean not null default true;
alter table public.app_settings add column if not exists auto_open_days        boolean not null default true;
alter table public.app_settings add column if not exists booking_window_days   int     not null default 30;
alter table public.app_settings add column if not exists staff_daily_digest    boolean not null default true;
alter table public.app_settings add column if not exists manager_daily_digest  boolean not null default true;

alter table public.app_settings drop constraint if exists app_settings_booking_window_days_check;
alter table public.app_settings add constraint app_settings_booking_window_days_check
  check (booking_window_days between 7 and 90);

-- ----------------------------------------------------------------------------
-- 2) Auto-confirm
-- ----------------------------------------------------------------------------
create or replace function public.auto_confirm_new_appointment()
returns trigger
language plpgsql security definer set search_path = public as $fn$
begin
  if new.status = 'pending'
     and coalesce((select auto_confirm_bookings from public.app_settings where salon_id = new.salon_id), false)
  then
    new.status := 'confirmed';
  end if;
  return new;
end;
$fn$;

drop trigger if exists trg_auto_confirm_new_appointment on public.appointments;
create trigger trg_auto_confirm_new_appointment
  before insert on public.appointments
  for each row execute function public.auto_confirm_new_appointment();

-- Bookings already waiting on a manual confirm, in salons that now
-- auto-confirm: confirm them too, so nothing is left stuck in the old queue.
update public.appointments a
   set status = 'confirmed'
  from public.app_settings s
 where s.salon_id = a.salon_id
   and s.auto_confirm_bookings
   and a.status = 'pending'
   and a.date >= public.salon_today();

-- ----------------------------------------------------------------------------
-- 3) Rolling booking window
-- ----------------------------------------------------------------------------
create or replace function public.open_booking_window(p_salon_id uuid default null)
returns int
language plpgsql security definer set search_path = public as $fn$
declare v_added int;
begin
  insert into public.approved_dates (salon_id, date)
  select s.salon_id, (public.salon_today() + g.i)::date
    from public.app_settings s
    join public.salons sa on sa.id = s.salon_id and sa.active
    cross join lateral generate_series(0, s.booking_window_days - 1) as g(i)
   where s.auto_open_days
     and (p_salon_id is null or s.salon_id = p_salon_id)
  on conflict (salon_id, date) do nothing;
  get diagnostics v_added = row_count;
  return v_added;
end;
$fn$;
-- Scheduler-only for the all-salons form; a manager may (re)open their own
-- salon's window right after changing the setting — see the wrapper below.
revoke all on function public.open_booking_window(uuid) from public, anon, authenticated;

create or replace function public.open_my_booking_window()
returns int
language plpgsql security definer set search_path = public as $fn$
begin
  if not public.is_manager() then
    raise exception 'forbidden';
  end if;
  return public.open_booking_window(public.current_salon_id());
end;
$fn$;
grant execute on function public.open_my_booking_window() to authenticated;

-- Open the window once now, so turning this migration on doesn't wait a day.
select public.open_booking_window();

-- ----------------------------------------------------------------------------
-- 4) Morning digests
-- ----------------------------------------------------------------------------
alter table public.sms_messages drop constraint if exists sms_messages_kind_check;
alter table public.sms_messages add constraint sms_messages_kind_check
  check (kind in (
    'confirmation','reminder','cancellation','reschedule','campaign','loyalty','custom',
    'reconciliation_prompt','weekly_summary','predictive_rebooking',
    'reschedule_proposed','feedback_request','feedback_followup','staff_new_booking',
    'daily_digest'
  ));

create or replace function public.fa_digits(p text) returns text
language sql immutable as $$ select translate(p, '0123456789', '۰۱۲۳۴۵۶۷۸۹') $$;

create or replace function public.fa_clock(p_min int) returns text
language sql immutable as $$
  select public.fa_digits(lpad((p_min / 60)::text, 2, '0') || ':' || lpad((p_min % 60)::text, 2, '0'))
$$;

create or replace function public.queue_daily_digests(p_date date default public.salon_today())
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_set record; v_st record; v_mgr record;
  v_lines text; v_count int; v_body text;
  v_total int; v_unassigned int; v_pending int; v_waitlist int;
  v_staff_sent int := 0; v_mgr_sent int := 0;
  c_max_lines constant int := 8; -- keeps the SMS to a couple of parts at most
begin
  for v_set in
    select s.*, sa.name as salon_name
      from public.app_settings s
      join public.salons sa on sa.id = s.salon_id and sa.active
     where s.staff_daily_digest or s.manager_daily_digest
  loop
    -- One SMS per stylist who has bookings today. No bookings = no SMS.
    if v_set.staff_daily_digest then
      for v_st in
        select st.id, st.name, st.phone
          from public.stylists st
         where st.salon_id = v_set.salon_id and st.active and st.phone ~ '^09[0-9]{9}$'
      loop
        select count(*),
               string_agg(public.fa_clock(x.start_min) || ' ' || x.customer_name || ' — ' || x.service_name, E'\n' order by x.start_min)
                 filter (where x.rn <= c_max_lines)
          into v_count, v_lines
          from (
            select a.start_min, a.customer_name, coalesce(sv.name, 'خدمت') as service_name,
                   row_number() over (order by a.start_min) as rn
              from public.appointments a
              left join public.services sv on sv.id = a.service_id and sv.salon_id = a.salon_id
             where a.salon_id = v_set.salon_id and a.staff_id = v_st.id and a.date = p_date
               and a.status in ('confirmed', 'rescheduled', 'pending')
          ) x;

        continue when coalesce(v_count, 0) = 0;
        -- Never queue the same digest twice for the same day (re-runs are safe).
        continue when exists (
          select 1 from public.sms_messages m
           where m.salon_id = v_set.salon_id and m.kind = 'daily_digest'
             and m.to_phone = v_st.phone and m.created_at > now() - interval '20 hours'
        );

        v_body := 'برنامهٔ امروز شما (' || public.fa_digits(v_count::text) || ' نوبت):' || E'\n' || v_lines
               || case when v_count > c_max_lines
                       then E'\n' || 'و ' || public.fa_digits((v_count - c_max_lines)::text) || ' نوبت دیگر'
                       else '' end;
        insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
        values (v_set.salon_id, v_st.phone, v_body, 'daily_digest', 'queued', now());
        v_staff_sent := v_staff_sent + 1;
      end loop;
    end if;

    -- One short summary per owner/manager — only the numbers that matter
    -- and only what actually needs a person. Nothing to report = no SMS.
    if v_set.manager_daily_digest then
      select count(*) filter (where status in ('confirmed', 'rescheduled', 'pending')),
             count(*) filter (where status in ('confirmed', 'rescheduled', 'pending') and staff_id is null),
             count(*) filter (where status = 'pending')
        into v_total, v_unassigned, v_pending
        from public.appointments
       where salon_id = v_set.salon_id and date = p_date;
      select count(*) into v_waitlist from public.waitlist where salon_id = v_set.salon_id and date = p_date;

      if v_total > 0 or v_pending > 0 then
        v_body := v_set.salon_name || ' — امروز ' || public.fa_digits(v_total::text) || ' نوبت.'
          || case when v_unassigned > 0 then E'\n' || '⚠ ' || public.fa_digits(v_unassigned::text) || ' نوبت بدون آرایشگر' else '' end
          || case when v_pending > 0 then E'\n' || '⚠ ' || public.fa_digits(v_pending::text) || ' نوبت منتظر تایید شما' else '' end
          || case when v_waitlist > 0 then E'\n' || public.fa_digits(v_waitlist::text) || ' نفر در لیست انتظار امروز' else '' end;

        for v_mgr in
          select u.phone from public.users u
           where u.salon_id = v_set.salon_id and u.active and u.role in ('owner', 'manager')
             and u.phone ~ '^09[0-9]{9}$'
        loop
          continue when exists (
            select 1 from public.sms_messages m
             where m.salon_id = v_set.salon_id and m.kind = 'daily_digest'
               and m.to_phone = v_mgr.phone and m.created_at > now() - interval '20 hours'
          );
          insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
          values (v_set.salon_id, v_mgr.phone, v_body, 'daily_digest', 'queued', now());
          v_mgr_sent := v_mgr_sent + 1;
        end loop;
      end if;
    end if;
  end loop;

  return json_build_object('ok', true, 'staff', v_staff_sent, 'managers', v_mgr_sent);
end;
$fn$;
revoke all on function public.queue_daily_digests(date) from public, anon, authenticated;


-- >>>>>>>>>> supabase/migrations/v2.29_waitlist_and_attendance.sql
-- ============================================================================
-- Migration v2.29 — Waitlist auto-offer + customer attendance confirmation
-- ============================================================================
-- Continues v2.28 (hands-off automation). Two more jobs move from people to
-- the system, each switchable per salon in app_settings (both ON by default):
--
--   1. waitlist_auto_offer — when a booking is cancelled, everyone on that
--      day's waitlist gets an SMS with a single-use booking link (the
--      existing /book?token=… page from v2.26, now pre-set to the freed
--      day). First to book gets the slot. Nobody has to phone anyone.
--      Booking (by any path) removes that customer from that day's list.
--
--   2. attendance_confirmation — every reminder SMS carries a personal link
--      to /confirm?token=… where the customer taps "I'll be there" or
--      "I can't make it". Declining cancels the booking, which in turn
--      offers the slot to the waitlist (1) — a no-show turned into a
--      re-filled slot with zero staff involvement.
--
--   Plus: any cancellation of a booking for TODAY sends the stylist a short
--   SMS (the morning digest from v2.28 already went out, so this is the one
--   change they need to hear about straight away).
--
-- Links need the public site address. Set it once (see DEPLOY.md):
--   alter database postgres set app.base_url = 'https://your-domain.com';
-- Without it no link is sent (the closure/predictive SMS from v2.26 had the
-- same dependency, undocumented until now).
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 0) Settings, SMS kinds, link helper
-- ----------------------------------------------------------------------------
alter table public.app_settings add column if not exists waitlist_auto_offer     boolean not null default true;
alter table public.app_settings add column if not exists attendance_confirmation boolean not null default true;

alter table public.sms_messages drop constraint if exists sms_messages_kind_check;
alter table public.sms_messages add constraint sms_messages_kind_check
  check (kind in (
    'confirmation','reminder','cancellation','reschedule','campaign','loyalty','custom',
    'reconciliation_prompt','weekly_summary','predictive_rebooking',
    'reschedule_proposed','feedback_request','feedback_followup','staff_new_booking',
    'daily_digest','waitlist_offer','staff_change'
  ));

-- Absolute link to a public page, or NULL when app.base_url isn't set (so
-- callers can skip the link instead of sending a broken relative one).
create or replace function public.public_link(p_path text) returns text
language sql stable as $$
  select case when coalesce(current_setting('app.base_url', true), '') = '' then null
              else rtrim(current_setting('app.base_url', true), '/') || p_path end
$$;

-- ----------------------------------------------------------------------------
-- 1) Waitlist auto-offer
-- ----------------------------------------------------------------------------
alter table public.rebooking_tokens add column if not exists preferred_date date;
alter table public.rebooking_tokens drop constraint if exists rebooking_tokens_reason_check;
alter table public.rebooking_tokens add constraint rebooking_tokens_reason_check
  check (reason in ('closure', 'predictive', 'manual', 'waitlist'));

alter table public.waitlist add column if not exists notified_at timestamptz;

-- resolve_rebooking_token now also tells the page why the link was sent and
-- which day to open on.
create or replace function public.resolve_rebooking_token(p_token text)
returns json
language sql stable security definer set search_path = public as $fn$
  select case when rt.id is null then json_build_object('ok', false, 'error', 'این لینک منقضی یا نامعتبر است')
    else json_build_object(
      'ok', true,
      'salon_id', rt.salon_id,
      'salon_name', s.name,
      'salon_slug', s.slug,
      'customer_name', rt.customer_name,
      'service_id', rt.service_id,
      'service_name', svc.name,
      'staff_id', rt.staff_id,
      'staff_name', st.name,
      'reason', rt.reason,
      'preferred_date', rt.preferred_date
    )
  end
  from (select 1) as dummy
  left join public.rebooking_tokens rt
    on rt.token_hash = encode(digest(coalesce(p_token, ''), 'sha256'), 'hex')
   and rt.used_at is null and rt.expires_at > now()
  left join public.salons s on s.id = rt.salon_id
  left join public.services svc on svc.id = rt.service_id and svc.salon_id = rt.salon_id
  left join public.stylists st on st.id = rt.staff_id and st.salon_id = rt.salon_id;
$fn$;
grant execute on function public.resolve_rebooking_token(text) to anon, authenticated;

create or replace function public.on_appointment_cancelled()
returns trigger
language plpgsql security definer set search_path = public as $fn$
declare
  v_set record; v_w record; v_token text; v_link text; v_salon_name text;
  v_staff_phone text; v_service_name text; v_offered int := 0;
  c_max_offers constant int := 5;
begin
  if new.status <> 'cancelled' or old.status not in ('pending', 'confirmed', 'rescheduled', 'reschedule_proposed') then
    return new;
  end if;
  if new.date < public.salon_today() then
    return new;
  end if;

  select * into v_set from public.app_settings where salon_id = new.salon_id;
  select name into v_salon_name from public.salons where id = new.salon_id;

  -- Same-day change: tell the stylist now (their morning digest is stale).
  if new.date = public.salon_today() and new.staff_id is not null and coalesce(v_set.staff_daily_digest, false) then
    select phone into v_staff_phone from public.stylists where id = new.staff_id and salon_id = new.salon_id;
    select name into v_service_name from public.services where id = new.service_id and salon_id = new.salon_id;
    if v_staff_phone ~ '^09[0-9]{9}$' then
      insert into public.sms_messages (salon_id, to_phone, body, kind, appointment_id, status, scheduled_for)
      values (new.salon_id, v_staff_phone,
              'لغو شد: نوبت امروز ساعت ' || public.fa_clock(new.start_min) || ' — '
                || coalesce(nullif(new.customer_name, ''), 'مشتری') || ' (' || coalesce(v_service_name, 'خدمت') || ')',
              'staff_change', new.id, 'queued', now());
    end if;
  end if;

  -- Offer the freed time to that day's waitlist.
  if coalesce(v_set.waitlist_auto_offer, false) then
    for v_w in
      select w.*
        from public.waitlist w
       where w.salon_id = new.salon_id and w.date = new.date
         and w.customer_phone ~ '^09[0-9]{9}$'
         and w.customer_phone <> new.customer_phone
         and (w.staff_id is null or new.staff_id is null or w.staff_id = new.staff_id)
         -- already holds a booking that day: no need to offer
         and not exists (
           select 1 from public.appointments a
            where a.salon_id = w.salon_id and a.date = w.date and a.customer_phone = w.customer_phone
              and a.status in ('pending', 'confirmed', 'rescheduled', 'reschedule_proposed')
         )
       order by w.created_at
       limit c_max_offers
    loop
      v_token := public.create_rebooking_token(new.salon_id, v_w.customer_phone, coalesce(v_w.service_id, new.service_id), v_w.staff_id, 'waitlist');
      update public.rebooking_tokens
         set preferred_date = new.date,
             expires_at = least(expires_at, (new.date + 1)::timestamptz)
       where token_hash = encode(digest(v_token, 'sha256'), 'hex');
      v_link := public.public_link('/book?token=' || v_token);
      continue when v_link is null;

      insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
      values (new.salon_id, v_w.customer_phone,
              coalesce(v_salon_name, 'سالن') || ': نوبتی در روزی که در لیست انتظارش بودید خالی شد. '
                || 'هر کس زودتر رزرو کند، نوبت مال اوست: ' || v_link,
              'waitlist_offer', 'queued', now());
      update public.waitlist set notified_at = now() where id = v_w.id;
      v_offered := v_offered + 1;
    end loop;
  end if;

  return new;
end;
$fn$;

drop trigger if exists trg_on_appointment_cancelled on public.appointments;
create trigger trg_on_appointment_cancelled
  after update of status on public.appointments
  for each row execute function public.on_appointment_cancelled();

-- Whoever books a day (by any path) leaves that day's waitlist.
create or replace function public.clear_waitlist_on_booking()
returns trigger
language plpgsql security definer set search_path = public as $fn$
begin
  delete from public.waitlist
   where salon_id = new.salon_id and date = new.date and customer_phone = new.customer_phone;
  return new;
end;
$fn$;

drop trigger if exists trg_clear_waitlist_on_booking on public.appointments;
create trigger trg_clear_waitlist_on_booking
  after insert on public.appointments
  for each row execute function public.clear_waitlist_on_booking();

-- ----------------------------------------------------------------------------
-- 2) Attendance confirmation
-- ----------------------------------------------------------------------------
alter table public.appointments add column if not exists attendance_token_hash text;
alter table public.appointments add column if not exists customer_response     text;
alter table public.appointments add column if not exists customer_responded_at timestamptz;
alter table public.appointments drop constraint if exists appointments_customer_response_check;
alter table public.appointments add constraint appointments_customer_response_check
  check (customer_response is null or customer_response in ('confirmed', 'declined'));
create unique index if not exists appointments_attendance_token_idx
  on public.appointments (attendance_token_hash) where attendance_token_hash is not null;

-- Mints the link for one appointment (only the hash is stored). Each call
-- replaces the previous token, so only the latest link works.
create or replace function public.issue_attendance_link(p_appointment_id text)
returns text
language plpgsql security definer set search_path = public as $fn$
declare v_token text; v_link text;
begin
  v_token := encode(gen_random_bytes(32), 'hex');
  v_link := public.public_link('/confirm?token=' || v_token);
  if v_link is null then
    return null;
  end if;
  update public.appointments
     set attendance_token_hash = encode(digest(v_token, 'sha256'), 'hex')
   where id = p_appointment_id;
  return v_link;
end;
$fn$;
revoke all on function public.issue_attendance_link(text) from public, anon, authenticated;

-- Every queued reminder (client-scheduled or not) gets the link appended,
-- so no Edge Function change is needed for the normal path.
create or replace function public.add_attendance_link_to_reminder()
returns trigger
language plpgsql security definer set search_path = public as $fn$
declare v_link text;
begin
  if new.kind = 'reminder' and new.appointment_id is not null and new.status = 'queued'
     and coalesce((select attendance_confirmation from public.app_settings where salon_id = new.salon_id), false)
  then
    v_link := public.issue_attendance_link(new.appointment_id);
    if v_link is not null then
      new.body := new.body || E'\n' || 'تایید حضور یا لغو: ' || v_link;
    end if;
  end if;
  return new;
end;
$fn$;

drop trigger if exists trg_add_attendance_link_to_reminder on public.sms_messages;
create trigger trg_add_attendance_link_to_reminder
  before insert on public.sms_messages
  for each row execute function public.add_attendance_link_to_reminder();

-- What the /confirm page shows. Token is the only credential; no PII
-- beyond the customer's own first name and their own booking.
create or replace function public.get_attendance(p_token text)
returns json
language sql stable security definer set search_path = public as $fn$
  select case when a.id is null then json_build_object('ok', false, 'error', 'این لینک نامعتبر است')
    else json_build_object(
      'ok', true,
      'salon_name', s.name,
      'customer_name', a.customer_name,
      'service_name', svc.name,
      'staff_name', nullif(a.staff_name, ''),
      'date', a.date,
      'start_min', a.start_min,
      'status', a.status,
      'customer_response', a.customer_response,
      'active', a.status in ('pending', 'confirmed', 'rescheduled') and a.date >= public.salon_today()
    )
  end
  from (select 1) as dummy
  left join public.appointments a on a.attendance_token_hash = encode(digest(coalesce(p_token, ''), 'sha256'), 'hex')
  left join public.salons s on s.id = a.salon_id
  left join public.services svc on svc.id = a.service_id and svc.salon_id = a.salon_id;
$fn$;
grant execute on function public.get_attendance(text) to anon, authenticated;

create or replace function public.respond_attendance(p_token text, p_response text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_appt record;
begin
  if p_response not in ('confirmed', 'declined') then
    return json_build_object('ok', false, 'error', 'پاسخ نامعتبر است');
  end if;
  select * into v_appt from public.appointments
   where attendance_token_hash = encode(digest(coalesce(p_token, ''), 'sha256'), 'hex')
   for update;
  if v_appt.id is null then
    return json_build_object('ok', false, 'error', 'این لینک نامعتبر است');
  end if;
  if v_appt.status not in ('pending', 'confirmed', 'rescheduled') or v_appt.date < public.salon_today() then
    return json_build_object('ok', false, 'error', 'این نوبت دیگر فعال نیست');
  end if;

  if p_response = 'confirmed' then
    update public.appointments
       set customer_response = 'confirmed', customer_responded_at = now()
     where id = v_appt.id;
  else
    -- Cancelling fires on_appointment_cancelled: same-day stylist SMS and
    -- the waitlist offer happen there.
    update public.appointments
       set status = 'cancelled', customer_response = 'declined', customer_responded_at = now()
     where id = v_appt.id;
    update public.sms_messages set status = 'cancelled', error = 'customer declined via attendance link'
     where appointment_id = v_appt.id and status = 'queued'
       and kind in ('reminder', 'feedback_request', 'feedback_followup'); -- not the stylist notice queued just above
  end if;

  return json_build_object('ok', true, 'response', p_response);
end;
$fn$;
grant execute on function public.respond_attendance(text, text) to anon, authenticated;


-- >>>>>>>>>> supabase/migrations/v2.30_review_fixes.sql
-- ============================================================================
-- Migration v2.30 — fixes from a review pass (run after v2.29)
-- ============================================================================
--  1. (salon_today(), the salon-local date used by v2.28/v2.29, lives in
--     v2.28.) The functions redefined below use it too.
--  2. Closures and the rolling booking window:
--     - open_booking_window() no longer (re)opens a day that has an active
--       closure;
--     - announcing a closure removes the day from approved_dates, and
--       revoking it puts the day back (when auto-open is on), so the public
--       booking page stops offering times the server will then refuse.
--  3. handle_closure_announcement() also cancels 'pending' and
--     'reschedule_proposed' bookings on the closed day (they were left in
--     place), and no longer sends a broken relative link when app.base_url
--     isn't set.
--  4. run_predictive_rebooking(): a customer with an empty name made the SMS
--     body NULL, which failed the insert and aborted the whole run; also
--     skips sending when there's no usable link.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1) Salon-local date
-- ----------------------------------------------------------------------------
-- salon_today() itself is defined in v2.28 (its first user); the v2.28 and
-- v2.29 automation functions already use it.

-- ----------------------------------------------------------------------------
-- 2) Closures vs. the rolling booking window
-- ----------------------------------------------------------------------------
create or replace function public.open_booking_window(p_salon_id uuid default null)
returns int
language plpgsql security definer set search_path = public as $fn$
declare v_added int;
begin
  insert into public.approved_dates (salon_id, date)
  select s.salon_id, (public.salon_today() + g.i)::date
    from public.app_settings s
    join public.salons sa on sa.id = s.salon_id and sa.active
    cross join lateral generate_series(0, s.booking_window_days - 1) as g(i)
   where s.auto_open_days
     and (p_salon_id is null or s.salon_id = p_salon_id)
     and not exists (
       select 1 from public.salon_closures c
        where c.salon_id = s.salon_id and c.closure_date = public.salon_today() + g.i and c.is_active
     )
  on conflict (salon_id, date) do nothing;
  get diagnostics v_added = row_count;
  return v_added;
end;
$fn$;
revoke all on function public.open_booking_window(uuid) from public, anon, authenticated;

create or replace function public.sync_closure_with_open_days()
returns trigger
language plpgsql security definer set search_path = public as $fn$
begin
  if new.is_active then
    delete from public.approved_dates where salon_id = new.salon_id and date = new.closure_date;
  elsif tg_op = 'UPDATE' and old.is_active then
    insert into public.approved_dates (salon_id, date)
    select new.salon_id, new.closure_date
      from public.app_settings s
     where s.salon_id = new.salon_id and s.auto_open_days
       and new.closure_date between public.salon_today() and public.salon_today() + s.booking_window_days - 1
    on conflict (salon_id, date) do nothing;
  end if;
  return new;
end;
$fn$;

drop trigger if exists trg_sync_closure_with_open_days on public.salon_closures;
create trigger trg_sync_closure_with_open_days
  after insert or update of is_active on public.salon_closures
  for each row execute function public.sync_closure_with_open_days();

-- Days already closed before this migration: take them out of the window now.
delete from public.approved_dates ad
 using public.salon_closures c
 where c.salon_id = ad.salon_id and c.closure_date = ad.date and c.is_active;

-- ----------------------------------------------------------------------------
-- 3) handle_closure_announcement — same as v2.26 plus the fixes above
-- ----------------------------------------------------------------------------
create or replace function public.handle_closure_announcement(
  p_salon_id uuid, p_closure_date date, p_closure_type text, p_notes text default ''
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_appt record;
  v_affected int := 0;
  v_reason_note text;
  v_token text;
  v_body text;
  v_salon_name text;
  v_link text;
begin
  if not (public.is_manager() and p_salon_id = public.current_salon_id()) then
    return json_build_object('ok', false, 'error', 'دسترسی مجاز نیست');
  end if;
  if p_closure_type not in ('holiday', 'maintenance', 'personal_leave') then
    return json_build_object('ok', false, 'error', 'نوع تعطیلی نامعتبر است');
  end if;

  insert into public.salon_closures (salon_id, closure_date, closure_type, notes, is_active)
  values (p_salon_id, p_closure_date, p_closure_type, coalesce(p_notes, ''), true)
  on conflict (salon_id, closure_date) do update
    set closure_type = excluded.closure_type, notes = excluded.notes, is_active = true;

  select name into v_salon_name from public.salons where id = p_salon_id;
  v_reason_note := case p_closure_type
    when 'holiday' then ''
    else ' (تعطیلی ناگهانی به دلیل ' || case p_closure_type when 'maintenance' then 'تعمیرات' else 'مرخصی' end || ')'
  end;

  for v_appt in
    select * from public.appointments
     where salon_id = p_salon_id and date = p_closure_date
       and status in ('pending', 'confirmed', 'rescheduled', 'reschedule_proposed') -- v2.30: pending / awaiting-reply bookings were left on a closed day
  loop
    update public.appointments set status = 'cancelled_by_salon' where id = v_appt.id;
    v_affected := v_affected + 1;

    -- A single-use rebooking token (part 1) tied to this customer's own
    -- phone and service — never the raw phone/service in the SMS URL
    -- itself, only an opaque token the frontend/RPC resolve server-side.
    v_token := public.create_rebooking_token(p_salon_id, v_appt.customer_phone, v_appt.service_id, v_appt.staff_id, 'closure');

    v_link := public.public_link('/book?token=' || v_token);
    v_body := coalesce(v_salon_name, 'سالن') || ': متاسفانه نوبت شما در این تاریخ به دلیل تعطیلی لغو شد' || v_reason_note || '. '
      || case when v_link is not null then 'برای رزرو زمان جدید لمس کنید: ' || v_link
              else 'برای رزرو زمان جدید با سالن تماس بگیرید.' end;

    insert into public.sms_messages (salon_id, to_phone, body, kind, appointment_id, status, scheduled_for)
    values (p_salon_id, v_appt.customer_phone, v_body, 'cancellation', v_appt.id, 'queued', now());
  end loop;

  return json_build_object('ok', true, 'affected_appointments', v_affected);
end;
$fn$;
grant execute on function public.handle_closure_announcement(uuid, date, text, text) to authenticated;

-- ----------------------------------------------------------------------------
-- 4) run_predictive_rebooking — same as v2.26 plus the fixes above
-- ----------------------------------------------------------------------------
create or replace function public.run_predictive_rebooking()
returns int
language plpgsql security definer set search_path = public as $fn$
declare
  v_candidate record;
  v_token text;
  v_body text;
  v_sent int := 0;
  v_link text;
begin
  for v_candidate in
    with last_visit as (
      select
        a.salon_id, a.customer_phone, a.service_id,
        max(a.date) as last_date,
        (array_agg(a.customer_name order by a.date desc))[1] as customer_name,
        (array_agg(a.staff_id order by a.date desc))[1] as staff_id
      from public.appointments a
      where a.status = 'completed'
      group by a.salon_id, a.customer_phone, a.service_id
    )
    select
      lv.salon_id, lv.customer_phone, lv.customer_name, lv.service_id, lv.staff_id,
      s.name as service_name, s.average_cycle_days, lv.last_date,
      sal.name as salon_name
    from last_visit lv
    join public.services s on s.id = lv.service_id and s.salon_id = lv.salon_id and s.is_active
    join public.salons sal on sal.id = lv.salon_id and sal.active
    where s.average_cycle_days is not null
      and current_date between
            lv.last_date + (s.average_cycle_days - 3)
        and lv.last_date + (s.average_cycle_days + 2)
      -- not already upcoming for the same service
      and not exists (
        select 1 from public.appointments up
        where up.salon_id = lv.salon_id and up.customer_phone = lv.customer_phone and up.service_id = lv.service_id
          and up.status in ('pending', 'confirmed', 'rescheduled', 'pending_verification')
          and up.date >= current_date
      )
      -- not already nudged recently for this same service
      and not exists (
        select 1 from public.rebooking_tokens rt
        where rt.salon_id = lv.salon_id and rt.customer_phone = lv.customer_phone and rt.service_id = lv.service_id
          and rt.reason = 'predictive' and rt.created_at > now() - interval '10 days'
      )
      -- respects opt-out — this is a retention/marketing nudge, not a
      -- transactional message, and the queued-message send path (unlike
      -- send-sms's direct "send" action) has no opt-out check of its own
      and not coalesce(
        (select c.sms_opt_out from public.customers c where c.salon_id = lv.salon_id and c.phone = lv.customer_phone),
        false
      )
  loop
    v_token := public.create_rebooking_token(
      v_candidate.salon_id, v_candidate.customer_phone, v_candidate.service_id, v_candidate.staff_id, 'predictive'
    );

    v_link := public.public_link('/book?token=' || v_token);
    -- v2.30: without a public address there's no usable link — skip rather
    -- than send a broken one (the token simply expires unused).
    continue when v_link is null;
    -- v2.30: nullif() on an empty name made the WHOLE body NULL, failing the
    -- insert and aborting the run for every customer after it.
    v_body := 'سلام' || coalesce(' ' || nullif(trim(v_candidate.customer_name), ''), '') || E'\n' ||
      'وقتشه برای ' || v_candidate.service_name || ' بعدی‌تون وقت بگیرید! برای حفظ ظاهرتون و رزرو زمان دلخواه، لمس کنید: ' || v_link;

    insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
    values (v_candidate.salon_id, v_candidate.customer_phone, v_body, 'predictive_rebooking', 'queued', now());

    v_sent := v_sent + 1;
  end loop;

  return v_sent;
end;
$fn$;


-- >>>>>>>>>> supabase/migrations/v2.31_server_owned_booking_sms.sql
-- ============================================================================
-- Migration v2.31 — booking SMS move into the database (run after v2.30)
-- ============================================================================
-- Before: the browser of whoever made the booking sent the booking SMS
-- through the send-sms Edge Function. For an anonymous customer that meant:
--   * send-sms had to accept anonymous "send"/"schedule" calls with a
--     caller-chosen recipient AND text — an open SMS relay on the salon's
--     sender and credit (5/hour per number was the only limit);
--   * the stylist's "new booking" SMS always failed (its kind was not on
--     the anonymous allow-list);
--   * bookings made from SMS links (rebooking, waitlist, closure) got no
--     confirmation and no reminder at all — only the main form sent them;
--   * a customer moving their own booking left the old reminder queued
--     for the old time, and the cron sweep then skipped the new time
--     because "a reminder already exists".
--
-- Now two triggers on public.appointments own these messages for every
-- booking path, rendering the salon's own templates server-side:
--   AFTER INSERT  → confirmation to the customer, "new booking" to the
--                   stylist (same-day only when the morning digest is on),
--                   and the reminder (for confirmed bookings).
--   AFTER UPDATE of status/date/start_min → (re)queue the reminder when a
--                   booking becomes confirmed or moves; drop queued
--                   reminders when it's cancelled / no-show / done.
-- The Edge Function no longer accepts anonymous send/schedule at all (see
-- supabase/functions/send-sms). Messages are queued and sent by the
-- cron-reminders drain — schedule it every minute (supabase/cron.sql).
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1) Formatting helpers (same algorithm as src/lib/format.js)
-- ----------------------------------------------------------------------------
create or replace function public.jalali_label(p_date date)
returns text
language plpgsql immutable as $fn$
declare
  g_d_m constant int[] := array[0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
  months constant text[] := array['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'];
  gy int := extract(year from p_date)::int;
  gm int := extract(month from p_date)::int;
  gd int := extract(day from p_date)::int;
  jy int; jm int; jd int; gy2 int; days int;
begin
  jy := case when gy <= 1600 then 0 else 979 end;
  gy := gy - case when gy <= 1600 then 621 else 1600 end;
  gy2 := case when gm > 2 then gy + 1 else gy end;
  days := 365 * gy + (gy2 + 3) / 4 - (gy2 + 99) / 100 + (gy2 + 399) / 400 - 80 + gd + g_d_m[gm];
  jy := jy + 33 * (days / 12053);
  days := days % 12053;
  jy := jy + 4 * (days / 1461);
  days := days % 1461;
  if days > 365 then
    jy := jy + (days - 1) / 365;
    days := (days - 1) % 365;
  end if;
  if days < 186 then
    jm := 1 + days / 31;  jd := 1 + days % 31;
  else
    jm := 7 + (days - 186) / 30;  jd := 1 + (days - 186) % 30;
  end if;
  return public.fa_digits(jd::text) || ' ' || months[jm] || ' ' || public.fa_digits(jy::text);
end;
$fn$;

create or replace function public.render_sms(p_body text, p_vars jsonb)
returns text
language plpgsql immutable as $fn$
declare v_out text := coalesce(p_body, ''); v_key text; v_val text;
begin
  for v_key, v_val in select key, value from jsonb_each_text(p_vars) loop
    v_out := replace(v_out, '{{' || v_key || '}}', coalesce(v_val, ''));
  end loop;
  -- any placeholder we don't know about renders empty, like the client did
  return regexp_replace(v_out, '\{\{\w+\}\}', '', 'g');
end;
$fn$;

-- The salon's default template for a kind, or the built-in fallback.
create or replace function public.booking_sms_text(p_appt public.appointments, p_kind text)
returns text
language plpgsql stable security definer set search_path = public as $fn$
declare v_tpl text; v_service text; v_salon text;
begin
  select body into v_tpl from public.sms_templates
   where salon_id = p_appt.salon_id and kind = p_kind and body <> ''
   order by is_default desc, created_at limit 1;
  v_tpl := coalesce(v_tpl, case p_kind
    when 'confirmation' then E'{{name}} عزیز، نوبت شما در {{salon}} ثبت شد.\nخدمت: {{service}}\nتاریخ: {{date}} ساعت {{time}}\nکد پیگیری: {{code}}'
    when 'reminder'     then E'{{name}} عزیز، یادآوری نوبت شما در {{salon}}:\n{{service}} — {{date}} ساعت {{time}}\nمنتظر شما هستیم.'
  end);
  select name into v_service from public.services where id = p_appt.service_id and salon_id = p_appt.salon_id;
  select name into v_salon from public.salons where id = p_appt.salon_id;
  return public.render_sms(v_tpl, jsonb_build_object(
    'name',    coalesce(nullif(trim(p_appt.customer_name), ''), 'مشتری'),
    'service', coalesce(v_service, 'خدمت'),
    'date',    public.jalali_label(p_appt.date),
    'time',    public.fa_clock(p_appt.start_min),
    'stylist', coalesce(nullif(p_appt.staff_name, ''), 'بدون آرایشگر مشخص'),
    'code',    coalesce(p_appt.tracking_code, ''),
    'salon',   coalesce(v_salon, 'سالن')
  ));
end;
$fn$;
revoke all on function public.booking_sms_text(public.appointments, text) from public, anon, authenticated;

-- ----------------------------------------------------------------------------
-- 2) Reminder queue — one place decides when (and whether) it goes out
-- ----------------------------------------------------------------------------
create or replace function public.requeue_reminder(p_appt public.appointments)
returns void
language plpgsql security definer set search_path = public as $fn$
declare v_hours int; v_send_at timestamptz;
begin
  update public.sms_messages
     set status = 'cancelled', error = 'superseded: booking changed'
   where appointment_id = p_appt.id and kind = 'reminder' and status = 'queued';

  if p_appt.status not in ('confirmed', 'rescheduled') or p_appt.customer_phone !~ '^09[0-9]{9}$' then
    return;
  end if;

  select reminder_hours_before into v_hours from public.stylists where id = p_appt.staff_id and salon_id = p_appt.salon_id;
  v_send_at := ((p_appt.date + make_interval(mins => p_appt.start_min))
                 at time zone coalesce(nullif(current_setting('app.timezone', true), ''), 'Asia/Tehran'))
               - make_interval(hours => coalesce(v_hours, 3));
  if v_send_at <= now() then
    return; -- window already open: the cron-reminders sweep covers it
  end if;

  insert into public.sms_messages (salon_id, to_phone, body, kind, appointment_id, status, scheduled_for)
  values (p_appt.salon_id, p_appt.customer_phone, public.booking_sms_text(p_appt, 'reminder'),
          'reminder', p_appt.id, 'queued', v_send_at);
end;
$fn$;
revoke all on function public.requeue_reminder(public.appointments) from public, anon, authenticated;

-- ----------------------------------------------------------------------------
-- 3) Triggers
-- ----------------------------------------------------------------------------
create or replace function public.queue_new_booking_messages()
returns trigger
language plpgsql security definer set search_path = public as $fn$
declare v_staff_phone text; v_digest boolean; v_service text;
begin
  if new.customer_phone ~ '^09[0-9]{9}$' then
    insert into public.sms_messages (salon_id, to_phone, body, kind, appointment_id, status, scheduled_for)
    values (new.salon_id, new.customer_phone, public.booking_sms_text(new, 'confirmation'),
            'confirmation', new.id, 'queued', now());
  end if;

  if new.staff_id is not null then
    select phone into v_staff_phone from public.stylists where id = new.staff_id and salon_id = new.salon_id;
    select staff_daily_digest into v_digest from public.app_settings where salon_id = new.salon_id;
    -- with the morning digest on, later days are covered by that day's digest
    if v_staff_phone ~ '^09[0-9]{9}$' and (not coalesce(v_digest, false) or new.date = public.salon_today()) then
      select name into v_service from public.services where id = new.service_id and salon_id = new.salon_id;
      insert into public.sms_messages (salon_id, to_phone, body, kind, appointment_id, status, scheduled_for)
      values (new.salon_id, v_staff_phone,
              'نوبت جدید: ' || coalesce(nullif(trim(new.customer_name), ''), 'مشتری') || ' — ' || coalesce(v_service, 'خدمت')
                || E'\n' || public.jalali_label(new.date) || ' ساعت ' || public.fa_clock(new.start_min),
              'staff_new_booking', new.id, 'queued', now());
    end if;
  end if;

  perform public.requeue_reminder(new);
  return new;
end;
$fn$;

drop trigger if exists trg_queue_new_booking_messages on public.appointments;
create trigger trg_queue_new_booking_messages
  after insert on public.appointments
  for each row execute function public.queue_new_booking_messages();

create or replace function public.sync_reminder_on_change()
returns trigger
language plpgsql security definer set search_path = public as $fn$
begin
  if new.status in ('confirmed', 'rescheduled') then
    -- became active, or moved: schedule for the (new) time
    if old.status not in ('confirmed', 'rescheduled') or old.date <> new.date or old.start_min <> new.start_min then
      perform public.requeue_reminder(new);
    end if;
  elsif old.status in ('confirmed', 'rescheduled') then
    -- no longer active (cancelled, no-show, completed, closure, …)
    perform public.requeue_reminder(new); -- cancels the queued one, queues nothing
  end if;
  return new;
end;
$fn$;

drop trigger if exists trg_sync_reminder_on_change on public.appointments;
create trigger trg_sync_reminder_on_change
  after update of status, date, start_min on public.appointments
  for each row execute function public.sync_reminder_on_change();


-- >>>>>>>>>> supabase/migrations/v2.32_function_privileges.sql
-- ============================================================================
-- Migration v2.32 — function privileges (SECURITY — run after v2.31)
-- ============================================================================
-- PostgreSQL lets PUBLIC execute every new function, and Supabase's default
-- privileges also grant every new function in `public` to anon and
-- authenticated. Several functions documented as "server only" were never
-- revoked, so anyone holding the public anon key could call them over
-- /rest/v1/rpc:
--   * request_booking_otp_internal(phone, salon) → returns the plaintext
--     login code for ANY phone → full access to that customer's bookings
--     (view / cancel / reschedule);
--   * create_reconciliation_token(salon) → the owner's reconciliation link:
--     customer names/phones, and marking visits completed (which awards
--     loyalty points) or no-show;
--   * create_rebooking_token(...) + resolve_rebooking_token → the name on
--     file for any phone number;
--   * run_predictive_rebooking(), transition_elapsed_appointments(),
--     archive_stale_pending_verifications() → scheduler jobs on demand.
-- Separately, customer_loyalty(phone) was callable anonymously and returned
-- the customer's name, referral code, points history and the NAMES AND
-- PHONES of everyone they had referred — for any number typed in.
--
-- Fix: execute is revoked from everyone on every function in `public`
-- (including future ones), then granted back by intent:
--   service_role  → everything (Edge Functions, cron);
--   anon + authenticated → RLS/view helpers and the public token-based pages;
--   authenticated → staff RPCs (each also checks is_manager()/is_staff()).
-- customer_loyalty is split: staff get the full record; anonymous callers
-- get only {found, discount_percent, ...}; customers get their own full
-- record after OTP via get_my_loyalty_with_token(token).
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1) customer_loyalty: full view for staff / the verified customer only
-- ----------------------------------------------------------------------------
create or replace function public.customer_loyalty_full(p_phone text, p_salon_id uuid)
returns json
language plpgsql stable security definer set search_path = public as $fn$
declare c record; ls record; tier int; disc int;
begin
  select * into ls from public.loyalty_settings where salon_id = p_salon_id;
  select * into c from public.customers where phone = p_phone and salon_id = p_salon_id;
  if c is null or ls is null then
    return json_build_object('found', false, 'points', 0, 'discount_percent', 0, 'history', '[]'::json, 'referrals', '[]'::json);
  end if;
  tier := floor(c.loyalty_points::numeric / greatest(ls.points_per_tier, 1));
  disc := least(tier * ls.discount_per_tier, ls.max_discount);
  return json_build_object(
    'found', true,
    'name', c.name,
    'points', c.loyalty_points,
    'total_visits', c.total_visits,
    'referral_code', c.referral_code,
    'discount_percent', disc,
    'max_discount', ls.max_discount,
    'at_cap', disc >= ls.max_discount,
    'points_to_next_tier', greatest(ls.points_per_tier - (c.loyalty_points % greatest(ls.points_per_tier, 1)), 0),
    'history', coalesce((
      select json_agg(json_build_object('delta', l.delta, 'reason', l.reason, 'at', l.created_at) order by l.created_at desc)
        from (select * from public.loyalty_ledger where customer_phone = p_phone and salon_id = p_salon_id
               order by created_at desc limit 30) l
    ), '[]'::json),
    'referrals', coalesce((
      select json_agg(json_build_object('name', r.name, 'phone', r.phone, 'total_visits', r.total_visits, 'joined_at', r.created_at) order by r.created_at desc)
        from public.customers r where r.referred_by = p_phone and r.salon_id = p_salon_id
    ), '[]'::json)
  );
end;
$fn$;

create or replace function public.customer_loyalty(p_phone text)
returns json
language plpgsql stable security definer set search_path = public as $fn$
declare v_full json;
begin
  v_full := public.customer_loyalty_full(p_phone, public.current_salon_id());
  if public.is_staff() then
    return v_full;
  end if;
  -- Anonymous: only what the booking page needs to price the booking.
  return json_build_object(
    'found', coalesce((v_full ->> 'found')::boolean, false),
    'discount_percent', coalesce((v_full ->> 'discount_percent')::int, 0)
  );
end;
$fn$;

create or replace function public.get_my_loyalty_with_token(p_token text)
returns json
language plpgsql stable security definer set search_path = public as $fn$
declare v_phone text; v_salon_id uuid;
begin
  select r.phone, r.salon_id into v_phone, v_salon_id from public.resolve_booking_token(p_token) r;
  if v_phone is null then
    return json_build_object('found', false, 'error', 'نشست شما منقضی شده — دوباره وارد شوید');
  end if;
  return public.customer_loyalty_full(v_phone, v_salon_id);
end;
$fn$;

-- ----------------------------------------------------------------------------
-- 2) create_public_booking — same as v2.26, plus the name fallback above
-- ----------------------------------------------------------------------------
create or replace function public.create_public_booking(
  p_service_id text, p_staff_id text, p_date date, p_start_min int,
  p_customer_name text, p_customer_phone text, p_customer_gender text,
  p_referral_code text default null
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_svc record; v_wh record; v_app_dow int; v_wh_start int; v_wh_end int;
  v_end_min int; v_id text; v_code text; v_original bigint; v_svc_discount bigint;
  v_after_svc bigint; v_loyalty_pct int := 0; v_final bigint; v_loyalty json; v_code_bytes bytea;
  v_salon_id uuid;
begin
  v_salon_id := public.current_salon_id();
  if v_salon_id is null then
    return json_build_object('ok', false, 'error', 'سالن نامعتبر است');
  end if;
  if p_customer_phone !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شماره موبایل نامعتبر است');
  end if;
  -- v2.32: a returning customer's name is no longer sent to the browser
  -- (customer_loyalty is PII-free for anonymous callers), so an empty name
  -- falls back to the one already on file for this phone.
  if coalesce(trim(p_customer_name), '') = '' then
    select name into p_customer_name from public.customers where salon_id = v_salon_id and phone = p_customer_phone;
  end if;
  if coalesce(trim(p_customer_name), '') = '' then
    return json_build_object('ok', false, 'error', 'نام لازم است');
  end if;
  if p_customer_gender not in ('female', 'male') then
    return json_build_object('ok', false, 'error', 'جنسیت نامعتبر است');
  end if;
  if not public.check_rate_limit('create_booking:' || v_salon_id || ':' || p_customer_phone, 10, 30) then
    return json_build_object('ok', false, 'error', 'تعداد درخواست بیش از حد مجاز است — کمی بعد دوباره امتحان کنید');
  end if;
  if p_date < current_date then
    return json_build_object('ok', false, 'error', 'تاریخ گذشته قابل انتخاب نیست');
  end if;
  if not exists (select 1 from public.approved_dates where date = p_date and salon_id = v_salon_id) then
    return json_build_object('ok', false, 'error', 'این روز برای رزرو باز نشده است');
  end if;
  if exists (select 1 from public.salon_closures where salon_id = v_salon_id and closure_date = p_date and is_active) then
    return json_build_object('ok', false, 'error', 'سالن در این روز تعطیل است');
  end if;

  select * into v_svc from public.services where id = p_service_id and salon_id = v_salon_id and is_active;
  if v_svc is null then
    return json_build_object('ok', false, 'error', 'خدمت یافت نشد یا غیرفعال است');
  end if;
  if v_svc.gender <> p_customer_gender then
    return json_build_object('ok', false, 'error', 'این خدمت با جنسیت انتخابی مطابقت ندارد');
  end if;

  if p_staff_id is not null and not exists (select 1 from public.stylists where id = p_staff_id and salon_id = v_salon_id and active) then
    return json_build_object('ok', false, 'error', 'آرایشگر یافت نشد یا غیرفعال است');
  end if;

  v_app_dow := (extract(dow from p_date)::int + 1) % 7;
  select * into v_wh from public.working_hours
   where day_of_week = v_app_dow and staff_id = p_staff_id and salon_id = v_salon_id;
  if v_wh is null then
    select * into v_wh from public.working_hours
     where day_of_week = v_app_dow and staff_id is null and salon_id = v_salon_id;
  end if;
  if v_wh is null or v_wh.is_closed then
    return json_build_object('ok', false, 'error', 'در این روز سالن یا آرایشگر تعطیل است');
  end if;
  v_wh_start := split_part(v_wh.start_time, ':', 1)::int * 60 + split_part(v_wh.start_time, ':', 2)::int;
  v_wh_end := split_part(v_wh.end_time, ':', 1)::int * 60 + split_part(v_wh.end_time, ':', 2)::int;
  v_end_min := p_start_min + v_svc.duration_minutes;
  if p_start_min < v_wh_start or v_end_min > v_wh_end then
    return json_build_object('ok', false, 'error', 'خارج از ساعات کاری است');
  end if;

  v_original := coalesce(v_svc.price, 0);
  v_svc_discount := case
    when v_svc.discount_type = 'percent' then round(v_original * v_svc.discount_value / 100.0)
    when v_svc.discount_type = 'fixed' then v_svc.discount_value
    else 0
  end;
  v_after_svc := greatest(0, v_original - v_svc_discount);
  if v_svc.price is not null then
    v_loyalty := public.customer_loyalty(p_customer_phone);
    if (v_loyalty->>'found')::boolean then
      v_loyalty_pct := coalesce((v_loyalty->>'discount_percent')::int, 0);
    end if;
  end if;
  v_final := case when v_svc.price is null then null
                  else greatest(0, v_after_svc - round(v_after_svc * v_loyalty_pct / 100.0)) end;

  v_id := 'apt-' || substr(md5(gen_random_uuid()::text), 1, 16);
  v_code_bytes := gen_random_bytes(4);
  v_code := 'MN-' || lpad((
    ((get_byte(v_code_bytes, 0)::bigint << 24) | (get_byte(v_code_bytes, 1)::bigint << 16)
     | (get_byte(v_code_bytes, 2)::bigint << 8) | get_byte(v_code_bytes, 3)::bigint) % 90000 + 10000
  )::text, 5, '0');

  begin
    insert into public.appointments (
      id, salon_id, customer_name, customer_phone, customer_gender, service_id, staff_id,
      staff_name, date, start_min, end_min, buffer_minutes, status,
      tracking_code, original_price, discount_type, discount_value, discount_reason, final_price
    ) values (
      v_id, v_salon_id, trim(p_customer_name), p_customer_phone, p_customer_gender, p_service_id, p_staff_id,
      coalesce((select name from public.stylists where id = p_staff_id and salon_id = v_salon_id), ''),
      p_date, p_start_min, v_end_min, v_svc.buffer_minutes, 'pending',
      v_code, v_original, v_svc.discount_type, v_svc.discount_value,
      case when v_loyalty_pct > 0 then v_svc.discount_reason || case when v_svc.discount_reason <> '' then ' · ' else '' end || v_loyalty_pct || '٪ تخفیف باشگاه مشتریان' else v_svc.discount_reason end,
      v_final
    );
  exception when exclusion_violation then
    return json_build_object('ok', false, 'error', 'این زمان قبلاً رزرو شده — زمان دیگری انتخاب کنید');
  end;

  if p_referral_code is not null and length(trim(p_referral_code)) > 0 then
    perform public.apply_referral(p_customer_phone, p_referral_code);
  end if;

  return json_build_object(
    'ok', true, 'id', v_id, 'tracking_code', v_code, 'final_price', v_final,
    'original_price', v_original, 'staff_name', coalesce((select name from public.stylists where id = p_staff_id and salon_id = v_salon_id), '')
  );
end;
$fn$;

-- ----------------------------------------------------------------------------
-- 3) Privileges
-- ----------------------------------------------------------------------------
revoke execute on all functions in schema public from public, anon, authenticated;

-- Future functions start closed too (Supabase creates them as postgres /
-- supabase_admin; skip roles that don't exist, e.g. on plain Postgres).
do $$
declare r text;
begin
  foreach r in array array['postgres', 'supabase_admin'] loop
    if exists (select 1 from pg_roles where rolname = r) then
      execute format('alter default privileges for role %I in schema public revoke execute on functions from public, anon, authenticated', r);
      -- PUBLIC's EXECUTE default is global — a per-schema revoke can't remove
      -- it, so revoke it for the role as a whole too.
      execute format('alter default privileges for role %I revoke execute on functions from public', r);
    end if;
  end loop;
end $$;

grant execute on all functions in schema public to service_role;

-- Used inside RLS policies / views, i.e. evaluated with the caller's rights.
grant execute on function
  public.current_salon_id(), public.is_staff(), public.is_manager(), public.my_role(), public.my_stylist_id(),
  public.appointment_status_for_feedback(text), public.salon_today()
to anon, authenticated;

-- Public pages: booking form, "my dashboard" (OTP token), SMS-link pages.
grant execute on function
  public.create_public_booking(text, text, date, int, text, text, text, text),
  public.customer_loyalty(text),
  public.apply_referral(text, text),
  public.report_appointment_no_show(text),
  public.verify_booking_otp(text, text),
  public.request_booking_otp_test(text),
  public.get_my_bookings_with_token(text),
  public.get_my_loyalty_with_token(text),
  public.cancel_my_booking_with_token(text, text),
  public.reschedule_my_booking_with_token(text, text, date, int),
  public.revoke_booking_token(text),
  public.resolve_rebooking_token(text),
  public.get_available_slots_for_rebooking(text, date, text),
  public.create_booking_from_rebooking_token(text, date, int, text),
  public.resolve_reconciliation_token(text),
  public.get_reconciliation_queue(text),
  public.submit_reconciliation_batch(text, jsonb),
  public.get_attendance(text),
  public.respond_attendance(text, text)
to anon, authenticated;

-- Staff panel (each of these also checks is_manager()/is_staff() inside).
grant execute on function
  public.handle_closure_announcement(uuid, date, text, text),
  public.open_my_booking_window(),
  public.inactive_customers(int),
  public.get_customer_rfm_segments(),
  public.get_customer_category_matrix(),
  public.get_campaign_performance(text),
  public.get_feedback_stats(),
  public.preview_customer_segment_distribution(int, int, int),
  public.redeem_loyalty_reward(text)
to authenticated;

-- ----------------------------------------------------------------------------
-- 4) Stylists' personal phone numbers are staff-only. The public booking
--    page reads names/sections only (src/lib/api.js bootstrap); staff load
--    full rows after login (fetchStaffData).
-- ----------------------------------------------------------------------------
revoke select on public.stylists from anon;
grant select (id, salon_id, name, gender, active, reminder_hours_before, created_at) on public.stylists to anon;


-- >>>>>>>>>> supabase/migrations/v2.33_salon_defaults_and_signup_guard.sql
-- ============================================================================
-- Migration v2.33 — salon_id defaults + self-registration guard (run after v2.32)
-- ============================================================================
-- 1) BUG (since v2.24): every tenant table got `salon_id NOT NULL` but no
--    default, and the app never sends salon_id on insert. So every insert
--    made from the browser failed — adding a service, stylist, expense,
--    time off, working hours, open days, SMS template, a customer joining
--    the waitlist, and owner/stylist self-registration ("ساخت پروفایل
--    ناموفق بود"). The UI showed success because insert errors were only
--    logged. salon_id now defaults to current_salon_id() — the caller's own
--    salon for staff, the page's salon (x-salon-id) for public visitors —
--    which is exactly what each table's RLS check already demands.
--
-- 2) SECURITY: users' self-insert policy (p_users_selfins) checked only
--    id = auth.uid() and the salon — not the role. Anyone could sign up and
--    insert themselves as 'owner'/'manager' of any salon (the "only while no
--    manager exists" rule lived only in the browser). Now enforced here:
--      * owner/manager self-registration only while the salon has none;
--      * stylist self-registration only against a stylists row of the same
--        salon and phone that isn't linked to another account.
--    Managers adding users (p_users_mgr) and server-side inserts are not
--    affected (they aren't self-inserts).
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1) salon_id defaults
-- ----------------------------------------------------------------------------
do $$
declare t text;
begin
  for t in
    select c.table_name
      from information_schema.columns c
      join information_schema.tables tb on tb.table_schema = c.table_schema and tb.table_name = c.table_name
     where c.table_schema = 'public' and c.column_name = 'salon_id'
       and tb.table_type = 'BASE TABLE' and c.table_name <> 'salons'
  loop
    execute format('alter table public.%I alter column salon_id set default public.current_salon_id()', t);
  end loop;
end $$;

-- ----------------------------------------------------------------------------
-- 2) Self-registration guard
-- ----------------------------------------------------------------------------
create or replace function public.guard_user_self_insert()
returns trigger
language plpgsql security definer set search_path = public as $fn$
begin
  -- Only the app's own sign-up path (a user creating their own profile).
  if auth.uid() is null or new.id <> auth.uid() then
    return new;
  end if;

  if new.role in ('owner', 'manager') then
    if exists (
      select 1 from public.users u
       where u.salon_id = new.salon_id and u.role in ('owner', 'manager') and u.id <> new.id
    ) then
      raise exception 'این سالن قبلاً مدیر دارد — برای دسترسی مدیریتی از مدیر فعلی بخواهید'
        using errcode = '42501';
    end if;
  elsif new.role = 'stylist' then
    if new.stylist_id is null or not exists (
      select 1 from public.stylists s
       where s.id = new.stylist_id and s.salon_id = new.salon_id and s.phone = new.phone
    ) or exists (
      select 1 from public.users u where u.stylist_id = new.stylist_id and u.salon_id = new.salon_id and u.id <> new.id
    ) then
      raise exception 'پروفایل آرایشگر با این شماره پیدا نشد' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$fn$;

drop trigger if exists trg_guard_user_self_insert on public.users;
create trigger trg_guard_user_self_insert
  before insert on public.users
  for each row execute function public.guard_user_self_insert();

-- ----------------------------------------------------------------------------
-- 3) Saving working hours per salon
-- ----------------------------------------------------------------------------
-- The app upserted rows with fixed ids like 'wh-salon-0'. working_hours.id is
-- unique across ALL salons, so a second salon's save collided with the
-- first salon's rows (and was rejected by RLS). This replaces the salon's
-- (or one stylist's) week in one call. SECURITY INVOKER on purpose: the
-- table's RLS (managers; a stylist only for their own staff_id) decides
-- who may write.
create or replace function public.save_working_hours(p_staff_id text, p_hours jsonb)
returns void
language plpgsql set search_path = public as $fn$
declare v_salon uuid := public.current_salon_id();
begin
  if v_salon is null then
    raise exception 'salon unknown' using errcode = '42501';
  end if;
  delete from public.working_hours
   where salon_id = v_salon and staff_id is not distinct from p_staff_id;
  insert into public.working_hours (id, salon_id, staff_id, day_of_week, start_time, end_time, is_closed)
  select 'wh-' || substr(md5(gen_random_uuid()::text), 1, 16), v_salon, p_staff_id,
         (h ->> 'day_of_week')::int,
         coalesce(h ->> 'start_time', '09:00'),
         coalesce(h ->> 'end_time', '21:00'),
         coalesce((h ->> 'is_closed')::boolean, false)
    from jsonb_array_elements(coalesce(p_hours, '[]'::jsonb)) as h;
end;
$fn$;
grant execute on function public.save_working_hours(text, jsonb) to authenticated, service_role;


-- >>>>>>>>>> supabase/migrations/v2.34_sms_claim.sql
-- ============================================================================
-- Migration v2.34 — each queued SMS is sent exactly once (run after v2.33)
-- ============================================================================
-- cron-reminders' drain (now every minute) and predictive-rebooking-cron
-- both selected status='queued' rows and sent them; two overlapping runs
-- (or the two functions at 10:00) could send the same message twice.
-- claim_due_sms() hands out due rows atomically (FOR UPDATE SKIP LOCKED)
-- and marks them 'sending', so a row goes to exactly one sender. A row
-- stuck in 'sending' (sender crashed mid-run) is handed out again after
-- 10 minutes.
-- ============================================================================

alter table public.sms_messages drop constraint if exists sms_messages_status_check;
alter table public.sms_messages add constraint sms_messages_status_check
  check (status in ('queued', 'sending', 'sent', 'failed', 'delivered', 'cancelled'));
alter table public.sms_messages add column if not exists claimed_at timestamptz;

create index if not exists sms_messages_due_idx
  on public.sms_messages (scheduled_for) where status in ('queued', 'sending');

create or replace function public.claim_due_sms(p_limit int default 200)
returns setof public.sms_messages
language sql security definer set search_path = public as $fn$
  update public.sms_messages m
     set status = 'sending', claimed_at = now()
   where m.id in (
     select id from public.sms_messages
      where scheduled_for <= now()
        and (status = 'queued' or (status = 'sending' and claimed_at < now() - interval '10 minutes'))
      order by scheduled_for
      limit greatest(p_limit, 1)
      for update skip locked
   )
  returning m.*;
$fn$;
revoke all on function public.claim_due_sms(int) from public, anon, authenticated;
grant execute on function public.claim_due_sms(int) to service_role;


-- >>>>>>>>>> supabase/migrations/v2.35_stylist_approval.sql
-- ============================================================================
-- Migration v2.35 — self-registered stylists wait for the manager (after v2.34)
-- ============================================================================
-- Stylist self-registration is open to anyone with the salon's address (by
-- design: the manager doesn't have to create accounts). Until now such a
-- stranger became an active stylist immediately: listed on the public
-- booking page, able to log in, and — through customer_loyalty's staff
-- branch — able to look up any customer's full record by phone.
--
-- Now:
--   * a stylists row created by a non-manager (the self-registration path)
--     starts inactive and is marked self_registered; every owner/manager
--     gets one SMS ("… is waiting for your approval");
--   * the matching users row starts inactive too, so the person can't log
--     in yet (the app says "waiting for the salon manager");
--   * turning the stylist on in Panel → Stylists activates the login as
--     well (and turning them off blocks it) — one switch;
--   * a stylist the manager added beforehand (with their phone) is trusted:
--     linking to it on sign-up needs no approval;
--   * customer_loyalty's full record is for managers only, not stylists.
-- ============================================================================

alter table public.stylists add column if not exists self_registered boolean not null default false;

create or replace function public.guard_stylist_self_registration()
returns trigger
language plpgsql security definer set search_path = public as $fn$
declare v_mgr record; v_salon_name text;
begin
  -- Manager/panel inserts and server-side inserts are trusted as-is.
  if auth.uid() is null or public.is_manager() then
    return new;
  end if;

  new.self_registered := true;
  new.active := false;

  select name into v_salon_name from public.salons where id = new.salon_id;
  for v_mgr in
    select u.phone from public.users u
     where u.salon_id = new.salon_id and u.active and u.role in ('owner', 'manager')
       and u.phone ~ '^09[0-9]{9}$'
  loop
    insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
    values (new.salon_id, v_mgr.phone,
            coalesce(v_salon_name, 'سالن') || ': آرایشگر جدید «' || coalesce(nullif(trim(new.name), ''), 'بدون نام') || '» ('
              || coalesce(new.phone, '') || ') ثبت‌نام کرد و منتظر تایید شماست — پنل مدیریت ← آرایشگرها',
            'custom', 'queued', now());
  end loop;
  return new;
end;
$fn$;

drop trigger if exists trg_guard_stylist_self_registration on public.stylists;
create trigger trg_guard_stylist_self_registration
  before insert on public.stylists
  for each row execute function public.guard_stylist_self_registration();

-- The account inherits the stylist profile's approval state on sign-up.
create or replace function public.guard_user_self_insert()
returns trigger
language plpgsql security definer set search_path = public as $fn$
declare v_st record;
begin
  -- Only the app's own sign-up path (a user creating their own profile).
  if auth.uid() is null or new.id <> auth.uid() then
    return new;
  end if;

  if new.role in ('owner', 'manager') then
    if exists (
      select 1 from public.users u
       where u.salon_id = new.salon_id and u.role in ('owner', 'manager') and u.id <> new.id
    ) then
      raise exception 'این سالن قبلاً مدیر دارد — برای دسترسی مدیریتی از مدیر فعلی بخواهید'
        using errcode = '42501';
    end if;
  elsif new.role = 'stylist' then
    select * into v_st from public.stylists s
     where s.id = new.stylist_id and s.salon_id = new.salon_id and s.phone = new.phone;
    if v_st.id is null or exists (
      select 1 from public.users u where u.stylist_id = new.stylist_id and u.salon_id = new.salon_id and u.id <> new.id
    ) then
      raise exception 'پروفایل آرایشگر با این شماره پیدا نشد' using errcode = '42501';
    end if;
    -- A profile the manager created is trusted; a self-registered one waits.
    if v_st.self_registered and not v_st.active then
      new.active := false;
    end if;
  end if;
  return new;
end;
$fn$;

-- One switch in the panel: the stylist's listing AND their login.
create or replace function public.sync_stylist_login_with_active()
returns trigger
language plpgsql security definer set search_path = public as $fn$
begin
  if new.active is distinct from old.active then
    update public.users
       set active = new.active
     where stylist_id = new.id and salon_id = new.salon_id and role = 'stylist';
  end if;
  return new;
end;
$fn$;

drop trigger if exists trg_sync_stylist_login_with_active on public.stylists;
create trigger trg_sync_stylist_login_with_active
  after update of active on public.stylists
  for each row execute function public.sync_stylist_login_with_active();

-- Full customer record: managers only (stylists don't need other customers').
create or replace function public.customer_loyalty(p_phone text)
returns json
language plpgsql stable security definer set search_path = public as $fn$
declare v_full json;
begin
  v_full := public.customer_loyalty_full(p_phone, public.current_salon_id());
  if public.is_manager() then
    return v_full;
  end if;
  return json_build_object(
    'found', coalesce((v_full ->> 'found')::boolean, false),
    'discount_percent', coalesce((v_full ->> 'discount_percent')::int, 0)
  );
end;
$fn$;

-- Functions created after v2.32 start closed; these are trigger functions
-- (no direct grants needed) except customer_loyalty, re-granted here.
grant execute on function public.customer_loyalty(text) to anon, authenticated;


-- >>>>>>>>>> supabase/migrations/v2.36_client_error_log.sql
-- ============================================================================
-- Migration v2.36 — client error log (run after v2.35)
-- ============================================================================
-- Several serious bugs fixed in v2.30–v2.34 (e.g. no panel insert being
-- saved since v2.24) went unnoticed because failures only reached the
-- browser console. Hosted error trackers such as Sentry refuse traffic from
-- Iran and would also need a CSP exception, so errors are stored here, in
-- the project's own database:
--   * log_client_error(...) — callable by every page, rate-limited, merges
--     repeats of the same error into one row (occurrences / last_seen);
--   * managers read their salon's rows (Panel → ساعات کاری → سلامت برنامه);
--     the developer can query public.client_errors directly;
--   * rows older than 30 days are pruned as new ones arrive.
-- ============================================================================

create table if not exists public.client_errors (
  id           bigint generated always as identity primary key,
  salon_id     uuid references public.salons (id) on delete cascade,
  kind         text not null check (kind in ('render', 'runtime', 'promise', 'save')),
  message      text not null,
  stack        text not null default '',
  url          text not null default '',
  user_agent   text not null default '',
  occurrences  int  not null default 1,
  first_seen   timestamptz not null default now(),
  last_seen    timestamptz not null default now()
);
create index if not exists client_errors_salon_seen_idx on public.client_errors (salon_id, last_seen desc);

alter table public.client_errors enable row level security;
drop policy if exists p_client_errors_read on public.client_errors;
create policy p_client_errors_read on public.client_errors for select
  using (public.is_manager() and salon_id = public.current_salon_id());
grant select on public.client_errors to authenticated;
-- No insert/update policies: rows are written only by log_client_error().

create or replace function public.log_client_error(
  p_kind text, p_message text, p_stack text default '', p_url text default '', p_user_agent text default ''
)
returns void
language plpgsql security definer set search_path = public as $fn$
declare
  v_salon uuid := public.current_salon_id();
  v_msg text := left(coalesce(nullif(trim(p_message), ''), '(no message)'), 500);
begin
  if p_kind not in ('render', 'runtime', 'promise', 'save') then
    return;
  end if;
  -- At most 60 reports per salon per 10 minutes — enough to see a problem,
  -- not enough for a broken page (or someone malicious) to flood the table.
  if not public.check_rate_limit('client_error:' || coalesce(v_salon::text, 'none'), 60, 10) then
    return;
  end if;

  update public.client_errors
     set occurrences = occurrences + 1, last_seen = now()
   where salon_id is not distinct from v_salon and kind = p_kind and message = v_msg
     and last_seen > now() - interval '24 hours';
  if not found then
    insert into public.client_errors (salon_id, kind, message, stack, url, user_agent)
    values (v_salon, p_kind, v_msg, left(coalesce(p_stack, ''), 2000), left(coalesce(p_url, ''), 300), left(coalesce(p_user_agent, ''), 300));
  end if;

  if random() < 0.02 then
    delete from public.client_errors where last_seen < now() - interval '30 days';
  end if;
end;
$fn$;
grant execute on function public.log_client_error(text, text, text, text, text) to anon, authenticated, service_role;


-- >>>>>>>>>> supabase/migrations/v2.37_online_deposit.sql
-- ============================================================================
-- Migration v2.37 — optional online deposit via Zarinpal (run after v2.36)
-- ============================================================================
-- Off by default. A manager turns it on in Panel → ساعات کاری → پیش‌پرداخت
-- آنلاین by entering the salon's own Zarinpal merchant ID, a percentage, and
-- the minimum service price it applies to. Then, for a qualifying booking
-- made by a customer (not by staff):
--   1. the booking is created as 'awaiting_payment' — it holds its slot
--      (same overlap rule as confirmed bookings) but sends no SMS yet;
--   2. the customer pays deposit_amount on Zarinpal (Edge Function
--      `payment`, which talks to Zarinpal with the merchant ID server-side);
--   3. on return, the Edge Function verifies the payment with Zarinpal and
--      only then confirms the booking — which sends the confirmation,
--      stylist notice and reminder exactly as for any confirmed booking;
--   4. unpaid holds are released after 20 minutes (expire_unpaid_bookings,
--      scheduled in cron.sql).
-- The rest (final price minus deposit) is paid at the salon as before.
-- Refunds (e.g. a paid customer cancels) are done by the salon from its
-- Zarinpal panel; the booking shows the deposit and Zarinpal reference.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1) Settings and the merchant ID (the latter readable by managers only)
-- ----------------------------------------------------------------------------
alter table public.app_settings add column if not exists deposit_percent   int    not null default 0;
alter table public.app_settings add column if not exists deposit_min_price bigint not null default 0;
alter table public.app_settings drop constraint if exists app_settings_deposit_percent_check;
alter table public.app_settings add constraint app_settings_deposit_percent_check check (deposit_percent between 0 and 100);

create table if not exists public.salon_payment_settings (
  salon_id             uuid primary key references public.salons (id) on delete cascade default public.current_salon_id(),
  zarinpal_merchant_id text not null default '',
  updated_at           timestamptz not null default now()
);
alter table public.salon_payment_settings enable row level security;
drop policy if exists p_payment_settings_mgr on public.salon_payment_settings;
create policy p_payment_settings_mgr on public.salon_payment_settings for all
  using (public.is_manager() and salon_id = public.current_salon_id())
  with check (public.is_manager() and salon_id = public.current_salon_id());
grant select, insert, update on public.salon_payment_settings to authenticated;

-- ----------------------------------------------------------------------------
-- 2) Appointment status + deposit columns
-- ----------------------------------------------------------------------------
alter table public.appointments add column if not exists deposit_amount  bigint;
alter table public.appointments add column if not exists deposit_paid_at timestamptz;
alter table public.appointments add column if not exists deposit_ref     text;

alter table public.appointments drop constraint if exists appointments_status_check;
alter table public.appointments add constraint appointments_status_check
  check (status in (
    'pending','confirmed','cancelled','rescheduled','completed','no_show',
    'reschedule_proposed','pending_verification','archived_unconfirmed',
    'cancelled_by_salon','awaiting_payment'
  ));

-- An unpaid hold must block the slot like a booking does (and a staff
-- reschedule proposal keeps its original slot too — it already did in the
-- app, now also in the database).
alter table public.appointments drop constraint if exists appointments_no_overlap;
alter table public.appointments add constraint appointments_no_overlap
  exclude using gist (staff_id with =, date with =, int4range(start_min, end_min + buffer_minutes) with &&)
  where (staff_id is not null and status in ('pending', 'confirmed', 'rescheduled', 'reschedule_proposed', 'awaiting_payment'));

-- ----------------------------------------------------------------------------
-- 3) Hold qualifying customer bookings for payment
-- ----------------------------------------------------------------------------
-- Runs after trg_auto_confirm_new_appointment (triggers fire in name order).
create or replace function public.hold_for_deposit()
returns trigger
language plpgsql security definer set search_path = public as $fn$
declare v_set record; v_merchant text;
begin
  if new.status not in ('pending', 'confirmed') or new.final_price is null or new.final_price <= 0 then
    return new;
  end if;
  if public.is_staff() then
    return new; -- bookings entered by staff never wait for an online payment
  end if;
  select deposit_percent, deposit_min_price into v_set from public.app_settings where salon_id = new.salon_id;
  if coalesce(v_set.deposit_percent, 0) = 0 or new.final_price < coalesce(v_set.deposit_min_price, 0) then
    return new;
  end if;
  select zarinpal_merchant_id into v_merchant from public.salon_payment_settings where salon_id = new.salon_id;
  if coalesce(v_merchant, '') = '' then
    return new;
  end if;
  new.deposit_amount := greatest(1000, round(new.final_price * v_set.deposit_percent / 100.0)); -- Zarinpal minimum is 1,000 toman
  new.status := 'awaiting_payment';
  return new;
end;
$fn$;

drop trigger if exists trg_hold_for_deposit on public.appointments;
create trigger trg_hold_for_deposit
  before insert on public.appointments
  for each row execute function public.hold_for_deposit();

-- ----------------------------------------------------------------------------
-- 4) Booking SMS wait for the payment
-- ----------------------------------------------------------------------------
create or replace function public.send_new_booking_messages(p_appt public.appointments)
returns void
language plpgsql security definer set search_path = public as $fn$
declare v_staff_phone text; v_digest boolean; v_service text;
begin
  if p_appt.customer_phone ~ '^09[0-9]{9}$' then
    insert into public.sms_messages (salon_id, to_phone, body, kind, appointment_id, status, scheduled_for)
    values (p_appt.salon_id, p_appt.customer_phone, public.booking_sms_text(p_appt, 'confirmation'),
            'confirmation', p_appt.id, 'queued', now());
  end if;

  if p_appt.staff_id is not null then
    select phone into v_staff_phone from public.stylists where id = p_appt.staff_id and salon_id = p_appt.salon_id;
    select staff_daily_digest into v_digest from public.app_settings where salon_id = p_appt.salon_id;
    if v_staff_phone ~ '^09[0-9]{9}$' and (not coalesce(v_digest, false) or p_appt.date = public.salon_today()) then
      select name into v_service from public.services where id = p_appt.service_id and salon_id = p_appt.salon_id;
      insert into public.sms_messages (salon_id, to_phone, body, kind, appointment_id, status, scheduled_for)
      values (p_appt.salon_id, v_staff_phone,
              'نوبت جدید: ' || coalesce(nullif(trim(p_appt.customer_name), ''), 'مشتری') || ' — ' || coalesce(v_service, 'خدمت')
                || E'\n' || public.jalali_label(p_appt.date) || ' ساعت ' || public.fa_clock(p_appt.start_min),
              'staff_new_booking', p_appt.id, 'queued', now());
    end if;
  end if;
end;
$fn$;
revoke all on function public.send_new_booking_messages(public.appointments) from public, anon, authenticated;

create or replace function public.queue_new_booking_messages()
returns trigger
language plpgsql security definer set search_path = public as $fn$
begin
  if new.status = 'awaiting_payment' then
    return new; -- nothing goes out until the deposit is paid
  end if;
  perform public.send_new_booking_messages(new);
  perform public.requeue_reminder(new);
  return new;
end;
$fn$;

-- Deposit paid → confirmed: the messages a normal booking got at creation.
-- (The reminder is queued by sync_reminder_on_change on the same update.)
create or replace function public.on_deposit_settled()
returns trigger
language plpgsql security definer set search_path = public as $fn$
begin
  -- Keyed on the payment itself, so it also covers a hold that expired while
  -- the customer was still paying (cancelled → confirmed).
  if new.deposit_paid_at is not null and old.deposit_paid_at is null and new.status in ('pending', 'confirmed') then
    perform public.send_new_booking_messages(new);
  end if;
  return new;
end;
$fn$;

drop trigger if exists trg_on_deposit_settled on public.appointments;
create trigger trg_on_deposit_settled
  after update of status, deposit_paid_at on public.appointments
  for each row execute function public.on_deposit_settled();

-- ----------------------------------------------------------------------------
-- 5) Payments ledger (written by the `payment` Edge Function only)
-- ----------------------------------------------------------------------------
create table if not exists public.payments (
  id             uuid primary key default gen_random_uuid(),
  salon_id       uuid not null references public.salons (id) on delete cascade,
  appointment_id text not null references public.appointments (id) on delete cascade,
  amount_rial    bigint not null,
  authority      text unique,
  status         text not null default 'requested' check (status in ('requested', 'paid', 'failed', 'expired', 'refund_needed')),
  ref_id         text,
  card_pan       text,
  created_at     timestamptz not null default now(),
  paid_at        timestamptz
);
create index if not exists payments_appointment_idx on public.payments (appointment_id);
alter table public.payments enable row level security;
drop policy if exists p_payments_read on public.payments;
create policy p_payments_read on public.payments for select
  using (public.is_manager() and salon_id = public.current_salon_id());
grant select on public.payments to authenticated;

-- ----------------------------------------------------------------------------
-- 6) Release unpaid holds
-- ----------------------------------------------------------------------------
create or replace function public.expire_unpaid_bookings()
returns int
language plpgsql security definer set search_path = public as $fn$
declare v_n int;
begin
  with gone as (
    update public.appointments
       set status = 'cancelled'
     where status = 'awaiting_payment' and created_at < now() - interval '20 minutes'
    returning id
  )
  select count(*) into v_n from gone;
  update public.payments set status = 'expired'
   where status = 'requested' and created_at < now() - interval '20 minutes';
  return v_n;
end;
$fn$;
revoke all on function public.expire_unpaid_bookings() from public, anon, authenticated;
grant execute on function public.expire_unpaid_bookings() to service_role;

-- ----------------------------------------------------------------------------
-- 7) What the booking page needs to know
-- ----------------------------------------------------------------------------
-- Deposit terms for the current salon (the merchant ID itself stays private).
create or replace function public.deposit_terms()
returns json
language sql stable security definer set search_path = public as $fn$
  select json_build_object(
    'enabled', coalesce(s.deposit_percent, 0) > 0 and coalesce(p.zarinpal_merchant_id, '') <> '',
    'percent', coalesce(s.deposit_percent, 0),
    'min_price', coalesce(s.deposit_min_price, 0)
  )
  from (select public.current_salon_id() as salon_id) c
  left join public.app_settings s on s.salon_id = c.salon_id
  left join public.salon_payment_settings p on p.salon_id = c.salon_id;
$fn$;
grant execute on function public.deposit_terms() to anon, authenticated;

-- create_public_booking — as in v2.32, but also returns the stored status
-- (confirmed / pending / awaiting_payment) and the deposit amount.
create or replace function public.create_public_booking(
  p_service_id text, p_staff_id text, p_date date, p_start_min int,
  p_customer_name text, p_customer_phone text, p_customer_gender text,
  p_referral_code text default null
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_svc record; v_wh record; v_app_dow int; v_wh_start int; v_wh_end int;
  v_end_min int; v_id text; v_code text; v_original bigint; v_svc_discount bigint;
  v_after_svc bigint; v_loyalty_pct int := 0; v_final bigint; v_loyalty json; v_code_bytes bytea;
  v_salon_id uuid;
  v_status text; v_deposit bigint;
begin
  v_salon_id := public.current_salon_id();
  if v_salon_id is null then
    return json_build_object('ok', false, 'error', 'سالن نامعتبر است');
  end if;
  if p_customer_phone !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شماره موبایل نامعتبر است');
  end if;
  -- v2.32: a returning customer's name is no longer sent to the browser
  -- (customer_loyalty is PII-free for anonymous callers), so an empty name
  -- falls back to the one already on file for this phone.
  if coalesce(trim(p_customer_name), '') = '' then
    select name into p_customer_name from public.customers where salon_id = v_salon_id and phone = p_customer_phone;
  end if;
  if coalesce(trim(p_customer_name), '') = '' then
    return json_build_object('ok', false, 'error', 'نام لازم است');
  end if;
  if p_customer_gender not in ('female', 'male') then
    return json_build_object('ok', false, 'error', 'جنسیت نامعتبر است');
  end if;
  if not public.check_rate_limit('create_booking:' || v_salon_id || ':' || p_customer_phone, 10, 30) then
    return json_build_object('ok', false, 'error', 'تعداد درخواست بیش از حد مجاز است — کمی بعد دوباره امتحان کنید');
  end if;
  if p_date < current_date then
    return json_build_object('ok', false, 'error', 'تاریخ گذشته قابل انتخاب نیست');
  end if;
  if not exists (select 1 from public.approved_dates where date = p_date and salon_id = v_salon_id) then
    return json_build_object('ok', false, 'error', 'این روز برای رزرو باز نشده است');
  end if;
  if exists (select 1 from public.salon_closures where salon_id = v_salon_id and closure_date = p_date and is_active) then
    return json_build_object('ok', false, 'error', 'سالن در این روز تعطیل است');
  end if;

  select * into v_svc from public.services where id = p_service_id and salon_id = v_salon_id and is_active;
  if v_svc is null then
    return json_build_object('ok', false, 'error', 'خدمت یافت نشد یا غیرفعال است');
  end if;
  if v_svc.gender <> p_customer_gender then
    return json_build_object('ok', false, 'error', 'این خدمت با جنسیت انتخابی مطابقت ندارد');
  end if;

  if p_staff_id is not null and not exists (select 1 from public.stylists where id = p_staff_id and salon_id = v_salon_id and active) then
    return json_build_object('ok', false, 'error', 'آرایشگر یافت نشد یا غیرفعال است');
  end if;

  v_app_dow := (extract(dow from p_date)::int + 1) % 7;
  select * into v_wh from public.working_hours
   where day_of_week = v_app_dow and staff_id = p_staff_id and salon_id = v_salon_id;
  if v_wh is null then
    select * into v_wh from public.working_hours
     where day_of_week = v_app_dow and staff_id is null and salon_id = v_salon_id;
  end if;
  if v_wh is null or v_wh.is_closed then
    return json_build_object('ok', false, 'error', 'در این روز سالن یا آرایشگر تعطیل است');
  end if;
  v_wh_start := split_part(v_wh.start_time, ':', 1)::int * 60 + split_part(v_wh.start_time, ':', 2)::int;
  v_wh_end := split_part(v_wh.end_time, ':', 1)::int * 60 + split_part(v_wh.end_time, ':', 2)::int;
  v_end_min := p_start_min + v_svc.duration_minutes;
  if p_start_min < v_wh_start or v_end_min > v_wh_end then
    return json_build_object('ok', false, 'error', 'خارج از ساعات کاری است');
  end if;

  v_original := coalesce(v_svc.price, 0);
  v_svc_discount := case
    when v_svc.discount_type = 'percent' then round(v_original * v_svc.discount_value / 100.0)
    when v_svc.discount_type = 'fixed' then v_svc.discount_value
    else 0
  end;
  v_after_svc := greatest(0, v_original - v_svc_discount);
  if v_svc.price is not null then
    v_loyalty := public.customer_loyalty(p_customer_phone);
    if (v_loyalty->>'found')::boolean then
      v_loyalty_pct := coalesce((v_loyalty->>'discount_percent')::int, 0);
    end if;
  end if;
  v_final := case when v_svc.price is null then null
                  else greatest(0, v_after_svc - round(v_after_svc * v_loyalty_pct / 100.0)) end;

  v_id := 'apt-' || substr(md5(gen_random_uuid()::text), 1, 16);
  v_code_bytes := gen_random_bytes(4);
  v_code := 'MN-' || lpad((
    ((get_byte(v_code_bytes, 0)::bigint << 24) | (get_byte(v_code_bytes, 1)::bigint << 16)
     | (get_byte(v_code_bytes, 2)::bigint << 8) | get_byte(v_code_bytes, 3)::bigint) % 90000 + 10000
  )::text, 5, '0');

  begin
    insert into public.appointments (
      id, salon_id, customer_name, customer_phone, customer_gender, service_id, staff_id,
      staff_name, date, start_min, end_min, buffer_minutes, status,
      tracking_code, original_price, discount_type, discount_value, discount_reason, final_price
    ) values (
      v_id, v_salon_id, trim(p_customer_name), p_customer_phone, p_customer_gender, p_service_id, p_staff_id,
      coalesce((select name from public.stylists where id = p_staff_id and salon_id = v_salon_id), ''),
      p_date, p_start_min, v_end_min, v_svc.buffer_minutes, 'pending',
      v_code, v_original, v_svc.discount_type, v_svc.discount_value,
      case when v_loyalty_pct > 0 then v_svc.discount_reason || case when v_svc.discount_reason <> '' then ' · ' else '' end || v_loyalty_pct || '٪ تخفیف باشگاه مشتریان' else v_svc.discount_reason end,
      v_final
    )
    returning status, deposit_amount into v_status, v_deposit; -- after the auto-confirm / deposit triggers
  exception when exclusion_violation then
    return json_build_object('ok', false, 'error', 'این زمان قبلاً رزرو شده — زمان دیگری انتخاب کنید');
  end;

  if p_referral_code is not null and length(trim(p_referral_code)) > 0 then
    perform public.apply_referral(p_customer_phone, p_referral_code);
  end if;

  return json_build_object(
    'ok', true, 'id', v_id, 'tracking_code', v_code, 'final_price', v_final,
    'original_price', v_original, 'staff_name', coalesce((select name from public.stylists where id = p_staff_id and salon_id = v_salon_id), ''),
    'status', v_status, 'deposit_amount', v_deposit
  );
end;
$fn$;
grant execute on function public.create_public_booking(text, text, date, int, text, text, text, text) to anon, authenticated;


-- >>>>>>>>>> supabase/migrations/v2.38_review_pass7.sql
-- ============================================================================
-- Migration v2.38 — fixes from review pass 7 (run after v2.37)
-- ============================================================================
--  1. reschedule_my_booking_with_token didn't check the booking's status:
--     a customer could move a cancelled/completed/no-show booking (bringing
--     it back to life) or turn an unpaid deposit hold into a normal booking
--     without paying. Now only live bookings move.
--  2. cancel_my_booking_with_token likewise cancelled anything — including a
--     completed visit, erasing its revenue/loyalty. Now only live bookings
--     (and unpaid holds) can be cancelled.
--  3. Bookings made from links the salon sent (closure rebooking, waitlist
--     offer, predictive invitation) are exempt from the online deposit: the
--     page behind those links has no payment step, so they'd have expired.
-- ============================================================================

create or replace function public.reschedule_my_booking_with_token(
  p_token text, p_appointment_id text, p_new_date date, p_new_start_min int
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_phone text; v_salon_id uuid; v_appt record; v_svc record;
  v_new_end int; v_app_dow int; v_wh record; v_wh_start int; v_wh_end int;
begin
  select r.phone, r.salon_id into v_phone, v_salon_id from public.resolve_booking_token(p_token) r;
  if v_phone is null then
    return json_build_object('ok', false, 'error', 'نشست شما منقضی شده — دوباره وارد شوید');
  end if;

  select * into v_appt from public.appointments where id = p_appointment_id;
  if v_appt is null or v_appt.customer_phone <> v_phone or v_appt.salon_id <> v_salon_id then
    return json_build_object('ok', false, 'error', 'این نوبت متعلق به شما نیست');
  end if;
  -- v2.38: only a live booking can move. Without this, a customer could
  -- "reschedule" a cancelled / completed / no-show booking back to life, or
  -- an unpaid deposit hold into a normal booking without paying.
  if v_appt.status not in ('pending', 'confirmed', 'rescheduled', 'reschedule_proposed') then
    return json_build_object('ok', false, 'error', 'این نوبت دیگر قابل تغییر نیست');
  end if;
  if p_new_date < public.salon_today() then
    return json_build_object('ok', false, 'error', 'تاریخ گذشته قابل انتخاب نیست');
  end if;
  if not exists (select 1 from public.approved_dates where date = p_new_date and salon_id = v_salon_id) then
    return json_build_object('ok', false, 'error', 'این روز برای رزرو باز نشده است');
  end if;

  select * into v_svc from public.services where id = v_appt.service_id and salon_id = v_salon_id;
  if v_svc is null then
    return json_build_object('ok', false, 'error', 'خدمت مرتبط با این نوبت یافت نشد');
  end if;
  v_new_end := p_new_start_min + v_svc.duration_minutes;

  v_app_dow := (extract(dow from p_new_date)::int + 1) % 7;
  select * into v_wh from public.working_hours
   where day_of_week = v_app_dow and staff_id = v_appt.staff_id and salon_id = v_salon_id;
  if v_wh is null then
    select * into v_wh from public.working_hours
     where day_of_week = v_app_dow and staff_id is null and salon_id = v_salon_id;
  end if;
  if v_wh is null or v_wh.is_closed then
    return json_build_object('ok', false, 'error', 'در این روز سالن یا آرایشگر تعطیل است');
  end if;
  v_wh_start := split_part(v_wh.start_time, ':', 1)::int * 60 + split_part(v_wh.start_time, ':', 2)::int;
  v_wh_end := split_part(v_wh.end_time, ':', 1)::int * 60 + split_part(v_wh.end_time, ':', 2)::int;
  if p_new_start_min < v_wh_start or v_new_end > v_wh_end then
    return json_build_object('ok', false, 'error', 'خارج از ساعات کاری است');
  end if;

  begin
    update public.appointments
       set date = p_new_date, start_min = p_new_start_min, end_min = v_new_end,
           status = 'rescheduled', pending_date = null, pending_start_min = null, pending_end_min = null
     where id = p_appointment_id;
  exception when exclusion_violation then
    return json_build_object('ok', false, 'error', 'این زمان قبلاً رزرو شده — زمان دیگری انتخاب کنید');
  end;

  return json_build_object('ok', true);
end;
$fn$;
grant execute on function public.reschedule_my_booking_with_token(text, text, date, int) to anon, authenticated;

create or replace function public.cancel_my_booking_with_token(p_token text, p_appointment_id text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_phone text; v_salon_id uuid; v_owner text; v_owner_salon uuid;
begin
  select r.phone, r.salon_id into v_phone, v_salon_id from public.resolve_booking_token(p_token) r;
  if v_phone is null then
    return json_build_object('ok', false, 'error', 'نشست شما منقضی شده — دوباره وارد شوید');
  end if;
  select customer_phone, salon_id into v_owner, v_owner_salon from public.appointments where id = p_appointment_id;
  if v_owner is null or v_owner <> v_phone or v_owner_salon <> v_salon_id then
    return json_build_object('ok', false, 'error', 'این نوبت متعلق به شما نیست');
  end if;
  -- v2.38: only a live booking (or an unpaid hold) can be cancelled — not a
  -- completed visit (which would erase revenue/loyalty) or a no-show.
  update public.appointments set status = 'cancelled'
   where id = p_appointment_id
     and status in ('pending', 'confirmed', 'rescheduled', 'reschedule_proposed', 'awaiting_payment');
  if not found then
    return json_build_object('ok', false, 'error', 'این نوبت دیگر قابل لغو نیست');
  end if;
  return json_build_object('ok', true);
end;
$fn$;
grant execute on function public.cancel_my_booking_with_token(text, text) to anon, authenticated;

create or replace function public.create_booking_from_rebooking_token(
  p_token text, p_date date, p_start_min int, p_staff_id text default null
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_rt record; v_svc record; v_wh record; v_app_dow int; v_wh_start int; v_wh_end int;
  v_end_min int; v_id text; v_code text; v_original bigint; v_svc_discount bigint;
  v_after_svc bigint; v_loyalty_pct int := 0; v_final bigint; v_loyalty json; v_code_bytes bytea;
  v_staff_id text;
begin
  select * into v_rt from public.rebooking_tokens
   where token_hash = encode(digest(coalesce(p_token, ''), 'sha256'), 'hex')
     and used_at is null and expires_at > now();
  if v_rt is null then
    return json_build_object('ok', false, 'error', 'این لینک منقضی یا نامعتبر است');
  end if;
  if v_rt.service_id is null then
    return json_build_object('ok', false, 'error', 'این لینک برای خدمت مشخصی نیست');
  end if;
  if p_date < current_date then
    return json_build_object('ok', false, 'error', 'تاریخ گذشته قابل انتخاب نیست');
  end if;
  if not exists (select 1 from public.approved_dates where date = p_date and salon_id = v_rt.salon_id) then
    return json_build_object('ok', false, 'error', 'این روز برای رزرو باز نشده است');
  end if;
  if exists (select 1 from public.salon_closures where salon_id = v_rt.salon_id and closure_date = p_date and is_active) then
    return json_build_object('ok', false, 'error', 'سالن در این روز تعطیل است');
  end if;

  -- Staff can be the one the customer originally had, or a different one
  -- the customer actively chooses on the booking page — either way it's
  -- just "who performs the service", not an identity field, so it's safe
  -- to accept as a direct parameter (validated against this same salon).
  v_staff_id := coalesce(p_staff_id, v_rt.staff_id);
  select * into v_svc from public.services where id = v_rt.service_id and salon_id = v_rt.salon_id and is_active;
  if v_svc is null then
    return json_build_object('ok', false, 'error', 'خدمت یافت نشد یا غیرفعال است');
  end if;
  if v_staff_id is not null and not exists (select 1 from public.stylists where id = v_staff_id and salon_id = v_rt.salon_id and active) then
    return json_build_object('ok', false, 'error', 'آرایشگر یافت نشد یا غیرفعال است');
  end if;

  v_app_dow := (extract(dow from p_date)::int + 1) % 7;
  select * into v_wh from public.working_hours
   where day_of_week = v_app_dow and staff_id = v_staff_id and salon_id = v_rt.salon_id;
  if v_wh is null then
    select * into v_wh from public.working_hours
     where day_of_week = v_app_dow and staff_id is null and salon_id = v_rt.salon_id;
  end if;
  if v_wh is null or v_wh.is_closed then
    return json_build_object('ok', false, 'error', 'در این روز سالن یا آرایشگر تعطیل است');
  end if;
  v_wh_start := split_part(v_wh.start_time, ':', 1)::int * 60 + split_part(v_wh.start_time, ':', 2)::int;
  v_wh_end := split_part(v_wh.end_time, ':', 1)::int * 60 + split_part(v_wh.end_time, ':', 2)::int;
  v_end_min := p_start_min + v_svc.duration_minutes;
  if p_start_min < v_wh_start or v_end_min > v_wh_end then
    return json_build_object('ok', false, 'error', 'خارج از ساعات کاری است');
  end if;

  v_original := coalesce(v_svc.price, 0);
  v_svc_discount := case
    when v_svc.discount_type = 'percent' then round(v_original * v_svc.discount_value / 100.0)
    when v_svc.discount_type = 'fixed' then v_svc.discount_value
    else 0
  end;
  v_after_svc := greatest(0, v_original - v_svc_discount);
  if v_svc.price is not null then
    v_loyalty := public.customer_loyalty(v_rt.customer_phone);
    if (v_loyalty->>'found')::boolean then
      v_loyalty_pct := coalesce((v_loyalty->>'discount_percent')::int, 0);
    end if;
  end if;
  v_final := case when v_svc.price is null then null
                  else greatest(0, v_after_svc - round(v_after_svc * v_loyalty_pct / 100.0)) end;

  v_id := 'apt-' || substr(md5(gen_random_uuid()::text), 1, 16);
  v_code_bytes := gen_random_bytes(4);
  v_code := 'MN-' || lpad((
    ((get_byte(v_code_bytes, 0)::bigint << 24) | (get_byte(v_code_bytes, 1)::bigint << 16)
     | (get_byte(v_code_bytes, 2)::bigint << 8) | get_byte(v_code_bytes, 3)::bigint) % 90000 + 10000
  )::text, 5, '0');

  -- v2.38: links the salon itself sent (closure rebooking, waitlist offer,
  -- predictive invitation) never wait for an online deposit — the page
  -- behind them has no payment step. Transaction-local flag read by
  -- hold_for_deposit().
  perform set_config('app.skip_deposit', 'on', true);

  begin
    insert into public.appointments (
      id, salon_id, customer_name, customer_phone, customer_gender, service_id, staff_id,
      staff_name, date, start_min, end_min, buffer_minutes, status,
      tracking_code, original_price, discount_type, discount_value, discount_reason, final_price
    ) values (
      v_id, v_rt.salon_id,
      coalesce(nullif(v_rt.customer_name, ''), (select name from public.customers where salon_id = v_rt.salon_id and phone = v_rt.customer_phone), ''),
      v_rt.customer_phone, v_svc.gender, v_rt.service_id, v_staff_id,
      coalesce((select name from public.stylists where id = v_staff_id and salon_id = v_rt.salon_id), ''),
      p_date, p_start_min, v_end_min, v_svc.buffer_minutes, 'confirmed',
      v_code, v_original, v_svc.discount_type, v_svc.discount_value,
      case when v_loyalty_pct > 0 then v_svc.discount_reason || case when v_svc.discount_reason <> '' then ' · ' else '' end || v_loyalty_pct || '٪ تخفیف باشگاه مشتریان' else v_svc.discount_reason end,
      v_final
    );
  exception when exclusion_violation then
    return json_build_object('ok', false, 'error', 'این زمان قبلاً رزرو شده — زمان دیگری انتخاب کنید');
  end;

  update public.rebooking_tokens set used_at = now() where id = v_rt.id;

  return json_build_object(
    'ok', true, 'id', v_id, 'tracking_code', v_code, 'final_price', v_final,
    'original_price', v_original, 'staff_name', coalesce((select name from public.stylists where id = v_staff_id and salon_id = v_rt.salon_id), '')
  );
end;
$fn$;
grant execute on function public.create_booking_from_rebooking_token(text, date, int, text) to anon, authenticated;

create or replace function public.hold_for_deposit()
returns trigger
language plpgsql security definer set search_path = public as $fn$
declare v_set record; v_merchant text;
begin
  if new.status not in ('pending', 'confirmed') or new.final_price is null or new.final_price <= 0 then
    return new;
  end if;
  if public.is_staff() then
    return new; -- bookings entered by staff never wait for an online payment
  end if;
  if current_setting('app.skip_deposit', true) = 'on' then
    return new; -- booked from a link the salon sent (see create_booking_from_rebooking_token)
  end if;
  select deposit_percent, deposit_min_price into v_set from public.app_settings where salon_id = new.salon_id;
  if coalesce(v_set.deposit_percent, 0) = 0 or new.final_price < coalesce(v_set.deposit_min_price, 0) then
    return new;
  end if;
  select zarinpal_merchant_id into v_merchant from public.salon_payment_settings where salon_id = new.salon_id;
  if coalesce(v_merchant, '') = '' then
    return new;
  end if;
  new.deposit_amount := greatest(1000, round(new.final_price * v_set.deposit_percent / 100.0)); -- Zarinpal minimum is 1,000 toman
  new.status := 'awaiting_payment';
  return new;
end;
$fn$;

-- 4) current_salon_id() cast request.headers to json directly. After a
--    transaction-local set_config (how PostgREST passes headers) the setting
--    reads back as '' — not NULL — on a reused connection, and ''::json
--    raises, failing whatever called it (RLS checks, column defaults).
create or replace function public.current_salon_id() returns uuid
language sql stable security definer set search_path = public as $fn$
  select coalesce(
    (select salon_id from public.users where id = auth.uid()),
    nullif(nullif(current_setting('request.headers', true), '')::json ->> 'x-salon-id', '')::uuid
  );
$fn$;


-- >>>>>>>>>> supabase/migrations/v2.39_reminder_timing.sql
-- ============================================================================
-- Migration v2.39 — reminder timing in the SMS panel (run after v2.38)
-- ============================================================================
-- The "how many hours before the visit" setting for the customer reminder
-- lived only per stylist (stylist edit form). Managers now set it once for
-- the salon in Panel → پیامک, including "off":
--   * app_settings.reminder_hours_before (0 = no reminders);
--   * set_reminder_hours(h) — manager only — saves it, applies it to every
--     stylist of the salon, and moves reminders that are already queued for
--     upcoming bookings to the new time (or drops them when turned off);
--   * requeue_reminder() and the cron-reminders sweep honour "off".
-- A stylist can still adjust their own value afterwards; the salon setting
-- is the default and the off switch.
-- ============================================================================

alter table public.app_settings add column if not exists reminder_hours_before int not null default 3;
alter table public.app_settings drop constraint if exists app_settings_reminder_hours_check;
alter table public.app_settings add constraint app_settings_reminder_hours_check
  check (reminder_hours_before between 0 and 72);

-- Start from what the salon effectively used so far (its stylists' most
-- common value), so upgrading changes nothing by itself.
update public.app_settings s
   set reminder_hours_before = sub.h
  from (
    select salon_id, mode() within group (order by reminder_hours_before) as h
      from public.stylists group by salon_id
  ) sub
 where sub.salon_id = s.salon_id and sub.h between 0 and 72;

create or replace function public.requeue_reminder(p_appt public.appointments)
returns void
language plpgsql security definer set search_path = public as $fn$
declare v_hours int; v_salon_hours int; v_send_at timestamptz;
begin
  update public.sms_messages
     set status = 'cancelled', error = 'superseded: booking changed'
   where appointment_id = p_appt.id and kind = 'reminder' and status = 'queued';

  if p_appt.status not in ('confirmed', 'rescheduled') or p_appt.customer_phone !~ '^09[0-9]{9}$' then
    return;
  end if;

  select reminder_hours_before into v_salon_hours from public.app_settings where salon_id = p_appt.salon_id;
  if coalesce(v_salon_hours, 3) = 0 then
    return; -- reminders turned off for this salon
  end if;
  select reminder_hours_before into v_hours from public.stylists where id = p_appt.staff_id and salon_id = p_appt.salon_id;
  v_hours := coalesce(nullif(v_hours, 0), v_salon_hours, 3);

  v_send_at := ((p_appt.date + make_interval(mins => p_appt.start_min))
                 at time zone coalesce(nullif(current_setting('app.timezone', true), ''), 'Asia/Tehran'))
               - make_interval(hours => v_hours);
  if v_send_at <= now() then
    return; -- window already open: the cron-reminders sweep covers it
  end if;

  insert into public.sms_messages (salon_id, to_phone, body, kind, appointment_id, status, scheduled_for)
  values (p_appt.salon_id, p_appt.customer_phone, public.booking_sms_text(p_appt, 'reminder'),
          'reminder', p_appt.id, 'queued', v_send_at);
end;
$fn$;
revoke all on function public.requeue_reminder(public.appointments) from public, anon, authenticated;

create or replace function public.set_reminder_hours(p_hours int)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_salon uuid := public.current_salon_id(); v_appt public.appointments; v_moved int := 0;
begin
  if not public.is_manager() then
    return json_build_object('ok', false, 'error', 'دسترسی مجاز نیست');
  end if;
  if p_hours is null or p_hours < 0 or p_hours > 72 then
    return json_build_object('ok', false, 'error', 'مقدار نامعتبر است');
  end if;

  update public.app_settings set reminder_hours_before = p_hours where salon_id = v_salon;
  if p_hours > 0 then
    update public.stylists set reminder_hours_before = p_hours where salon_id = v_salon;
  end if;

  -- Re-time every upcoming booking's reminder (requeue_reminder drops the
  -- queued one and queues the new time — or nothing when turned off).
  for v_appt in
    select a.* from public.appointments a
     where a.salon_id = v_salon and a.status in ('confirmed', 'rescheduled')
       and a.date >= public.salon_today()
  loop
    perform public.requeue_reminder(v_appt);
    v_moved := v_moved + 1;
  end loop;

  return json_build_object('ok', true, 'hours', p_hours, 'requeued', v_moved);
end;
$fn$;
grant execute on function public.set_reminder_hours(int) to authenticated;


-- >>>>>>>>>> supabase/migrations/v2.40_tenant_scoping_fixes.sql
-- ============================================================================
-- Migration v2.40 — salon scoping for four older functions (run after v2.39)
-- ============================================================================
-- These SECURITY DEFINER functions predate multi-tenancy (v2.24) and were
-- never given a salon filter. Because they bypass RLS, a manager of one
-- salon could read every salon's data through them:
--   * inactive_customers(days)        — names + phones of other salons' customers
--   * get_customer_category_matrix()  — other salons' customers + visit history
--   * get_campaign_performance()      — campaign stats mixed across salons
--   * track_campaign_conversion       — (trigger) could credit a booking to
--                                       another salon's campaign SMS sent to
--                                       the same phone number
-- Same signatures and result columns as before; only the filters change.
-- ============================================================================

create or replace function public.inactive_customers(p_days int default 60)
returns table (phone text, name text, gender text, last_booking_at timestamptz, days_since int, total_visits int)
language sql stable security definer set search_path = public as $fn$
  select c.phone, c.name, c.gender, c.last_booking_at,
         extract(day from now() - c.last_booking_at)::int, c.total_visits
    from public.customers c
   where public.is_manager()
     and c.salon_id = public.current_salon_id()
     and c.sms_opt_out = false
     and c.last_booking_at is not null
     and c.last_booking_at < now() - make_interval(days => p_days)
   order by c.last_booking_at asc;
$fn$;
revoke all on function public.inactive_customers(int) from public, anon;
grant execute on function public.inactive_customers(int) to authenticated;

create or replace function public.get_customer_category_matrix()
returns table (phone text, name text, category text, category_fa text, visit_count int,
               last_visit_days int, line_status text, line_status_fa text)
language sql stable security definer set search_path = public as $fn$
  with cat_stats as (
    select
      a.customer_phone as phone, c.name, s.category,
      count(a.id)::int as visit_count,
      extract(day from (now() - max(a.date)))::int as last_visit_days
    from public.appointments a
    join public.services s on s.id = a.service_id and s.salon_id = a.salon_id
    join public.customers c on c.phone = a.customer_phone and c.salon_id = a.salon_id
    where a.status = 'completed'
      and a.salon_id = public.current_salon_id()
    group by a.customer_phone, c.name, s.category
  )
  select
    phone, name, category,
    case category
      when 'hair' then 'مو' when 'beard' then 'ریش' when 'color' then 'رنگ'
      when 'makeup' then 'میکاپ' when 'nails' then 'ناخن' when 'skin' then 'پوست'
      when 'permanent_makeup' then 'خدمات دائم' else category
    end as category_fa,
    visit_count, last_visit_days,
    case when last_visit_days <= 45 then 'active' when last_visit_days <= 90 then 'at_risk' else 'dormant' end as line_status,
    case when last_visit_days <= 45 then 'فعال در این خط خدمت'
         when last_visit_days <= 90 then 'در خطر ریزش در این خط خدمت'
         else 'غیرفعال در این خط خدمت' end as line_status_fa
  from cat_stats
  where public.is_manager()
  order by phone, category;
$fn$;
revoke all on function public.get_customer_category_matrix() from public, anon;
grant execute on function public.get_customer_category_matrix() to authenticated;

create or replace function public.get_campaign_performance(p_template_id text default null)
returns table (template_id text, template_label text, segment text, total_sent bigint,
               successful_count bigint, total_conversions bigint, conversion_rate numeric,
               attributed_revenue bigint)
language sql stable security definer set search_path = public as $fn$
  select
    cl.template_id,
    max(cl.template_label) as template_label,
    max(cl.segment) as segment,
    sum(cl.total_sent)::bigint as total_sent,
    sum(cl.successful_count)::bigint as successful_count,
    count(distinct cc.id)::bigint as total_conversions,
    case when sum(cl.successful_count) = 0 then 0::numeric
         else round(count(distinct cc.id)::numeric / sum(cl.successful_count) * 100, 1)
    end as conversion_rate,
    coalesce(sum(a.final_price) filter (where a.status = 'completed'), 0)::bigint as attributed_revenue
  from public.campaign_logs cl
  left join public.campaign_conversions cc on cc.campaign_log_id = cl.id
  left join public.appointments a on a.id = cc.appointment_id
  where public.is_manager()
    and cl.salon_id = public.current_salon_id()
    and (p_template_id is null or cl.template_id = p_template_id)
  group by cl.template_id
  order by conversion_rate desc;
$fn$;
revoke all on function public.get_campaign_performance(text) from public, anon;
grant execute on function public.get_campaign_performance(text) to authenticated;

create or replace function public.track_campaign_conversion()
returns trigger
language plpgsql security definer set search_path = public as $fn$
declare matched_sms record;
begin
  if new.customer_phone !~ '^09[0-9]{9}$' then
    return new;
  end if;

  -- Most recent campaign SMS this salon sent to this phone in the last 7 days.
  select sm.id as sms_id, sm.campaign_log_id, sm.sent_at
    into matched_sms
    from public.sms_messages sm
   where sm.to_phone = new.customer_phone
     and sm.salon_id = new.salon_id
     and sm.campaign_log_id is not null
     and sm.status in ('sent', 'delivered')
     and sm.sent_at >= now() - interval '7 days'
   order by sm.sent_at desc
   limit 1;

  if matched_sms.campaign_log_id is not null then
    insert into public.campaign_conversions
      (salon_id, campaign_log_id, customer_phone, appointment_id, sms_message_id, converted_at, days_to_convert)
    values (
      new.salon_id, matched_sms.campaign_log_id, new.customer_phone, new.id, matched_sms.sms_id, now(),
      greatest(0, extract(day from (now() - matched_sms.sent_at))::int)
    )
    on conflict (appointment_id) do nothing;
  end if;

  return new;
end;
$fn$;
revoke all on function public.track_campaign_conversion() from public, anon, authenticated;


-- >>>>>>>>>> supabase/migrations/v2.41_multi_salon_platform.sql
-- ============================================================================
-- Migration v2.41 — running many salons on one installation (run after v2.40)
-- ============================================================================
-- 1. Platform admin: a small set of accounts (platform_admins) that can create
--    salons, bind each to its owner's phone, and activate/deactivate them —
--    no SQL needed per salon. Bootstrap the first admin once (INSTALL.md).
-- 2. Owner binding: a salon created by the admin carries owner_phone; only
--    that phone can register as its manager. Before this, whoever signed up
--    first at a fresh salon's address became its owner.
-- 3. Deactivated salons are off for everyone: current_salon_id() resolves
--    only active salons, so public booking AND the staff panel stop.
-- 4. Each salon's own SMS account (provider, API key, sender line). The key
--    is write-only from the app; only the Edge Functions (service role) read it.
-- 5. Waitlist: an anonymous visitor could read every salon's waitlist (names,
--    phones), and the public "join waitlist" write never worked (the client's
--    upsert needs UPDATE, which anon doesn't have). Joining now goes through
--    join_waitlist(); only staff can read the list.
-- 6. Feedback rows take their salon from the booking, not the request header.
-- ============================================================================

-- ---------------------------------------------------------------- salons ----
alter table public.salons add column if not exists owner_phone text;
alter table public.salons drop constraint if exists salons_owner_phone_check;
alter table public.salons add constraint salons_owner_phone_check check (owner_phone is null or owner_phone ~ '^09[0-9]{9}$');

-- Public pages need id/slug/name only; owner_phone stays private.
revoke select on public.salons from anon, authenticated;
grant select (id, slug, name, active, created_at) on public.salons to anon, authenticated;

-- ------------------------------------------------------ platform admins ----
create table if not exists public.platform_admins (
  user_id    uuid primary key references auth.users(id) on delete cascade,
  created_at timestamptz not null default now()
);
alter table public.platform_admins enable row level security;
revoke all on public.platform_admins from public, anon, authenticated;

create or replace function public.is_platform_admin()
returns boolean
language sql stable security definer set search_path = public as $fn$
  select exists (select 1 from public.platform_admins where user_id = auth.uid());
$fn$;
revoke all on function public.is_platform_admin() from public, anon;
grant execute on function public.is_platform_admin() to authenticated;

-- ------------------------------------------- active salons only (tenancy) ---
create or replace function public.current_salon_id()
returns uuid
language sql stable security definer set search_path = public as $fn$
  select s.id
    from public.salons s
   where s.active
     and s.id = coalesce(
       (select salon_id from public.users where id = auth.uid()),
       nullif(nullif(current_setting('request.headers', true), '')::json ->> 'x-salon-id', '')::uuid
     );
$fn$;

-- ------------------------------------------------ owner phone binding ------
create or replace function public.guard_user_self_insert()
returns trigger
language plpgsql security definer set search_path = public as $fn$
declare v_st record; v_owner_phone text;
begin
  -- Only the app's own sign-up path (a user creating their own profile).
  if auth.uid() is null or new.id <> auth.uid() then
    return new;
  end if;

  if new.role in ('owner', 'manager') then
    select owner_phone into v_owner_phone from public.salons where id = new.salon_id;
    if v_owner_phone is not null then
      -- v2.41: salons created from the platform panel name their owner.
      if new.phone is distinct from v_owner_phone then
        raise exception 'این شماره به‌عنوان مدیر این سالن ثبت نشده است' using errcode = '42501';
      end if;
      new.role := 'owner';
    end if;
    if exists (
      select 1 from public.users u
       where u.salon_id = new.salon_id and u.role in ('owner', 'manager') and u.id <> new.id
    ) then
      raise exception 'این سالن قبلاً مدیر دارد — برای دسترسی مدیریتی از مدیر فعلی بخواهید'
        using errcode = '42501';
    end if;
  elsif new.role = 'stylist' then
    select * into v_st from public.stylists s
     where s.id = new.stylist_id and s.salon_id = new.salon_id and s.phone = new.phone;
    if v_st.id is null or exists (
      select 1 from public.users u where u.stylist_id = new.stylist_id and u.salon_id = new.salon_id and u.id <> new.id
    ) then
      raise exception 'پروفایل آرایشگر با این شماره پیدا نشد' using errcode = '42501';
    end if;
    if v_st.self_registered and not v_st.active then
      new.active := false;
    end if;
  end if;
  return new;
end;
$fn$;

-- --------------------------------------------- per-salon SMS account -------
create table if not exists public.salon_sms_settings (
  salon_id   uuid primary key references public.salons(id) on delete cascade,
  provider   text not null check (provider in ('kavenegar', 'melipayamak')),
  api_key    text not null,
  sender     text not null default '',
  updated_at timestamptz not null default now()
);
alter table public.salon_sms_settings enable row level security;
revoke all on public.salon_sms_settings from public, anon, authenticated;
-- (no policies: only the service role — the Edge Functions — reads it)

-- -------------------------------------------------------- admin RPCs -------
create or replace function public.admin_create_salon(p_slug text, p_name text, p_owner_phone text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_slug text := lower(trim(coalesce(p_slug, ''))); v_id uuid;
begin
  if not public.is_platform_admin() then
    return json_build_object('ok', false, 'error', 'دسترسی مجاز نیست');
  end if;
  if v_slug !~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$' then
    return json_build_object('ok', false, 'error', 'آدرس فقط حروف کوچک انگلیسی، عدد و خط تیره');
  end if;
  if v_slug in ('admin', 'feedback', 'book', 'confirm', 'payment', 'reconcile', 'api', 'assets', 'default-new') then
    return json_build_object('ok', false, 'error', 'این آدرس رزرو شده است');
  end if;
  if coalesce(trim(p_name), '') = '' then
    return json_build_object('ok', false, 'error', 'نام سالن لازم است');
  end if;
  if coalesce(p_owner_phone, '') !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شمارهٔ موبایل مدیر نامعتبر است');
  end if;
  if exists (select 1 from public.salons where slug = v_slug) then
    return json_build_object('ok', false, 'error', 'این آدرس قبلاً استفاده شده');
  end if;

  insert into public.salons (slug, name, owner_phone) values (v_slug, trim(p_name), p_owner_phone)
  returning id into v_id;
  -- trg_provision_salon_defaults adds app/loyalty/segment settings; open the
  -- booking window right away so the salon is bookable once it has hours.
  return json_build_object('ok', true, 'id', v_id, 'slug', v_slug);
end;
$fn$;

create or replace function public.admin_update_salon(p_id uuid, p_name text default null, p_owner_phone text default null, p_active boolean default null)
returns json
language plpgsql security definer set search_path = public as $fn$
begin
  if not public.is_platform_admin() then
    return json_build_object('ok', false, 'error', 'دسترسی مجاز نیست');
  end if;
  if p_owner_phone is not null and p_owner_phone !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شمارهٔ موبایل مدیر نامعتبر است');
  end if;
  update public.salons
     set name = coalesce(nullif(trim(p_name), ''), name),
         owner_phone = coalesce(p_owner_phone, owner_phone),
         active = coalesce(p_active, active)
   where id = p_id;
  if not found then
    return json_build_object('ok', false, 'error', 'سالن پیدا نشد');
  end if;
  return json_build_object('ok', true);
end;
$fn$;

-- One row per salon with what the platform owner needs to run 300+ of them:
-- is it set up, is it used, is its SMS working.
create or replace function public.admin_list_salons()
returns table (
  id uuid, slug text, name text, active boolean, owner_phone text, created_at timestamptz,
  owner_registered boolean, stylists int, services int,
  bookings_30d int, completed_30d int, last_booking_date date,
  sms_configured boolean, sms_sent_30d int, sms_failed_30d int
)
language sql stable security definer set search_path = public as $fn$
  select s.id, s.slug, s.name, s.active, s.owner_phone, s.created_at,
         exists (select 1 from public.users u where u.salon_id = s.id and u.role in ('owner', 'manager')),
         (select count(*)::int from public.stylists t where t.salon_id = s.id and t.active),
         (select count(*)::int from public.services v where v.salon_id = s.id and v.is_active),
         (select count(*)::int from public.appointments a where a.salon_id = s.id and a.date >= current_date - 30),
         (select count(*)::int from public.appointments a where a.salon_id = s.id and a.date >= current_date - 30 and a.status = 'completed'),
         (select max(a.date) from public.appointments a where a.salon_id = s.id),
         exists (select 1 from public.salon_sms_settings x where x.salon_id = s.id),
         (select count(*)::int from public.sms_messages m where m.salon_id = s.id and m.created_at >= now() - interval '30 days' and m.status in ('sent', 'delivered')),
         (select count(*)::int from public.sms_messages m where m.salon_id = s.id and m.created_at >= now() - interval '30 days' and m.status = 'failed')
    from public.salons s
   where public.is_platform_admin()
   order by s.created_at desc;
$fn$;

create or replace function public.get_sms_account()
returns json
language sql stable security definer set search_path = public as $fn$
  select case when not public.is_manager() then json_build_object('ok', false)
  else coalesce(
    (select json_build_object('ok', true, 'configured', true, 'provider', provider, 'sender', sender,
                              'key_hint', right(api_key, 4), 'updated_at', updated_at)
       from public.salon_sms_settings where salon_id = public.current_salon_id()),
    json_build_object('ok', true, 'configured', false))
  end;
$fn$;

-- p_api_key empty = keep the saved key (change provider line/sender only).
create or replace function public.set_sms_account(p_provider text, p_api_key text, p_sender text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_salon uuid := public.current_salon_id(); v_key text := nullif(trim(coalesce(p_api_key, '')), '');
begin
  if not public.is_manager() or v_salon is null then
    return json_build_object('ok', false, 'error', 'دسترسی مجاز نیست');
  end if;
  if p_provider = 'none' then
    delete from public.salon_sms_settings where salon_id = v_salon;
    return json_build_object('ok', true, 'configured', false);
  end if;
  if p_provider not in ('kavenegar', 'melipayamak') then
    return json_build_object('ok', false, 'error', 'سرویس پیامک نامعتبر است');
  end if;
  if v_key is not null and length(v_key) < 8 then
    return json_build_object('ok', false, 'error', 'کلید API نامعتبر به نظر می‌رسد');
  end if;
  if v_key is null and not exists (select 1 from public.salon_sms_settings where salon_id = v_salon) then
    return json_build_object('ok', false, 'error', 'کلید API لازم است');
  end if;
  update public.salon_sms_settings
     set provider = p_provider, api_key = coalesce(v_key, api_key),
         sender = coalesce(trim(p_sender), ''), updated_at = now()
   where salon_id = v_salon;
  if not found then
    insert into public.salon_sms_settings (salon_id, provider, api_key, sender)
    values (v_salon, p_provider, v_key, coalesce(trim(p_sender), ''));
  end if;
  insert into public.audit_log (salon_id, actor, event, detail)
  values (v_salon, auth.uid(), 'sms_account_updated', jsonb_build_object('provider', p_provider));
  return json_build_object('ok', true, 'configured', true);
end;
$fn$;

-- ---------------------------------------------------------- waitlist -------
drop policy if exists p_wait_select on public.waitlist;
create policy p_wait_select on public.waitlist for select using (salon_id = public.current_salon_id() and public.is_staff());
drop policy if exists p_wait_insert on public.waitlist;
create policy p_wait_insert on public.waitlist for insert with check (salon_id = public.current_salon_id() and public.is_staff());
revoke insert, select, update, delete on public.waitlist from anon;

create or replace function public.join_waitlist(p_date date, p_service_id text, p_staff_id text,
                                                p_name text, p_phone text, p_gender text default null)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_salon uuid := public.current_salon_id(); v_staff_name text;
begin
  if v_salon is null then
    return json_build_object('ok', false, 'error', 'سالن نامعتبر است');
  end if;
  if coalesce(p_phone, '') !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شمارهٔ موبایل نامعتبر است');
  end if;
  if coalesce(trim(p_name), '') = '' or length(p_name) > 80 then
    return json_build_object('ok', false, 'error', 'نام را وارد کنید');
  end if;
  if p_date is null or p_date < public.salon_today() or p_date > public.salon_today() + 90 then
    return json_build_object('ok', false, 'error', 'تاریخ نامعتبر است');
  end if;
  if not exists (select 1 from public.services where id = p_service_id and salon_id = v_salon and is_active) then
    return json_build_object('ok', false, 'error', 'خدمت پیدا نشد');
  end if;
  if p_staff_id is not null then
    select name into v_staff_name from public.stylists where id = p_staff_id and salon_id = v_salon and active;
    if v_staff_name is null then
      return json_build_object('ok', false, 'error', 'آرایشگر پیدا نشد');
    end if;
  end if;
  if not public.check_rate_limit('waitlist:' || p_phone, 10, 60) then
    return json_build_object('ok', false, 'error', 'تعداد درخواست‌ها زیاد است؛ کمی بعد دوباره تلاش کنید');
  end if;
  -- Same person, same day/service/stylist: already on the list.
  if exists (select 1 from public.waitlist w
              where w.salon_id = v_salon and w.customer_phone = p_phone and w.date = p_date
                and w.service_id = p_service_id and w.staff_id is not distinct from p_staff_id) then
    return json_build_object('ok', true, 'already', true);
  end if;

  insert into public.waitlist (id, salon_id, date, customer_name, customer_phone, customer_gender, service_id, staff_id, staff_name)
  values ('wl-' || encode(gen_random_bytes(8), 'hex'), v_salon, p_date, trim(p_name), p_phone,
          coalesce(nullif(p_gender, ''), (select gender from public.services where id = p_service_id), 'female'),
          p_service_id, p_staff_id, coalesce(v_staff_name, ''));
  return json_build_object('ok', true);
end;
$fn$;
revoke all on function public.join_waitlist(date, text, text, text, text, text) from public;
grant execute on function public.join_waitlist(date, text, text, text, text, text) to anon, authenticated;

